INSERT INTO lex.ingested_documents (external_id, doc_type, source_system, title, body, meta, organized, crawl_batch_id, content_hash)
VALUES
  ('cpiuris2025::ce6c6b1e15549f3ca0173ebd7cc1ae87', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Designação de locais de votação e seções eleitorais', '## Designação de locais de votação e seções eleitorais

A legislação estabelece regras para a designação de locais de votação e seções eleitorais, incluindo a proibição de designar propriedades rurais como locais de votação.

### Conceitos
- **Designação de local de votação**: A escolha do local onde os eleitores irão votar
- **Seção eleitoral**: Unidade administrativa responsável pela organização das eleições em uma determinada área
- **Propriedade rural**: Terras rurais que fazem parte de um imóvel
- **Edifício público**: Estrutura construída pelo Estado ou por entidades públicas para fins específicos

### Referências legais
- Art. 15 da Lei nº 4.737/1965

### Dicas de prova
- Distinção entre propriedades rurais e edifícios públicos
- Importância da designação de locais de votação adequados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.173", "page_number": 173, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 15 da Lei nº 4.737/1965"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:58:19.140009+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=173", "doc_key": "ce6c6b1e15549f3ca0173ebd7cc1ae87"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '094b3f95c534ed708e1ab007b5e06bf3cd96de5ed13b70e8edb936d34e490bcf'),
  ('cpiuris2025::060f8ef79e2c9e66a1767ece6f20d475', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Localização de seções eleitorais', '## Localização de seções eleitorais

A localização de seções eleitorais é regulamentada pelo Código Eleitoral, proibindo-se suas instalações em propriedades rurais privadas e vedando o uso de imóveis pertencentes a autoridades policiais. Além disso, as resoluções do TSE estabelecem a possibilidade de instalar seções eleitorais em estabelecimentos penais e unidades de internação.

### Conceitos
- **Código Eleitoral**: Lei que regula o processo eleitoral no Brasil
- **Propriedade rural privada**: Imóvel rurário não pertencente ao Estado ou a entidades públicas
- **Autoridade policial**: Pessoas físicas ou jurídicas que exercem poderes de controle e aplicação da lei
- **Tribunal Regional Eleitoral (TSE)**: Entidade responsável por organizar as eleições no Brasil
- **Mesa Receptora**: Comissão que recebe os votos dos eleitores

### Referências legais
- Art. 135, § 5º; Art. 135, § 4º; Art. 64 da Lei n.º 9.504/97; Art. 120, § 2º do Código Eleitoral

### Jurisprudência
- RE 123456
- Resolução n.º 23.554/2017 do TSE

### Dicas de prova
- Entenda a importância da localização de seções eleitorais e como elas são regulamentadas pelo Código Eleitoral.
- Conheça as exceções à regra geral e como o TSE estabelece novas regras para a organização das eleições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 135, § 5º; Art. 135, § 4º; Art. 64 da Lei n.º 9.504/97; Art. 120, § 2º do Código Eleitoral"], "jurisprudence": ["RE 123456", "Resolução n.º 23.554/2017 do TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T00:59:02.352618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=174", "doc_key": "060f8ef79e2c9e66a1767ece6f20d475"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '350f3f80aebf88c99dc4aa4c6605d3f24a20a321c5e29c531f3d719cb96d5874'),
  ('cpiuris2025::290bc83d6ae65482c0edb9de610c7d93', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Redução do número de membros das Mesas Receptoras', '## Redução do número de membros das Mesas Receptoras

A redução para 2 membros não é permitida, pois o artigo 120 do Código Eleitoral estabelece a composição da mesa. Além disso, o artigo 63, § 2º, da Lei n.º 9.504/97 proíbe a nomeação de menores de 18 anos para essas funções.

### Conceitos
- **Mesa Receptora**: Composição da mesa responsável por receber os votos
- **Art. 120 do Código Eleitoral**: Estabelece a composição das Mesas Receptoras
- **Art. 63, § 2º, da Lei n.º 9.504/97**: Proíbe a nomeação de menores de 18 anos para funções eleitorais

### Referências legais
- Art. 120 do Código Eleitoral
- Art. 63, § 2º, da Lei n.º 9.504/97

### Dicas de prova
- Entenda a composição das Mesas Receptoras e as restrições impostas pela legislação eleitoral
- Diferencie entre os artigos mencionados e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 120 do Código Eleitoral", "Art. 63, § 2º, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:59:43.217921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=174", "doc_key": "290bc83d6ae65482c0edb9de610c7d93"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'fd7b203aa76df09d4bb4df67f3b7a86cd711dcfa2c090161923441f5acb9ecc8'),
  ('cpiuris2025::db7a38f7e23ee8cbe29a0020a8a7e46a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Proibição de direitos do eleitor após a eleição', '## Proibição de direitos do eleitor após a eleição

A lei proíbe que os eleitores recebam vencimentos, remuneração ou outros benefícios após a eleição, exceto se comprovada a participação no pleito.

### Conceitos
- **Proibição de direitos do eleitor**: A lei proíbe que os eleitores recebam vencimentos, remuneração ou outros benefícios após a eleição.
- **Vedação ao parcelamento de IPTU**: Não é considerada uma hipótese prevista expressamente pela lei.
- **Prova do voto**: É necessária para justificar o recebimento de benefícios após a eleição.
- **Pagamento da multa**: Também é necessário para justificar o recebimento de benefícios após a eleição.
- **Benefícios governamentais**: Incluem valores de fundações, empresas e institutos mantidos ou subvencionados pelo governo.

### Referências legais
- Art. 7º, § 1º, do Código Eleitoral

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinguir entre benefícios públicos e privados.
- Entender a importância da prova do voto para justificar o recebimento de benefícios após a eleição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.175", "page_number": 175, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º, § 1º, do Código Eleitoral"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T01:00:15.969351+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=175", "doc_key": "db7a38f7e23ee8cbe29a0020a8a7e46a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '05c3ed8da87a2f19befa3b5c6b6ab4b9d97230597a6c6b5cf6269608bc31fcf2'),
  ('cpiuris2025::05cf40906206a42ffa59fb734359f837', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Garantias Eleitorais', '## Garantias Eleitorais

Ninguém pode impedir ou embaraçar o exercício do sufrágio. O eleitor que sofrer violência pode receber salvo-conduto com prisão por desobediência até cinco dias.

### Conceitos
- **Salvo-conduto**: Documento que protege o eleitor de prisão por desobediência
- **Desobediência**: Ação ilegal que pode resultar em prisão por desobediência
- **Garantia Eleitoral**: Direito do eleitor a exercer seu voto sem medo de violência ou repressão

### Referências legais
- Art. 234 do Código Eleitoral
- Art. 235 do Código Eleitoral
- Art. 236 do Código Eleitoral

### Dicas de prova
- Entenda a diferença entre salvo-conduto e desobediência
- Conheça as garantias eleitorais previstas no Código Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.177", "page_number": 177, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 234 do Código Eleitoral", "Art. 235 do Código Eleitoral", "Art. 236 do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:00:42.440344+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=177", "doc_key": "05cf40906206a42ffa59fb734359f837"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '250852ae187ef653b5e8dfdd47f3400992edc155832e8498954e6483abbf8146'),
  ('cpiuris2025::8bb846f9334ffacdace4a82340d28b0d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ação de Impugnação ao Registro de Candidatura (AIRC)', '## Ação de Impugnação ao Registro de Candidatura (AIRC)

Ação que reconhece judicialmente a inelegibilidade do candidato, impedindo sua candidatura.

### Conceitos
- **Legitimidade Ativa**: Os candidatos, partidos políticos, coligações e Ministério Público Eleitoral têm legitimidade para ajuizar AIRC.
- **Legitimidade Passiva**: Os pré-candidatos que incorreram em alguma causa de inelegibilidade ou não cumpriram condições de elegibilidade são legitimados passivos.
- **Contraditório e Ampla Defesa**: O Juiz Eleitoral pode conhecer de ofício da existência de causas de inelegibilidade ou ausência de condição de elegibilidade, resguardando o contraditório e a ampla defesa.
- **Representação Processual**: O impugnante deve ter representação processual por advogado ou advogada constituída por procuração nos autos.

### Referências legais
- Art. 3º e seguintes da LC n.º 64/90

### Jurisprudência
- Súmula n.º 45, do TSE
- Súmula n.º 11, do TSE

### Dicas de prova
- Distinguir entre legitimidade ativa e passiva para ajuizar AIRC.
- Conhecer as condições de elegibilidade e causas de inelegibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.179", "page_number": 179, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 3º e seguintes da LC n.º 64/90"], "jurisprudence": ["Súmula n.º 45, do TSE", "Súmula n.º 11, do TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T01:01:30.184100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=179", "doc_key": "8bb846f9334ffacdace4a82340d28b0d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '41a01ff72bbc994448b1c3544d898959b5ca3e01daf1a7e615228e879ba429b0'),
  ('cpiuris2025::a11c3e855f8f7a9a15eaf45ad90ac5f3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ação Inicial de Recurso contra o Registro de Candidatura (AIRC)', '## Ação Inicial de Recurso contra o Registro de Candidatura (AIRC)

Regras e procedimentos para a propositura da AIRC, incluindo prazo, competência, procedimento e testemunhas.

### Conceitos
- **Litisconsórcio**: Condição em que duas ou mais pessoas são responsáveis pelo mesmo ato jurídico
- **Prazo para interposição**: Deve ser de cinco dias, a contar da data da publicação do edital com a relação nominal dos pedidos de registro de candidatura
- **Competência**: Dependerá do cargo pleiteado pelo pré-candidato
- **Procedimento**: Proposta da AIRC, os legitimados ativos devem especificar os meios de provas que pretendem produzir

### Referências legais
- Art. 3º da LC n.º 64/90
- Súmula n.º 39 do TSE
- Súmula n.º 49 do TSE

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de litisconsórcio e sua aplicação na AIRC
- Conheça o prazo para interposição da AIRC e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.180", "page_number": 180, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 3º da LC n.º 64/90", "Súmula n.º 39 do TSE", "Súmula n.º 49 do TSE"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:02:05.825173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=180", "doc_key": "a11c3e855f8f7a9a15eaf45ad90ac5f3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e7d4cc6583d6382fd2043a0bc786928f01fb9941f764cc7c4ec66babedfccdcf'),
  ('cpiuris2025::7477a8c3522d9321dcde82856d5552fd', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Procedimento para encerramento do prazo e julgamento das ações eleitorais', '## Procedimento para encerramento do prazo e julgamento das ações eleitorais

Descreve o procedimento para encerramento do prazo de registro de candidatos, julgamento das ações eleitorais e abuso de poder econômico ou político.

### Conceitos
- **Prazo peremptório**: Prazo que não pode ser suspenso ou interrompido
- **Regra do art. 10 da LC n.º 64/90**: Aplica-se a regra para eleições gerais, estabelecendo prazos contínuos e peremptórios
- **Abuso de poder econômico ou político**: Exercício do poder em afronta à lei, que pode ser econômico ou político

### Referências legais
- Art. 10 da LC n.º 64/90
- Art. 16 da LC n.º 64/90
- Art. 22 da LC n.º 64/90

### Dicas de prova
- Pegar a definição de prazo peremptório e regra do art. 10 da LC n.º 64/90
- Distinção entre abuso de poder econômico ou político', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.181", "page_number": 181, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 10 da LC n.º 64/90", "Art. 16 da LC n.º 64/90", "Art. 22 da LC n.º 64/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:02:42.511285+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=181", "doc_key": "7477a8c3522d9321dcde82856d5552fd"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8033a4b9880114c6c8ee02a673a9c4941980eaefaf356dab4449f5c4a21c868a'),
  ('cpiuris2025::957439bba157a036ecde8685736a6ee2', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Abuso do Poder Político e Econômico nas Campanhas Eleitorais', '## Abuso do Poder Político e Econômico nas Campanhas Eleitorais

O abuso do poder político ou econômico se caracteriza pela utilização ilícita de recursos públicos em prol de determinado candidato, utilizando-se da condição funcional para beneficiar a própria candidatura ou a de outrem. Isso pode incluir manipulação de receitas orçamentárias, propaganda institucional e contratação ilícita de pessoal.

### Conceitos
- **Abuso do Poder Político**: Utilização ilícita de recursos públicos em prol de determinado candidato
- **Abuso de Autoridade**: Prevalência da condição funcional para beneficiar a própria candidatura ou a de outrem
- **Manipulação de Receitas Orçamentárias**: Utilização indevida de receitas orçamentárias para benefício da campanha
- **Propaganda Institucional**: Utilização indevida de propaganda institucional para benefício da campanha
- **Contratação Ilícita de Pessoal**: Contratação de pessoal sem a devida justificativa ou sem respeito aos procedimentos estabelecidos
- **Abuso do Poder Econômico**: Utilização inadequada de recursos patrimoniais controlados pelo agente para benefício da campanha
- **Doações a Candidatos e Partidos por Instituições Religiosas**: Vedação de doações a candidatos e partidos por instituições religiosas
- **Propaganda Política em Templos**: Proibição da propaganda política em templos

### Referências legais
- Art. 14, §5º, da Constituição Federal
- Lei n.º 9.504/97

### Jurisprudência
- {''RE'': ''Respe n.º 82-85.2016.6.09.0139''}
- {''Tema Repetitivo'': ''Abuso de Poder Religioso''}

### Dicas de prova
- Distinção entre abuso do poder político e econômico
- Manipulação de receitas orçamentárias e propaganda institucional
- Contratação ilícita de pessoal e uso indevido de recursos patrimoniais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14, §5º, da Constituição Federal", "Lei n.º 9.504/97"], "jurisprudence": ["{''RE'': ''Respe n.º 82-85.2016.6.09.0139''}", "{''Tema Repetitivo'': ''Abuso de Poder Religioso''}"], "confidence": 0.8, "extracted_at": "2026-05-27T01:03:44.719159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=182", "doc_key": "957439bba157a036ecde8685736a6ee2"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6834a8fecf6c5bf61c2b77de484e043769670cd65a3b262518463b1d4d7be0ce'),
  ('cpiuris2025::e95836df0554475272c804482dc19798', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Abuso de poder religioso no processo eleitoral', '## Abuso de poder religioso no processo eleitoral

O Plenário do TSE deu provimento a recurso especial e julgou prejudicado o agravo regimental interposto pelo MPE, rejeitando a proposta de fixação de tese sobre possibilidade de exame jurídico do abuso de poder de autoridade religiosa em sede de Ações de Investigação Judicial Eleitoral.

### Conceitos
- **Abuso de poder**: Uso indevido de poder para prejudicar alguém
- **Autoridade religiosa**: Pessoa ou entidade que exerce influência sobre a fé e a conduta de uma comunidade
- **Liberdade de voto**: Direito do eleitor de escolher seu candidato preferido
- **Legitimidade do processo eleitoral**: Integridade e confiabilidade do processo de seleção dos representantes

### Referências legais
- Art. 5º, caput, da CF; Art. 14 da Lei nº 4.737/1965

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Diferenciar entre abuso de poder econômico e político
- Entender a importância da liberdade de voto e legitimidade do processo eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º, caput, da CF; Art. 14 da Lei nº 4.737/1965"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T01:04:16.646413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=182", "doc_key": "e95836df0554475272c804482dc19798"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'cc7f478245add134246cd81f67e8588be2bc5a562a9b3a13a2b935f6a8569d1f'),
  ('cpiuris2025::528c65c77d450dafa025a498913ab744', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Legitimidade para propor Ação Inicial de Investigação Eleitoral (AIJE)', '## Legitimidade para propor Ação Inicial de Investigação Eleitoral (AIJE)

A AIJE pode ser proposta por candidato, partido político, coligação ou Ministério Público Eleitoral. O eleitor não tem legitimidade para propor a AIJE, mas pode noticiar atos abusivos ao MP Eleitoral ou Juiz Eleitoral.

### Conceitos
- **Legitimidade**: O direito de agir em um processo ou ação
- **Ação Inicial de Investigação Eleitoral (AIJE)**: Procedimento para investigar atos abusivos em eleições
- **Litisconsórcio**: Ocorrência de mais de um legitimado propondo a AIJE
- **Procurador**: Pessoa autorizada a representar uma parte em um processo

### Referências legais
- Art. 22, XVI, da LC n.º 64/90
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a noção de legitimidade para propor AIJE
