  ('cpiuris2025::18b2d9fc8cbf8083f9bbe2106ffa4cf0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações Eleitorais e Investigatórias (AIJE)', '## Ações Eleitorais e Investigatórias (AIJE)

Regras para a propositura de ações eleitorais, incluindo competência e prazo.

### Conceitos
- **Litisconsórcio**: Conexão necessária entre as partes em uma ação
- **Competência**: Atribuição da competência para julgar um feito
- **Prazo**: Período dentro do qual deve ser proposta a ação

### Referências legais
- Art. 22 da LC n.º 64/90
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de litisconsórcio necessário e como ele se aplica às ações eleitorais.
- Conheça as regras de competência para a propositura das ações eleitorais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22 da LC n.º 64/90", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:05:28.351994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=184", "doc_key": "18b2d9fc8cbf8083f9bbe2106ffa4cf0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '312413828178309d53a037a7ebc57c655705b3a4e6b1db5c87b08500f263bcc8'),
  ('cpiuris2025::51fadf7f44e9522763af64b2daf5d487', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência dos Tribunais Regionais Eleitorais', '## Competência dos Tribunais Regionais Eleitorais

Os Tribunais Regionais Eleitorais expedem resolução indicando o juízo competente para processar e julgar representações de cassação do registro ou diploma, ações de investigação judicial eleitoral e impugnação.

### Conceitos
- **Tribunal Regional Eleitoral**: Entidade responsável por expedir resolução indicando o juízo competente para processar e julgar representações eleitorais
- **Competência**: Conceito jurídico que se refere à capacidade de um órgão ou tribunal decidir sobre uma questão específica

### Referências legais
- Art. 102 da Lei nº 4.737/1965
- ...

### Jurisprudência
- TSE — RESPE n.º 624-54
- TSE — Agravo Regimental em Ação Cautelar n.º 060075539

### Dicas de prova
- Entenda a competência dos Tribunais Regionais Eleitorais e como ela se relaciona com as representações eleitorais.
- Reconheça a importância da competência no processo eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 102 da Lei nº 4.737/1965", "..."], "jurisprudence": ["TSE — RESPE n.º 624-54", "TSE — Agravo Regimental em Ação Cautelar n.º 060075539"], "confidence": 0.8, "extracted_at": "2026-05-27T01:05:53.308489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=184", "doc_key": "51fadf7f44e9522763af64b2daf5d487"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '237d62f563d8c06e9f309127bf7d385538e20b6fb3f328c48e632b72456da096'),
  ('cpiuris2025::fe0171e31f9ad966268ae79bdece3f03', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Procedimento para ação eleitoral', '## Procedimento para ação eleitoral

Descreve o procedimento para a ação eleitoral, incluindo notificação do representado, prazo para defesa e inquirição de testemunhas.

### Conceitos
- **Ação Eleitoral**: Processo judicial que visa impugnar atos eleitorais
- **Representação**: Ato processual que busca impugnar um ato eleitoral
- **Defesa**: O direito de uma parte apresentar argumentos e provas para apoiar sua posição
- **Testemunhas**: Pessoas que podem ser ouvidas em um processo para fornecer informações relevantes
- **Procurador-Geral**: O oficial do Estado responsável por representar o interesse público no processo

### Referências legais
- Art. 22, I, b, LC n.º 64/90
- Código Eleitoral

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da defesa no processo eleitoral
- Conheça o procedimento para a inquirição de testemunhas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22, I, b, LC n.º 64/90", "Código Eleitoral"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:06:25.982520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=185", "doc_key": "fe0171e31f9ad966268ae79bdece3f03"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8a993c9f2d8309c590940771bab7145018e12501a88defd3ffe00f4f111f49db'),
  ('cpiuris2025::373f1034f131d747f4c7714700b0695e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sanções para contribuição com o ato eleitoral', '## Sanções para contribuição com o ato eleitoral

O Tribunal pode declarar inelegibilidade a candidato e a não candidato que contribuíram para o ato, recebendo sanções por interferência do poder econômico ou desvio de autoridade.

### Conceitos
- **inelegibilidade**: Impossibilidade de exercer cargo público devido a uma infração eleitoral
- **representação**: Ação apresentada por um cidadão contra outro, com o objetivo de proteger seus direitos
- **prática do ato**: Comportamento que viola as regras eleitorais
- **contribuição**: Participação no ato ilegal

### Referências legais
- Art. 22, XIV, da LC n.º 64/90

### Dicas de prova
- Distinção entre candidato e não candidato que contribuiu para o ato
- Sanções para interferência do poder econômico ou desvio de autoridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22, XIV, da LC n.º 64/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:07:00.096530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=185", "doc_key": "373f1034f131d747f4c7714700b0695e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e8631f3f92cf372ac72e4d149b0fbc00a6087dcf1b4c144bf740fab67a20c768'),
  ('cpiuris2025::96dd3a3b6da6be21df4fa2fe7f7a46fd', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações eletoras e representações por condutas vedadas aos agentes públicos', '## Ações eletoras e representações por condutas vedadas aos agentes públicos

O texto discute as ações eletoras e as representações por condutas vedadas aos agentes públicos, destacando a importância da isonomia no processo eleitoral.

### Conceitos
- **inelegibilidade**: Pena autônoma aplicada ao candidato que cometeu abuso de poder político
- **abuso de poder político**: Uso indevido de recursos para desequilibrar a isonomia do pleito eleitoral
- **conduta vedada**: Atos que caracterizam abuso de poder político e afetam a igualdade de oportunidades

### Referências legais
- Art. 73, da Lei n.º 9.504/97

### Jurisprudência
- TSE — Agravo Regimental no Agravo Regimental no Recurso Ordinário n.º 537610
- Súmula N STF

### Dicas de prova
- Pergunte sobre a inelegibilidade e suas consequências
- Entenda o conceito de abuso de poder político e como ele afeta a isonomia do pleito eleitoral
- Conheça as condutas vedadas e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.186", "page_number": 186, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 73, da Lei n.º 9.504/97"], "jurisprudence": ["TSE — Agravo Regimental no Agravo Regimental no Recurso Ordinário n.º 537610", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T01:07:36.219527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=186", "doc_key": "96dd3a3b6da6be21df4fa2fe7f7a46fd"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '295c204f2aa110749f336ff0954a0d82755981415da44a5740a7cbea61ed462a'),
  ('cpiuris2025::69fc25ee0e86adf2fd236ce63b64c4fe', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações Eleitorais', '## Ações Eleitorais

O pedido de representação pode ser proposto contra o candidato, agente público, partido político ou coligação. Em eleições majoritárias, é necessário litisconsórcio passivo entre o candidato e seu vice ou suplente. As sanções aplicáveis incluem multa, suspensão imediata da conduta vedada e cassação do registro do candidato.

### Conceitos
- **Litisconsórcio passivo**: Relacionamento jurídico entre duas ou mais pessoas que se tornam responsáveis pela mesma ação ou omissão
- **Multa**: Sancionamento aplicado aos responsáveis pela conduta vedada e aos partidos, coligações e candidatos que dela se beneficiam
- **Suspensão imediata da conduta vedada**: Medida provisória para interromper a conduta ilegal
- **Cassação do registro ou diploma do candidato**: Sanção aplicável em casos de abuso de poder

### Referências legais
- Art. 73, §§ 4º e 8º, da Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- Tema repetitivo do TSE

### Dicas de prova
- Entenda o conceito de litisconsórcio passivo necessário
- Conheça as sanções aplicáveis às condutas vedadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 73, §§ 4º e 8º, da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "Tema repetitivo do TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T01:08:12.659841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=187", "doc_key": "69fc25ee0e86adf2fd236ce63b64c4fe"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4559f66a8f30a1d4419ab689e3cf5a842d325753815db8e06074bb72db27b7ff'),
  ('cpiuris2025::e8d5916aae0e6d265038afd6af42ba80', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Cassação do registro ou diploma do candidato', '## Cassação do registro ou diploma do candidato

A cassação de registro ou diploma de um candidato é representada e acarreta a cassação, sem multa, em certas hipóteses. O rito é previsto no artigo 22 da LC nº 64/90 e no §12 do artigo 73 da LE.

### Conceitos
- **cassação**: Ato que resulta na inabilitação de um candidato a se eleger
- **registro**: O ato de registrar um candidato para as eleições
- **dipoma**: O documento que certifica o direito de um candidato a se eleger

### Referências legais
- Art. 22 da LC nº 64/90
- Art. 73 §12 da LE

### Jurisprudência
- TSE — RESPE n.º 78136
- TSE — RESPE n.º 32372
- TSE — RESPE n.º 82203

### Dicas de prova
- Entenda a diferença entre registro e diploma do candidato
- Conheça o rito previsto no artigo 22 da LC nº 64/90', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22 da LC nº 64/90", "Art. 73 §12 da LE"], "jurisprudence": ["TSE — RESPE n.º 78136", "TSE — RESPE n.º 32372", "TSE — RESPE n.º 82203"], "confidence": 0.8, "extracted_at": "2026-05-27T01:08:50.474562+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=187", "doc_key": "e8d5916aae0e6d265038afd6af42ba80"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'ef1cf2f0b3860d5d6760b8329e3b3074c2ef75755ae0d85ad060b8e6bb1d0f4c'),
  ('cpiuris2025::b24d5f865ea9bf964fc451b9379167c8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações eletoras - Hipóteses materiais de condutas vedadas', '## Ações eletoras - Hipóteses materiais de condutas vedadas

São listados os benefícios que são vedados aos agentes públicos, como o uso de recursos públicos para campanha eleitoral ou a nomeação de servidores públicos sem justa causa.

### Conceitos
- **Benefício para candidato**: A ocorrência de conduta vedada só se materializa quando há um benefício para determinado candidato.
- **Uso de transporte oficial**: O uso, em campanha, de transporte oficial pelo Presidente da República é permitido, desde que não tenha caráter de ato público.
- **Serviços públicos**: A utilização de serviços públicos para fins eleitorais é vedada, exceto se for utilizado em campanha.
- **Nomeações e contratações**: A nomeação ou contratação de servidores públicos sem justa causa é vedada.
- **Distribuição gratuita de bens**: O uso promocional em favor de candidato, partido político ou coligação de distribuição gratuita de bens e serviços de caráter social custeados ou subvencionados pelo Poder Público é vedado.
- **Cessão de servidor público**: A cessão de servidor público para comitês de campanha eleitoral durante o horário de expediente normal é vedada, exceto se estiver licenciado.
- **Vantagens públicas**: A supressão ou readaptação de vantagens ou por outros meios causar dificuldades ou impedimentos do exercício funcional é vedada.
- **Remoção e exoneração**: A remoção ou exoneração de servidor público na circunscrição do pleito nos 3 meses que antecedem a eleição até a posse dos eleitos é vedada, sob pena de nulidade de eleição.

### Referências legais
- Art. 73 da Lei n.º 9.504/97

### Dicas de prova
- Pergunte sobre os benefícios que são vedados aos agentes públicos.
- Entenda a diferença entre uso de transporte oficial e uso de recursos públicos para campanha eleitoral.
- Conheça as hipóteses em que a nomeação ou contratação de servidores públicos é vedada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 73 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:09:43.331062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=188", "doc_key": "b24d5f865ea9bf964fc451b9379167c8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '70a7286ff3ee152f1372b72d2afefd6ca10d0217950ba2755ca4c11e4db97f7b'),
  ('cpiuris2025::d87d1be2f6624ed0a587a1bbe3fe507f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Nomeação e Contratação em Tempo de Eleição', '## Nomeação e Contratação em Tempo de Eleição

Regra de pleno direito com ressalvas para nomeações e contratações em tempo de eleição, incluindo exceções para agentes públicos e serviços públicos essenciais.

### Conceitos
- **Nomeação**: Ato pelo qual alguém é designado para um cargo ou função
- **Contratação**: O processo pelo qual uma pessoa é contratada para realizar um trabalho ou serviço
- **Tempo de eleição**: Périodo durante o qual as eleições são realizadas
- **Vedações**: Restrições ou limitações impostas a certas ações ou atos
- **Agentes públicos**: Pessoas que exercem funções públicas

### Referências legais
- Art. 299, § 3º da Lei nº 9.504/1997

### Jurisprudência
- TSE — RO n.º 12.224
- RE 123456

### Dicas de prova
- Entenda a distinção entre nomeação e contratação em tempo de eleição
- Conheça as exceções para agentes públicos e serviços públicos essenciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 299, § 3º da Lei nº 9.504/1997"], "jurisprudence": ["TSE — RO n.º 12.224", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:10:10.962414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=188", "doc_key": "d87d1be2f6624ed0a587a1bbe3fe507f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b007b0f06941f1e7b84eaf5af1c3be1e9a27f91b24f7b6d2f4ba6600f94a62a6'),
  ('cpiuris2025::d16c9a8e1bebc03772284b0e09941f54', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações eletoras', '## Ações eletoras

Conduzas vedadas nos 3 meses que antecedem o pleito incluem transferência voluntária de recursos, veicular propaganda institucional, fazer pronunciamento em cadeia de rádio e televisão fora do horário eleitoral gratuito, além de outras condutas proibidas.

### Conceitos
- **Propaganda institucional**: Divulgação de atos, programas, obras, serviços e campanhas dos órgãos públicos
- **Pronunciamento em cadeia de rádio e televisão**: Fazer declarações em horário não eleitoral gratuito

### Referências legais
- Art. 17 da Lei Eleitoral
- Redação dada pela Lei nº 14.356, de 2022

### Jurisprudência
- RE 123456
- Tema repetitivo: Propaganda institucional em período proibido

### Dicas de prova
- Distinção entre propaganda institucional e propaganda de produtos e serviços
- Entendimento do conceito de pronunciamento em cadeia de rádio e televisão fora do horário eleitoral gratuito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17 da Lei Eleitoral", "Redação dada pela Lei nº 14.356, de 2022"], "jurisprudence": ["RE 123456", "Tema repetitivo: Propaganda institucional em período proibido"], "confidence": 0.8, "extracted_at": "2026-05-27T01:10:51.076592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=189", "doc_key": "d16c9a8e1bebc03772284b0e09941f54"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e6164fdc121e09187ae8f77e3dc5656c6d0a2d4488a82d15d19ad8574a1aab53'),
  ('cpiuris2025::89a0fd4a59958542c8ee859489f9f3e5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ampliação de benefícios sociais em ano eleitoral', '## Ampliação de benefícios sociais em ano eleitoral

Programas sociais autorizados em lei e já em execução podem ser acompanhados pelo MP durante os anos eleitorais, mas não podem ser executados por entidades vinculadas a candidatos.

### Conceitos
- **Ampliação de benefícios sociais**: Aumento dos benefícios sociais concedidos em ano eleitoral
- **Entidade nominalmente vinculada**: Entidade que mantém uma relação de dependência com um candidato
- **Acompanhamento da execução financeira e administrativa**: O poder do MP monitorar a execução dos programas sociais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- EC n. 123/2022
- RE 123456
- Tema repetitivo ...
- STF: 14/07/2022

### Dicas de prova
- Entenda a relação entre os programas sociais e as eleições presidenciais.
- Conheça o conceito de entidade nominalmente vinculada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["EC n. 123/2022", "RE 123456", "Tema repetitivo ...", "STF: 14/07/2022"], "confidence": 0.8, "extracted_at": "2026-05-27T01:11:18.269196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=189", "doc_key": "89a0fd4a59958542c8ee859489f9f3e5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6f2633c9838a81a071629fb0c7d94aacdaca879ce09d2d39d5c0572adda7f30c'),
  ('cpiuris2025::7e975d182c8ef0fbf92b7955d51cbd8f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações Eletoras - Proibição de Benefícios Públicos aos Candidatos', '## Ações Eletoras - Proibição de Benefícios Públicos aos Candidatos

O artigo 73, §10 da Lei nº 9.504/97 proíbe que o governo distribua bens ou benefícios à população nos dias das eleições, exceto em casos de calamidade pública ou programas sociais. Além disso, a jurisprudência admite a aplicação do princípio da proporcionalidade para afastar a sanção de cassação do diploma quando o candidato comparece às inaugurações de obras públicas de forma discreta.

### Conceitos
- **Princípio da Proporcionalidade**: Aplicação do princípio para afastar a sanção de cassação do diploma
- **Benefícios Públicos**: Distribuição de bens ou benefícios pela população por parte do governo
- **Calamidade Pública**: Situação excepcional que justifica a distribuição de bens públicos
- **Programas Sociais**: Iniciativas governamentais destinadas a atender às necessidades sociais
- **Direito ao Voto**: Direito fundamental de todos os cidadãos para participar das eleições
- **Hipossuficiência Econômica**: Situação em que uma pessoa não tem condições econômicas para exercer seu direito ao voto

### Referências legais
- Art. 73, §10 da Lei nº 9.504/97
- Súmula 496 do TSE

### Jurisprudência
- ADI 7.212/DF
- RE 123456

### Dicas de prova
- Entenda a aplicação do princípio da proporcionalidade em casos de benefícios públicos aos candidatos
- Conheça as exceções à proibição de benefícios públicos nos dias das eleições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 73, §10 da Lei nº 9.504/97", "Súmula 496 do TSE"], "jurisprudence": ["ADI 7.212/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:12:02.135818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=190", "doc_key": "7e975d182c8ef0fbf92b7955d51cbd8f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b9d688db428ba2b1ac1e7e1128abd39f56309909e1b7e0a58b1fe87c63b6d8cc'),
  ('cpiuris2025::637c074fa604f0e8d255bff0d0744b8d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — O dever do Poder Público de oferecer transporte público coletivo gratuito nas zonas urbanas em dias de eleições', '## O dever do Poder Público de oferecer transporte público coletivo gratuito nas zonas urbanas em dias de eleições

A ação buscou determinar ao Poder Público que mantivesse o serviço de transporte público urbano coletivo de passageiros em níveis normais, sem redução específica nos dias das eleições. O Supremo Tribunal Federal (STF) fixou a tese de que é inconstitucional a omissão do poder público em oferecer transporte público coletivo gratuito nas zonas urbanas em dias de eleições.

### Conceitos
- **Obrigação do Poder Público**: O Estado tem a obrigação de garantir o acesso a serviços essenciais, como o transporte público coletivo.
- **Direito à igualdade**: Todos os eleitores devem ter acesso ao mesmo nível de serviço, independentemente da sua localização.
- **Gratuidade do serviço**: O serviço de transporte público coletivo deve ser oferecido gratuitamente em dias de eleições.
- **Zonas urbanas**: As áreas urbanas devem ter acesso ao mesmo nível de serviço de transporte público coletivo que as zonas rurais.
- **Eleições**: A data das eleições é um fator importante para a garantia do acesso ao serviço de transporte público coletivo.
- **Constitucionalidade**: A constitucionalidade de uma lei ou medida depende da sua conformidade com a Constituição.
- **Tese do STF**: A tese do STF é a interpretação dada à lei ou medida por um tribunal superior.

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- Súmula 643 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: direito à igualdade e obrigação do Poder Público

### Dicas de prova
- Perguntas sobre a constitucionalidade da omissão do poder público em oferecer transporte público coletivo gratuito nas zonas urbanas em dias de eleições.
- Distinção entre as zonas urbanas e rurais no que tange ao acesso ao serviço de transporte público coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "Súmula 643 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: direito à igualdade e obrigação do Poder Público"], "confidence": 0.8, "extracted_at": "2026-05-27T01:13:00.591207+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=190", "doc_key": "637c074fa604f0e8d255bff0d0744b8d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8d4d69736740334940a2108b79d468d7945f1b545e7761ea8f7361702019e7f1'),
  ('cpiuris2025::569f5aae277e23b84859675d24b7a854', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ação de Impugnação de Mandato Eletivo (AIME)', '## Ação de Impugnação de Mandato Eletivo (AIME)

A AIME é uma ação constitucional que visa invalidar o diploma conferido ao candidato, com objetivo de impugnar o mandato eletivo. O prazo para propor a ação é de 15 dias contados da diplomação, e deve ser instruída com provas de abuso de poder econômico, corrupção ou fraude.

### Conceitos
- **Ação de Impugnação de Mandato Eletivo (AIME)**: ação constitucional que visa invalidar o diploma conferido ao candidato
- **Abuso de poder econômico**: fato que configura a ação de impugnação de mandato eletivo
- **Corrupção**: fato que configura a ação de impugnação de mandato eletivo
- **Fraude**: fato que configura a ação de impugnação de mandato eletivo

### Referências legais
- Art. 14, §10, da CF

### Jurisprudência
- RE 123456
- Tema repetitivo AIME

### Dicas de prova
- Legitimidade ativa: candidato, partido político, coligação e Ministério Público Eleitoral
- Legitimidade passiva: candidato eleito e diplomado, incluindo suplentes
- Competência: Juiz Eleitoral e TRE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.191", "page_number": 191, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14, §10, da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo AIME"], "confidence": 0.8, "extracted_at": "2026-05-27T01:13:38.894850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=191", "doc_key": "569f5aae277e23b84859675d24b7a854"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a5705ece95d67873cefe471152f7be8b608a9ee2bd1b587471cfb93a3f79dd16'),
  ('cpiuris2025::de0cd2a6cf256660479d6288c6ffba06', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ação de Impugnação ao Mandato (AIME) e Representações por Descumprimento da Lei nº 9.504/97', '## Ação de Impugnação ao Mandato (AIME) e Representações por Descumprimento da Lei nº 9.504/97

Resumo do texto sobre a Ação de Impugnação ao Mandato (AIME) e as representações que podem ser feitas por descumprimento da Lei das Eleições.

### Conceitos
- **Ação de Impugnação ao Mandato (AIME)**: Procedimento para impugnar o mandato de um eleitor
- **Representação por Descumprimento da Lei nº 9.504/97**: Reclamação ou representação feita sobre descumprimento da Lei das Eleições
- **Prazo decadencial**: Prazo que não pode ser interrompido ou suspensso
- **Segredo de justiça**: Conceito jurídico que protege a confidencialidade da tramitação de um processo

### Referências legais
- Art. 3º e seguintes da LC nº 64/90
- Art. 258 do Código Eleitoral
- Art. 276, § 1º do Código Eleitoral
- Art. 281 do Código Eleitoral
- Art. 14, §11 da CF/88
- Art. 93, IX da CF/88
- Lei nº 9.504/97

### Jurisprudência
- RE 122
- Tema repetitivo: litispendência entre AIJE, AIME e Recurso contra a Diplomação

### Dicas de prova
- Entenda o conceito de prazo decadencial e como ele se aplica à AIME.
- Conheça as legítimas partes que podem propor representações por descumprimento da Lei nº 9.504/97.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.192", "page_number": 192, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 3º e seguintes da LC nº 64/90", "Art. 258 do Código Eleitoral", "Art. 276, § 1º do Código Eleitoral", "Art. 281 do Código Eleitoral", "Art. 14, §11 da CF/88", "Art. 93, IX da CF/88", "Lei nº 9.504/97"], "jurisprudence": ["RE 122", "Tema repetitivo: litispendência entre AIJE, AIME e Recurso contra a Diplomação"], "confidence": 0.8, "extracted_at": "2026-05-27T01:14:23.674319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=192", "doc_key": "de0cd2a6cf256660479d6288c6ffba06"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '28b4140643c4e1023ee54db316a7f8c7ca03371a120a0468b81b82a67eed5521'),
  ('cpiuris2025::1ab471a38d90d690f1f185340cb873c5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência e Procedimento das Representações Eleitorais', '## Competência e Procedimento das Representações Eleitorais

A competência para processar e julgar as representações eleitorais é distribuída entre os Juízes Eleitorais, TREs e TSE. O procedimento envolve notificação do reclamado ou representado, apresentação de defesa e julgamento da representação.

### Conceitos
- **Competência**: A competência para processar e julgar as representações eleitorais é distribuída entre os Juízes Eleitorais, TREs e TSE.
- **Procedimento**: O procedimento envolve notificação do reclamado ou representado, apresentação de defesa e julgamento da representação.
- **Reclamação**: Uma ação que pode ser apresentada por um eleitor contra outro, com o objetivo de resolver uma questão relacionada à eleição.
- **Representação**: Uma ação que pode ser apresentada por um eleitor ou partido político para solicitar uma mudança na legislação eleitoral.
- **TREs**: Tribunais Regionais Eleitorais, responsáveis pela eleição federal, estadual e distrital.
- **TSE**: Superior Tribunal Eleitoral, responsável pela eleição presidencial.

### Referências legais
- Art. 96-B, §1º, da Lei n.º 9.504/97

### Dicas de prova
- Entenda a competência e procedimento das representações eleitorais.
- Conheça as diferenças entre reclamação e representação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.193", "page_number": 193, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 96-B, §1º, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:15:16.597505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=193", "doc_key": "1ab471a38d90d690f1f185340cb873c5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '12968cf792654e056f67112d21b796eae0c2cfd2f725b09e051fad600e4a4503'),
  ('cpiuris2025::acb111eea63d3b5d3d216502120223c0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Captação Ilícita de Sufrágio', '## Captação Ilícita de Sufrágio

A captação ilícita de sufrágio é a prática de dar, prometer ou oferecer vantagens pessoais para influenciar o voto de um eleitor, protegendo a liberdade do voto.

### Conceitos
- **Captação Ilícita de Sufrágio**: Prática de dar, prometer ou oferecer vantagens pessoais para influenciar o voto de um eleitor
- **Dolo Específico**: Intenção de obter o voto do eleitor sem necessidade de pedido explícito
- **Participação ou Anuência**: Ocorrência da participação ou anuência do candidato beneficiado na prática do ilícito

### Referências legais
- Art. 41-A da Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinção entre captação ilícita e influência indevida
- Importância do dolo específico na caracterização da conduta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.194", "page_number": 194, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 41-A da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T01:15:47.622612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=194", "doc_key": "acb111eea63d3b5d3d216502120223c0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8dc761f27e9a38c4222b13069f5d29c23e2af95bc2a5cb138926ddea625acfdf'),
  ('cpiuris2025::6eb18ae48933c23c5da6ef99e4b25a2b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Captação Ilícita de Sufrágio', '## Captação Ilícita de Sufrágio

A captação ilícita de sufrágio é a doação, oferecimento ou promessa de bem ou vantagem pessoal para obter o voto. Exige prova robusta e inconteste dos atos. A ação pode ser proposta até a data da diplomação dos candidatos eleitos.

### Conceitos
- **Captação ilícita de sufrágio**: Doação, oferecimento ou promessa de bem ou vantagem pessoal para obter o voto
- **Prazo inicial**: O registro de candidatura
- **Procedimento**: Rito estabelecido no art. 22 da LC n.º 64/90
- **Sanção**: Multas e cassação do registro ou diploma

### Referências legais
- Art. 41-A, §1º, da Lei n.º 9.504/97
- Art. 41-A, §3º, da Lei n.º 9.504/97
- Art. 22 da LC n.º 64/90

### Jurisprudência
- TSE — Ag. Reg. RO n.º 97917

### Dicas de prova
- Distinção entre captação ilícita e doação de sufrágio
- Entendimento da prova necessária para a configuração da captação ilícita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.195", "page_number": 195, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 41-A, §1º, da Lei n.º 9.504/97", "Art. 41-A, §3º, da Lei n.º 9.504/97", "Art. 22 da LC n.º 64/90"], "jurisprudence": ["TSE — Ag. Reg. RO n.º 97917"], "confidence": 0.8, "extracted_at": "2026-05-27T01:16:23.533927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=195", "doc_key": "6eb18ae48933c23c5da6ef99e4b25a2b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5b3c684fb4c02885be562c520c27c25740a34bc153cb9271abdf63334de4658b'),
  ('cpiuris2025::bf3d610b530e762c878e84795684d3ed', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Representação por captação ou gastos ilícitos de recursos', '## Representação por captação ou gastos ilícitos de recursos

O artigo 30-A da Lei n.º 9.504/97 permite que partidos políticos, coligações e o Ministério Público Eleitoral representem à Justiça Eleitoral para apurar condutas em desacordo com as normas da Lei de Eleições, relacionadas à arrecadação e gastos de recursos.

### Conceitos
- **Legitimidade ativa**: O direito de representar na ação de captação ilícita de recursos
- **Legitimidade passiva**: A capacidade de ser processado na ação de captação ilícita de recursos
- **Sanção**: A consequência da ação de captação ilícita de recursos, que pode incluir denegação do diploma ou cassação do candidato

### Referências legais
- Art. 30-A da Lei n.º 9.504/97

### Dicas de prova
- Entenda a legitimidade ativa e passiva para representar na ação de captação ilícita de recursos
- Conheça as sanções que podem ser impuestas ao candidato eleito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.196", "page_number": 196, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 30-A da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:17:07.029472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=196", "doc_key": "bf3d610b530e762c878e84795684d3ed"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '51776473cf66848e1304ce9cae716400af499c1203dcf9a1d3b8f60537a27f11'),
  ('cpiuris2025::df6cd50521534ce3facfc7ff3b93c900', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso contra Expedição de Diploma (RCED)', '## Recurso contra Expedição de Diploma (RCED)

O RCED é um recurso que tem como objetivo desconstituir o diploma, afastando o eleito do exercício do mandato eletivo. Tem natureza de ação desconstitutiva do ato administrativo da diplomação.

### Conceitos
- **Recurso contra Expedição de Diploma (RCED)**: Ação que visa desconstituir o diploma, afastando o eleito do exercício do mandato eletivo.
- **Inelegibilidade superveniente**: Alterações fáticas ou jurídicas que ocorrem até a data fixada para os partidos e coligações apresentarem os requerimentos de registros de candidatos.
- **Causa superveniente**: Fato que ocorre até o dia 15 de agosto do ano da eleição, conforme art. 11 da Lei n.º 9.504/97.
- **Ação desconstitutiva**: Atividade jurídica que visa invalidar um ato administrativo ou uma decisão judicial.
- **Impugnação autônoma**: Recurso que não depende de outro recurso para ser processado.
- **Diploma**: Ato administrativo que declara o eleito vencedor do pleito.

### Referências legais
- Art. 262 do Código Eleitoral
- Súmula n.º 47 do TSE

### Jurisprudência
- ADI n.º 6297

### Dicas de prova
- Entenda a diferença entre inelegibilidade superveniente e causa superveniente.
- Conheça o rito adotado para o RCED e como ele se diferencia da impugnação autônoma.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.197", "page_number": 197, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 262 do Código Eleitoral", "Súmula n.º 47 do TSE"], "jurisprudence": ["ADI n.º 6297"], "confidence": 0.8, "extracted_at": "2026-05-27T01:17:49.381806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=197", "doc_key": "df6cd50521534ce3facfc7ff3b93c900"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '43f43f55d2a5b2e2875f0917f544482823e6cd70bfac7b17f91a10de268fc63a'),
  ('cpiuris2025::76cb52c4485d8945a0c74d2c9341689d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Legitimidade Ativa para Recurso Contra a Expedição de Diploma', '## Legitimidade Ativa para Recurso Contra a Expedição de Diploma

São legitimados para propor o Recurso Contra a Expedição de Diploma: partidos políticos, coligações, candidatos e Ministério Público Eleitoral.

### Conceitos
- **Legitimidade Ativa**: O direito de uma entidade ou pessoa para propor um recurso contra a expedição de diploma.
- **Partidos Políticos**: São legitimados para propor o Recurso Contra a Expedição de Diploma.
- **Candidatos**: São legitimados para propor o Recurso Contra a Expedição de Diploma.
- **Ministério Público Eleitoral**: São legitimados para propor o Recurso Contra a Expedição de Diploma.

### Referências legais
- Art. 266 do Código Eleitoral
- Art. 267 do Código Eleitoral

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre legitimidade ativa e passiva para propor o Recurso Contra a Expedição de Diploma.
- Importância da competência para julgar o recurso contra expedição de diploma.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.198", "page_number": 198, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 266 do Código Eleitoral", "Art. 267 do Código Eleitoral"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:18:21.995615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=198", "doc_key": "76cb52c4485d8945a0c74d2c9341689d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a73492b50f6dad2c2433fa8349f0a3217a58728a6cf5fd4e653669fde506eab3'),
  ('cpiuris2025::62f2f35791bd6f6ce39c75cf80242f25', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações e Recursos Eleitorais', '## Ações e Recursos Eleitorais

Regras para o ajuizamento de recursos contra decisões do TSE em eleições federais, estaduais e presidenciais.

### Conceitos
- **RCED**: Recurso Contido Eleitoral
- **TSE**: Tribunal Superior Eleitoral
- **ADI**: Ação Direta de Inconstitucionalidade
- **Legitimidade Ativa**: O direito de uma parte iniciar um processo
- **Legitimidade Passiva**: O direito de uma parte ser ouvida em um processo

### Referências legais
- Art. 22, I, g do CE
- Art. 262, §3º do CE

### Jurisprudência
- RE 123456
- Súmula n.º 33 do TSE
- ADI n.º 1459-5

### Dicas de prova
- Entenda a diferença entre RCED e outras ações eleitorais.
- Conheça as regras de legitimidade para propositura da ação rescisória.
- Aprenda a distinguir entre competência do TSE e outros tribunais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.199", "page_number": 199, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22, I, g do CE", "Art. 262, §3º do CE"], "jurisprudence": ["RE 123456", "Súmula n.º 33 do TSE", "ADI n.º 1459-5"], "confidence": 0.8, "extracted_at": "2026-05-27T01:19:09.234531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=199", "doc_key": "62f2f35791bd6f6ce39c75cf80242f25"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd239806dbeaf30f3fd2f6510a235a188aa9add3ca9a4f9fd4713c01d2451bec1'),
  ('cpiuris2025::d58290000be2335da5b02d6f4b9cac42', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ação Rescisória', '## Ação Rescisória

Regras para a ação rescisória em decisões transitadas em julgado, incluindo hipóteses de rescisão e limitações.

### Conceitos
- **Decisão Transitada em Julgado**: Decisão final do juiz que não pode ser alterada por meio de recurso
- **Ação Rescisória**: Mecanismo para revisar uma decisão transitada em julgado em casos excepcionais
- **Causa de Rescisão**: Hipótese que justifica a rescisão de uma decisão transitada em julgado, como prevaricação ou corrupção do juiz
- **Coisa Julgada**: Conceito jurídico que se refere à imutabilidade da decisão final do juiz em um processo

### Referências legais
- Art. 966 do CPC

### Jurisprudência
- Súmula 636/2014 STF
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre decisão transitada em julgado e coisa julgada
- Conheça as hipóteses de rescisão previstas no art. 966 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.200", "page_number": 200, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 966 do CPC"], "jurisprudence": ["Súmula 636/2014 STF", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T01:19:44.768182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=200", "doc_key": "d58290000be2335da5b02d6f4b9cac42"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e50970db9b1762301882093724340e55a74ac2a4a9661332a89529594fa7f2a2'),
  ('cpiuris2025::fb09e1e0e2d631007b5ad2131d525d10', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações eletoras e proibição de condutas vedadas aos agentes públicos', '## Ações eletoras e proibição de condutas vedadas aos agentes públicos

Resumo objetivo: A questão destaca a proibição de certas condutas dos agentes públicos durante o período eleitoral, como nomeações, exonerações, revisões de remuneração e distribuição gratuita de bens. O artigo 73 da Lei nº 9.504/97 lista as condutas vedadas, incluindo a promoção de distribuição gratuita de bens durante o pleito.

### Conceitos
- **Art. 73**: Lei que proíbe certas condutas dos agentes públicos durante o período eleitoral
- **V - nomear, contratar ou de qualquer forma admitir, demitir sem justa causa, suprimir ou readaptar vantagens**: Proibição de nomeações e exonerações de cargos em comissão e designação
- **VIII - fazer, na circunscrição do pleito, revisão geral da remuneração dos servidores públicos**: Revisão geral da remuneração dos servidores públicos que exceda a recomposição da perda de seu poder aquisitivo
- **§10**: Lei que estabelece as regras para a promoção de distribuição gratuita de bens durante o pleito

### Referências legais
- Art. 73, V, ''a'', da Lei n.º 9.504/97
- Art. 73, VIII, da Lei n.º 9.504/97
- Art. 73, §10, da Lei n.º 9.504/97

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre nomeação e exoneração de cargos em comissão
- Revisão geral da remuneração dos servidores públicos: o que é permitido e o que não é
- Promoção de distribuição gratuita de bens durante o pleito: regras e exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.201", "page_number": 201, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 73, V, ''a'', da Lei n.º 9.504/97", "Art. 73, VIII, da Lei n.º 9.504/97", "Art. 73, §10, da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:20:34.722209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=201", "doc_key": "fb09e1e0e2d631007b5ad2131d525d10"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '830f2e96bc0b9315ce90d66093a2cf5bf9a55fe1a79ccb6072ae953e9afcbd39'),
  ('cpiuris2025::c40b0fc2c4c18d71c360d333cfb3cdde', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Proibição de condutas que afetam igualdade de oportunidades entre candidatos', '## Proibição de condutas que afetam igualdade de oportunidades entre candidatos

Art. 73, §10: proibida a distribuição gratuita de bens ou benefícios por parte da Administração Pública durante eleições, exceto em casos específicos.

### Conceitos
- **Administração Pública**: entidade pública responsável pela gestão dos recursos do Estado
- **Conduta Eleitoral**: ação ou comportamento que afeta a igualdade de oportunidades entre candidatos
- **Distribuição Gratuita**: oferecer bens ou benefícios sem custo para o destinatário
- **Eleição**: processo eletrônico ou presencial para escolher um candidato ao cargo público
- **Impugnação**: ação de questionar a validade do registro de um candidato

### Referências legais
- Art. 73, §10 da Lei nº 9.504/97
- LC nº 64/90

### Dicas de prova
- Entenda a importância da igualdade de oportunidades entre candidatos nos pleitos eleitorais
- Conheça as regras que regem a distribuição gratuita de bens ou benefícios por parte da Administração Pública durante eleições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.202", "page_number": 202, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 73, §10 da Lei nº 9.504/97", "LC nº 64/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:21:16.808074+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=202", "doc_key": "c40b0fc2c4c18d71c360d333cfb3cdde"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'f204591652038290dd38ca3bae548d2641418587463d194fc3b95bc1da330e6d'),
  ('cpiuris2025::bef71ce6c722f1b5745892552f752f1a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Princípio da devolutividade nos recursos eleitorais', '## Princípio da devolutividade nos recursos eleitorais

Os recursos eleitorais têm efeito devolutivo, exceto em casos específicos como a decisão sobre a prestação de contas anual dos órgãos partidários, que podem ter efeito suspensivo.

### Conceitos
- **Efeito devolutivo**: O recurso eleitoral tem efeito de revés, ou seja, não suspende a eficácia da decisão questionada, mas sim pede a devolução do caso ao tribunal competente.
- **Efeito suspensivo**: O recurso eleitoral tem efeito de suspensão, ou seja, interrompe a eficácia da decisão questionada até que o recurso seja julgado.
- **Prazo para interposição de recursos**: O prazo para interposição de recursos em matéria eleitoral é de três dias, contados da sua publicação, exceto quando houver previsão diversa.

### Referências legais
- Art. 257 do Código Eleitoral
- Art. 51 da Resolução n.º 23.604/2019 do TSE

### Jurisprudência
- {''term'': ''ADPF n.º 776'', ''definition'': ''Decisão do STF que estabeleceu o novo entendimento sobre o efeito suspensivo dos recursos eleitorais''}

### Dicas de prova
- Entenda a diferença entre efeito devolutivo e suspensivo nos recursos eleitorais.
- Conheça as exceções ao prazo para interposição de recursos em matéria eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.204", "page_number": 204, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 257 do Código Eleitoral", "Art. 51 da Resolução n.º 23.604/2019 do TSE"], "jurisprudence": ["{''term'': ''ADPF n.º 776'', ''definition'': ''Decisão do STF que estabeleceu o novo entendimento sobre o efeito suspensivo dos recursos eleitorais''}"], "confidence": 0.8, "extracted_at": "2026-05-27T01:21:57.855093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=204", "doc_key": "bef71ce6c722f1b5745892552f752f1a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd2989f14a74896d8c83cf6a56bfe1f766af6936e70d9c1a74112e5a377491dd6'),
  ('cpiuris2025::9fb436ce8e11d9d635f9b862a5cee9b4', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Gratuidade dos recursos eleitorais', '## Gratuidade dos recursos eleitorais

Os recursos eleitorais são gratuitos, de acordo com a Constituição Federal (art. 5º) e as leis específicas, como a Lei n.º 9.265/1996 e a Lei n.º 9.504/1997.

### Conceitos
- **Gratuidade**: O direito de realizar atos necessários à cidadania sem custas ou emolumentos.
- **Habeas Corpus**: Um dos direitos fundamentais previstos na Constituição Federal, garantindo a liberdade individual.
- **Ato necessário à cidadania**: Atividade ou procedimento que visa garantir os direitos e interesses do cidadão.

### Referências legais
- Art. 5º da Constituição Federal
- Lei n.º 9.265/1996
- Lei n.º 9.504/1997

### Jurisprudência
- Súmula N do TSE

### Dicas de prova
- Entenda a noção de ato necessário à cidadania e como ela está relacionada com os direitos fundamentais.
- Conheça as leis específicas que tornam os recursos eleitorais gratuitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.205", "page_number": 205, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º da Constituição Federal", "Lei n.º 9.265/1996", "Lei n.º 9.504/1997"], "jurisprudence": ["Súmula N do TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T01:22:31.678690+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=205", "doc_key": "9fb436ce8e11d9d635f9b862a5cee9b4"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd06feadec1cff7acc2f420defb993b4438d285b63960d998e24d22ead0b5c401'),
  ('cpiuris2025::a9769788aa8c28636c5a7089f4df3aa0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso e Apelação nos Processos Eleitorais', '## Recurso e Apelação nos Processos Eleitorais

Resumo do texto sobre recursos e apelações nos processos eleitorais, incluindo prazos e procedimentos.

### Conceitos
- **Recurso Inominado**: Recursos contra decisões dos Juízes Eleitorais
- **Apelação Criminal Eleitoral**: Apelelação de sentenças penais proferidas por Juízes Eleitorais
- **Embargos de Declaração**: Modalidade recursal de integração para esclarecer obscuridades, eliminar contradições, etc.

### Referências legais
- Art. 169 do CE
- Art. 265 do CE
- Art. 362 do Código Eleitoral
- Art. 275 do Código Eleitoral

### Dicas de prova
- Entenda a diferença entre Recurso Inominado e Apelação Criminal Eleitoral.
- Conheça o procedimento para opor Embargos de Declaração contra decisões dos Juízes Eleitorais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.206", "page_number": 206, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 169 do CE", "Art. 265 do CE", "Art. 362 do Código Eleitoral", "Art. 275 do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:23:13.973280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=206", "doc_key": "a9769788aa8c28636c5a7089f4df3aa0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c34b23f55847bbef773d52c8d5f51995c7e317575c7625ceb266161dabce3652'),
  ('cpiuris2025::9c7ff23527e29260e76bd07c444ccf1b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso contra decisões dos Tribunais Regionais Eleitorais', '## Recurso contra decisões dos Tribunais Regionais Eleitorais

São admissíveis recursos contra decisões dos Tribunais Regionais Eleitorais, incluindo recurso parcial, embargos de declaração e agravo de instrumento.

### Conceitos
- **Recurso Parcial**: É admissível em face das decisões de impugnações proferidas pelo TRE
- **Embargaos de Declaração**: São cabíveis quando houver obscuridade, dúvida, contradição ou omissão no acórdão
- **Agravo de Instrumento**: É cabível da decisão que inadmitir o recurso especial
- **Agravo Regimental**: Enseja a revisão de decisões monocráticas proferidas por membros do tribunal

### Referências legais
- Art. 275, §1º, do CE
- Art. 19 da Resolução n.º 23.478/2016, do TSE
- Art. 279, do CE

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre recurso parcial e embargos de declaração
- Entendimento da admissibilidade do agravo de instrumento
- Revisão das decisões monocráticas com o agravo regimental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.207", "page_number": 207, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 275, §1º, do CE", "Art. 19 da Resolução n.º 23.478/2016, do TSE", "Art. 279, do CE"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:23:50.814179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=207", "doc_key": "9c7ff23527e29260e76bd07c444ccf1b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'ec63563802666b218865eae4a07ce9a093bf353e681eed011f3e0ccccfdbb5fb'),
  ('cpiuris2025::a647de468b6c5d6541aea1b96f15b3f1', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso Ordinário e Recurso Especial', '## Recurso Ordinário e Recurso Especial

Recurso Ordinário: recurso contra decisões do TRE ou juiz eleitoral; Recurso Especial: discussão de questão de direito, cabível em face de decisões que contrariem a Constituição ou divergência na interpretação da lei.

### Conceitos
- **Recurso Ordinário**: recurso contra decisões do TRE ou juiz eleitoral
- **Recurso Especial**: discussão de questão de direito, cabível em face de decisões que contrariem a Constituição ou divergência na interpretação da lei
- **Decisão do TRE**: decisão proferida pelo Tribunal Regional Eleitoral
- **Habeas Corpus**: mandado que visa garantir a liberdade de alguém preso ou detido ilegalmente
- **Mandado de Segurança**: mandado que visa proteger direitos individuais contra atos do Poder Público

### Referências legais
- Art. 121, §4º, III, IV e V, da CF
- Art. 257, §2º, do CE
- Art. 281, §1º, CE

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre Recurso Ordinário e Recurso Especial
- Entender a importância do habeas corpus e mandado de segurança no contexto eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.208", "page_number": 208, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 121, §4º, III, IV e V, da CF", "Art. 257, §2º, do CE", "Art. 281, §1º, CE"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:24:31.284276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=208", "doc_key": "a647de468b6c5d6541aea1b96f15b3f1"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0fa63865c936a6f9c18e5f63491e905a6dc2242e29e2820085d5a6007dd7a882'),
  ('cpiuris2025::ac775d6fd78a310544f4b606e798c695', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso Extraordinário e Embargos de Declaração', '## Recurso Extraordinário e Embargos de Declaração

Resumo sobre o recurso extraordinário, embargos de declaração e suas regras no Direito Eleitoral.

### Conceitos
- **Recurso Extraordinário**: Ação que busca anular uma decisão do Tribunal Superior Eleitoral em contrariedade à norma constitucional.
- **Embargos de Declaração**: Mecanismo para corrigir o acórdão proferido pelo TSE, cabível quando houver omissão, obscuridade, contradição ou erro material.
- **Esgotamento das Instâncias Ordinárias**: Regra que exige o esgotamento de todas as instâncias ordinárias antes de interpor recurso especial eleitoral.
- **Poder de Polícia**: Autoridade do juiz eleitoral para tomar medidas preventivas, como a instauração de procedimento para impor multa.
- **Litisconsórcio Passivo**: Condição em que o titular e o vice da chapa majoritária são obrigados a se processar juntos em uma ação.

### Referências legais
- Art. 12 da Lei n.º 6.055/74
- Súmula n.º 18 do TSE
- Súmula n.º 25 do TSE
- Súmula n.º 30 do TSE
- Súmula n.º 38 do TSE

### Jurisprudência
- RE 123456
- Tema repetitivo Súmula n.º 18 do TSE

### Dicas de prova
- Entenda a regra de esgotamento das instâncias ordinárias para interpor recurso especial eleitoral.
- Conheça o poder de polícia do juiz eleitoral e suas limitações.
- Aprenda sobre litisconsórcio passivo em ações que visem à cassação de registro, diploma ou mandato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.209", "page_number": 209, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 12 da Lei n.º 6.055/74", "Súmula n.º 18 do TSE", "Súmula n.º 25 do TSE", "Súmula n.º 30 do TSE", "Súmula n.º 38 do TSE"], "jurisprudence": ["RE 123456", "Tema repetitivo Súmula n.º 18 do TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T01:25:29.128081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=209", "doc_key": "ac775d6fd78a310544f4b606e798c695"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3d54fef95d04ed42de0badaf13e0c068fadb8f20614aec18daa96b4d77465bf6'),
  ('cpiuris2025::16bf22f423dfde6f8568eeb4ccd9c0e0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Conhecimento de causa de inelegibilidade pelo Juiz Eleitoral', '## Conhecimento de causa de inelegibilidade pelo Juiz Eleitoral

O Juiz Eleitoral pode conhecer de ofício causas de inelegibilidade ou ausência de condição de elegibilidade, desde que resguardados o contraditório e a ampla defesa.

### Conceitos
- **Contraditório**: Princípio do direito processual que exige que as partes sejam ouvidas em uma causa de litigio
- **Ampla Defesa**: Direito do recorrente à apresentação de argumentos e provas para defender seus interesses

### Referências legais
- Súmula n.º 45 do TSE

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do contraditório e da ampla defesa no processo eleitoral
- Conheça a Súmula n.º 45 do TSE para aplicar corretamente o conhecimento de causa de inelegibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.210", "page_number": 210, "discipline": "Direito Eleitoral", "legal_refs": ["Súmula n.º 45 do TSE"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:25:50.603055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=210", "doc_key": "16bf22f423dfde6f8568eeb4ccd9c0e0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4e8ea76a32bf08240dea739d7c39214d3d44f52fd4049d6adcd6ebf8d0275ff9'),
  ('cpiuris2025::b621fd8bd40b0a0242e714269e9fc55c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Natureza jurídica dos crimes eleitorais', '## Natureza jurídica dos crimes eleitorais

Discute-se a natureza dos crimes eleitorais, com duas correntes: crime político (minoritária) ou crime comum (majoritária e seguida pelo STF). Prevalece a segunda corrente, considerando os crimes eleitorais como comuns.

### Conceitos
- **Crimes Eleitorais**: Têm natureza de crime comum, segundo a corrente majoritária
- **Crime Político**: Corrente minoritária que considera os crimes eleitorais como crime político
- **Pena Máxima**: Estabelecida no Código Eleitoral, sem pena mínima
- **Pena de Multa**: Consiste no pagamento ao Tesouro Nacional, com valor mínimo de 1 dia-multa e máximo de 300 dias-multa

### Referências legais
- Art. 284 do Código Eleitoral
- Art. 285 do Código Eleitoral
- Súmula n.º 231 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a natureza jurídica dos crimes eleitorais e suas implicações no processo penal eleitoral
- Conheça as especificidades da pena de multa em crimes eleitorais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.212", "page_number": 212, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 284 do Código Eleitoral", "Art. 285 do Código Eleitoral", "Súmula n.º 231 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T01:26:25.260964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=212", "doc_key": "b621fd8bd40b0a0242e714269e9fc55c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b8331cc63f99a98b606e80f0ba472b582131ac22ccea30ae988ccdf8eafe8948'),
  ('cpiuris2025::a57dfecda0799e142717f3cdfd3f9fcd', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Classificação dos crimes eleitorais', '## Classificação dos crimes eleitorais

Os crimes eleitorais são classificados em 8 grupos, abordando aspectos como formação do corpo eleitoral, partidos políticos, inelegibilidade e propaganda eleitoral.

### Conceitos
- **Crimes concernentes à formação do corpo eleitoral**: Atentam contra o processo de alistamento eleitoral
- **Crimes eleitorais relativos à formação e funcionamento dos partidos políticos**: Tutelam a garantia do efetivo exercício das atribuições dos partidos políticos
- **Crimes eleitorais em matéria de inelegibilidade**: Arguição de inelegibilidade ou impugnação de registro de candidato feita por interferência do poder econômico
- **Propaganda eleitoral**: Relativa à publicidade e divulgação de informações sobre candidatos ou partidos políticos
- **Votação**: Relativa ao ato de votar nas eleições
- **Garantia do resultado legítimo das eleições**: Tutela a integridade e validade dos resultados das eleições
- **Organização e funcionamento dos serviços eleitorais**: Relativa à gestão e administração dos serviços eleitorais
- **Crimes contra a fé pública eleitoral**: Atentam contra a confiança e integridade do processo eleitoral

### Referências legais
- Art. 5º, XLVI, alínea c da Constituição Federal
- Lei n.º 9.268/1996

### Jurisprudência
- ADI 3150
- Súmula do STF

### Dicas de prova
- Entenda a classificação dos crimes eleitorais e seus grupos
- Conheça as regras para a arguição de inelegibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.213", "page_number": 213, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º, XLVI, alínea c da Constituição Federal", "Lei n.º 9.268/1996"], "jurisprudence": ["ADI 3150", "Súmula do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T01:27:22.509190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=213", "doc_key": "a57dfecda0799e142717f3cdfd3f9fcd"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5ae974879c494ea0627d4cdf48cba8f7b55de2b4e2d902376c7469ab88f11114'),
  ('cpiuris2025::ee75c3c1c67aeb5d6947c5a056ad3e90', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Crimes Eleitorais e Processo Penal Eleitoral', '## Crimes Eleitorais e Processo Penal Eleitoral

Descreve os tipos de crimes eleitorais, incluindo a propaganda eleitoral, a votação, a garantia do resultado legítimo das eleições e a organização dos serviços eleitorais.

### Conceitos
- **Propaganda Eleitoral**: Tutelar a veracidade da propaganda eleitoral
- **Votação**: Garantir a liberdade para o exercício do poder de sufrágio
- **Fé Pública Eleitoral**: Preservação da confiança da sociedade em relação aos trabalhos da Justiça Eleitoral

### Referências legais
- Art. 323 do CE
- Art. 297 do CE
- Lei n.º 6.091/74, art. 11, V

### Dicas de prova
- Distinção entre propaganda eleitoral e votação
- Importância da preservação da fé pública eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.214", "page_number": 214, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 323 do CE", "Art. 297 do CE", "Lei n.º 6.091/74, art. 11, V"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:27:52.042747+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=214", "doc_key": "ee75c3c1c67aeb5d6947c5a056ad3e90"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '40bc22ba878a738da86ce7861a46d9772346ce39822c00340fc23cf29d681c65'),
  ('cpiuris2025::909360818cca11547b6917b77a1d8e66', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Processo Penal Eleitoral', '## Processo Penal Eleitoral

Descreve o processo penal eleitoral, incluindo a investigação dos crimes eleitorais, procedimento e controle externo.

### Conceitos
- **Investigação de crime eleitoral**: Conduzida pela Polícia Federal ou, supletivamente, pela Polícia Civil dos Estados
- **Inquérito policial**: Instaurado para apuração de crime eleitoral e concluído nos prazos estabelecidos pelo CPP
- **Controle externo da atividade policial**: Fazido pelo Ministério Público, que é o titular da ação penal

### Referências legais
- Art. 144, §1º, inciso IV, da CF/88
- Art. 2º da Resolução n.º 23.396/13, do TSE
- Art. 9º, caput, e §1º, da Resolução n.º 23.396/13, do TSE
- Art. 10 do CPP

### Jurisprudência
- ADI 5104
- RE 21.295/2003

### Dicas de prova
- Entenda a responsabilidade da Polícia Federal e da Polícia Civil nos crimes eleitorais
- Conheça o procedimento para instauração de inquérito policial e a importância do controle externo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.215 (1)", "page_number": 215, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 144, §1º, inciso IV, da CF/88", "Art. 2º da Resolução n.º 23.396/13, do TSE", "Art. 9º, caput, e §1º, da Resolução n.º 23.396/13, do TSE", "Art. 10 do CPP"], "jurisprudence": ["ADI 5104", "RE 21.295/2003"], "confidence": 0.8, "extracted_at": "2026-05-27T01:28:28.195200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=215", "doc_key": "909360818cca11547b6917b77a1d8e66"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6c876f61d5dde2b6a23a31cba345893e173ffe19bdc5813a136ea7a4b3bfbcc8'),
  ('cpiuris2025::7c90fd4cb3bf1ed4a94dec703d76b2a3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — A queixa-crime em ação penal privada subsidiária', '## A queixa-crime em ação penal privada subsidiária

A queixa-crime pode ser aceita apenas se o MP não ofereceu denúncia, não solicitou diligências ou arquivamento do inquérito policial no prazo legal.

### Conceitos
- **ação penal privada**: procedimento em que a vítima ou seu representante processal é o autor do processo
- **denúncia**: requerimento feito pelo MP para iniciar o processo
- **inércia do juiz**: falta de ação por parte do juiz que pode ser interpretada como inatividade
- **garantias processuais**: direitos e diretrizes estabelecidas pelo Código de Processo Penal

### Referências legais
- Art. 14 da Resolução n.º 23.640/21 do TSE

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ação penal privada e pública
- Conheça o papel do MP na iniciativa do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.215 (2)", "page_number": 215, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14 da Resolução n.º 23.640/21 do TSE"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:29:03.596342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=215", "doc_key": "7c90fd4cb3bf1ed4a94dec703d76b2a3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e53a06dfef3984b9c83a2d1ecdaa270c1bc37e45fc7c351a19681f94ba55c6a5'),
  ('cpiuris2025::9857ea17907f00625ddeb067175142e1', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ação Penal Eleitoral e Processo Penal Eleitoral', '## Ação Penal Eleitoral e Processo Penal Eleitoral

Resumo do texto: A ação penal eleitoral segue os procedimentos do Código de Processo Penal, com aplicação obrigatória dos artigos 395, 396, 396-A, 397 e 400. O juiz eleitoral pode absolver sumariamente ou confirmar o recebimento da denúncia, dando prosseguimento à ação penal.

### Conceitos
- **Código de Processo Penal**: Regulamenta os procedimentos do processo penal
- **Ação Penal Eleitoral**: Processo que envolve crimes eleitorais
- **Denúncia**: Ação apresentada contra um indivíduo acusado de crime
- **Citação**: Notificação formal do denunciado para responder à acusação
- **Prova admissível**: Meios que podem ser utilizados para comprovar a acusação

### Referências legais
- Art. 395 do Código de Processo Penal
- Art. 396 do Código de Processo Penal
- Lei nº 11.971/2008

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a aplicação obrigatória dos artigos 395, 396, 396-A, 397 e 400 do Código de Processo Penal na ação penal eleitoral.
- Conheça as regras de citação estabelecidas pelo Código de Processo Penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.216 (1)", "page_number": 216, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 395 do Código de Processo Penal", "Art. 396 do Código de Processo Penal", "Lei nº 11.971/2008"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T01:29:42.040298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=216", "doc_key": "9857ea17907f00625ddeb067175142e1"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'efab3f3036fc99de4dfb3c754f8fe389802c13824e70e2e75a7ca177606f2e45'),
  ('cpiuris2025::5c027d9dc0d79ae6e61b3a05a68ce66b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Gravações ambientais em âmbito eleitoral', '## Gravações ambientais em âmbito eleitoral

A STF entendeu que as gravações feitas durante o período eleitoral são equiparadas à situação de garantir elemento de defesa, para evitar armadilhas políticas.

### Conceitos
- **Gravação ambiental**: registração feita em âmbito eleitoral
- **Elemento de defesa**: meio utilizado para evitar armadilhas políticas

### Referências legais
- Art. 362 do CE
- Art. 1.040.515/SE

### Jurisprudência
- {''info'': ''RE 123456'', ''date'': ''26/04/2024''}
- Agravo de Instrumento n.º 455-02.2016.6.16.0114
- 04/04/2019

### Dicas de prova
- Diferenciar entre gravação ambiental e elemento de defesa.
- Entender o prazo para a apelação criminal eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.216 (2)", "page_number": 216, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 362 do CE", "Art. 1.040.515/SE"], "jurisprudence": ["{''info'': ''RE 123456'', ''date'': ''26/04/2024''}", "Agravo de Instrumento n.º 455-02.2016.6.16.0114", "04/04/2019"], "confidence": 0.8, "extracted_at": "2026-05-27T01:30:06.534059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=216", "doc_key": "5c027d9dc0d79ae6e61b3a05a68ce66b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '78a36d1a3ba3b96f92c677df9629332f879dbf2da3f9f60a688d949a795d51c4'),
  ('cpiuris2025::c6fae22acbc8b1a8a620b98795d6ed82', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência e Processamento de Crimes Eleitorais', '## Competência e Processamento de Crimes Eleitorais

A competência para julgar crimes eleitorais é da Justiça Eleitoral, exceto em casos de foro especial por prerrogativa de função prevista na Constituição. Pessoas com foro por prerrogativa de função são julgadas por Tribunais que não fazem parte da estrutura da Justiça Eleitoral.

### Conceitos
- **Competência**: A competência para julgar crimes eleitorais é da Justiça Eleitoral
- **Forno especial por prerrogativa de função**: Pessoas com foro por prerrogativa de função são julgadas por Tribunais que não fazem parte da estrutura da Justiça Eleitoral
- **Justiça Eleitoral**: A competência para julgar crimes eleitorais é da Justiça Eleitoral

### Referências legais
- Art. 364 do Código Eleitoral
- Art. 13 da Resolução n.º 23.640/21, do TSE

### Jurisprudência
- {''RE'': ''122943'', ''Tema'': ''Competência e Processamento de Crimes Eleitorais''}

### Dicas de prova
- Entenda a competência para julgar crimes eleitorais
- Conheça as exceções ao foro especial por prerrogativa de função', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.217", "page_number": 217, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 364 do Código Eleitoral", "Art. 13 da Resolução n.º 23.640/21, do TSE"], "jurisprudence": ["{''RE'': ''122943'', ''Tema'': ''Competência e Processamento de Crimes Eleitorais''}"], "confidence": 0.8, "extracted_at": "2026-05-27T01:31:23.316682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=217", "doc_key": "c6fae22acbc8b1a8a620b98795d6ed82"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '338141e51fab85933f5e5fd310e842f53ff2fbb5ea0361ef92003ac1c581ffc6'),
  ('cpiuris2025::90087af1765280f65d80fba24c8c0278', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Crimes Eleitorais e Processo Penal Eleitoral', '## Crimes Eleitorais e Processo Penal Eleitoral

Resumo do texto sobre crimes eleitorais e processo penal eleitoral, incluindo a definição da revisão criminal e as penas para os crimes eleitorais.

### Conceitos
- **Revisão Criminal**: Só é cabível quando a favor do réu
- **Fraude no Alistamento**: Crime eleitoral praticado pelo magistrado que permite a inscrição de forma fraudulenta
- **Induzimento à Inscrição Eleitoral Fraudulenta**: Crime eleitoral praticado por induzir alguém a se inscrever eleitor com infração de qualquer dispositivo do Código
- **Omissão Judicial**: Negar ou retardar a autoridade judiciária, sem fundamento legal, a inscrição requerida
- **Inscrição Eleitoral Fraudulenta**: Crime eleitoral praticado por efetuar o juiz, fraudulentamente, a inscrição de alistando
- **Calúnia Eleitoral**: Prova da verdade do fato é admitida ainda que o fato seja objeto de ação penal privada
- **Transação Penal e Suspensão Condicional**: Não são admitidas no processo penal eleitoral
- **Contratação de Pessoas para Ofender Honra**: Constitui crime a contratação, direta ou indireta, de grupo de pessoas com a finalidade de emitir mensagens ou comentários na Internet para ofender a honra de candidato, partido ou coligação

### Referências legais
- Art. 291 do Código Eleitoral
- Art. 290 do Código Eleitoral
- Art. 292 do Código Eleitoral

### Dicas de prova
- Revisão criminal só é cabível quando a favor do réu
- Fraude no alistamento é o crime eleitoral praticado pelo magistrado que permite a inscrição de forma fraudulenta
- Calúnia eleitoral: prova da verdade do fato é admitida ainda que o fato seja objeto de ação penal privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.218", "page_number": 218, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 291 do Código Eleitoral", "Art. 290 do Código Eleitoral", "Art. 292 do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:32:18.494071+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=218", "doc_key": "90087af1765280f65d80fba24c8c0278"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'dfd858ac95581e21031e0f87965214aecdf26608a49f7571340f8e5abe05f107'),
  ('cpiuris2025::11dc33718297b7ce2b5eb74ed98c1ccc', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Crimes Eleitorais e Processo Penal Eleitoral', '## Crimes Eleitorais e Processo Penal Eleitoral

Resumo sobre crimes eleitorais e processamento penal, incluindo artigos do Código Eleitoral e decisões da Justiça Eleitoral.

### Conceitos
- **Calúnia Eleitoral**: crime que imputa fato que ofende a integridade eleitoral de outrem
- **Transação Penal**: acordo entre o Estado e o réu para reduzir a pena
- **Suspensão Condicional do Processo**: medida processual que suspende a execução da pena, com condições
- **Pena de Reclusão**: prisão perpétua ou por tempo indeterminado
- **Multas**: sancionamento financeiro imposto ao réu
- **Detenção**: prisão temporária, geralmente inferior a 2 anos
- **Lei n.º 9.504/97**: Código Eleitoral brasileiro
- **Sistema Punitivo Especial**: sistema de punição mais severa para certos crimes

### Referências legais
- Art. 289 do Código Eleitoral
- Art. 293 do Código Eleitoral
- Art. 57-H, § 1º da Lei n.º 9.504/97

### Jurisprudência
- REsp n.º 25137
- Res. TSE n.º 21294/2002
- Ac.-STJ, de 09.04.2003, no CC n.º 37595

### Dicas de prova
- Entenda a diferença entre calúnia e crime eleitoral
- Conheça as exceções à transação penal e suspensão condicional do processo
- Identifique a pena mais severa para o crime de calúnia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.219", "page_number": 219, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 289 do Código Eleitoral", "Art. 293 do Código Eleitoral", "Art. 57-H, § 1º da Lei n.º 9.504/97"], "jurisprudence": ["REsp n.º 25137", "Res. TSE n.º 21294/2002", "Ac.-STJ, de 09.04.2003, no CC n.º 37595"], "confidence": 0.8, "extracted_at": "2026-05-27T01:33:10.478646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=219", "doc_key": "11dc33718297b7ce2b5eb74ed98c1ccc"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'df36694f5eb2756e2bdcd1fc1f5405b1f8dc346ebaeb23725733760664605a10'),
