  ('cpiuris2025::e566b0065e8e0cf79b04f8856292ce89', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Leis e Súmulas relacionadas ao Direito Eleitoral', '## Leis e Súmulas relacionadas ao Direito Eleitoral

