  ('cpiuris2025::4ac7cb2e835d01efed6f9ee0f0e8e2e2', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Referências Bibliográficas', '## Referências Bibliográficas

Lista de livros e fontes utilizadas como referência para o estudo do Direito Eleitoral.

### Conceitos
- **Referências Bibliográficas**: Listas de fontes utilizadas como referência para o estudo de um assunto
- **Bibliografia**: Coleção de livros, artigos e outros materiais escritos sobre um tema específico
- **Fonte**: Local ou instituição que fornece informações ou conhecimento
- **Publicação**: Obra impressa ou digital que contém texto, imagens ou gráficos
- **Recursos**: Materiais ou fontes utilizados para o estudo ou pesquisa de um assunto
- **Bibliografia**: Lista de livros, artigos e outros materiais escritos sobre um tema específico
- **Fonte secundária**: Informação obtida de uma fonte que não é a própria experiência ou observação

### Referências legais
- Art. 29 da Constituição Federal
- ...

