- Entenda a diferença entre fonte primária e secundária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.223", "page_number": 223, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29 da Constituição Federal", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:34:54.046825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=223", "doc_key": "4ac7cb2e835d01efed6f9ee0f0e8e2e2"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'cf6b36258fb2f55ed04ab453c43b7c66de0919c6a56c8b8d42e989c6e6ee5dc0'),
  ('cpiuris2025::817687a974aca3716b49a10208e7317c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Introdução ao Direito Empresarial', '## Introdução ao Direito Empresarial

Resumo objetivo: Este texto apresenta a introdução ao direito empresarial, destacando sua importância e abordagens. O direito empresarial é uma disciplina jurídica que regula as relações entre os atores do mercado, incluindo empresas, sócios, funcionários e clientes.

### Conceitos
- **Direito Empresarial**: Disciplina jurídica que regula as relações entre os atores do mercado
- **Relações de mercado**: Interatividade entre empresas, sócios, funcionários e clientes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância do direito empresarial na regulação de relações no mercado
- Destaque as principais áreas abordadas pelo direito empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.2", "page_number": 2, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:35:25.253010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=2", "doc_key": "817687a974aca3716b49a10208e7317c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e6b0b448a35ca2c25fd6e1d7e93209fd816635d3f0cd3e3de46a672e27798970'),
  ('cpiuris2025::16e9e9ee7902bcc6b482102823a11e37', 'doutrina', 'cp_iuris', 'Direito Empresarial — Autor de obra jurídica', '## Autor de obra jurídica

Informações biográficas sobre o autor do texto, destacando sua formação acadêmica e experiência como professor.

### Conceitos
- **Mestre**: Título acadêmico obtido após a conclusão de um curso de graduação
- **Especialista**: Certo nível de especialização em uma área específica do direito
- **Professor**: Pessoal que ensina e inicia os alunos em um campo específico

### Dicas de prova
- Reconheça a importância da formação acadêmica do autor para entender sua abordagem no texto.
- Destaque a experiência como professor e seu impacto na formação de conhecimento jurídico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.3", "page_number": 3, "discipline": "Direito Empresarial", "legal_refs": [], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:35:44.317801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=3", "doc_key": "16e9e9ee7902bcc6b482102823a11e37"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f1302f8fcb8cab306695bf936aec0ccfb30cfa6f728dd9834eefa8e0be13db23'),
  ('cpiuris2025::5d05112af2c50a117e76b0a60a126ab2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Origem e evolução histórica do Direito Empresarial', '## Origem e evolução histórica do Direito Empresarial

O Direito Empresarial tem suas origens na história, passando por fases como o direito consuetudinário, a teoria dos atos de comércio e a teoria da empresa.

### Conceitos
- **Direito Consuetudinário**: Regra jurídica adotada pela sociedade
- **Teoria dos Atos de Comércio**: Fase da evolução do Direito Empresarial que se concentra nos atos comerciais
- **Teoria da Empresa**: Fase final da evolução do Direito Empresarial que se concentra na empresa como unidade jurídica

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das fases da evolução do Direito Empresarial
- Conheça as regras básicas do direito consuetudinário, teoria dos atos de comércio e teoria da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:36:10.313560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=4", "doc_key": "5d05112af2c50a117e76b0a60a126ab2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b66c67a7675c471df14d853b6998446d79c706b88ea34bd44ae1b1d875d607cc'),
  ('cpiuris2025::e52f94db2a310af651f13ed99c95c329', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro de Empresa', '## Registro de Empresa

Discute as considerações gerais para o registro de empresa, incluindo a Junta Comercial e Departamento de Registro Empresarial e Integração (DREI), bem como os processos decisórios e revisionais.

### Conceitos
- **Parasitismo**: Condução irregular de empresa
- **Departamento de Registro Empresarial e Integração (DREI)**: Entidade responsável pelo registro de empresas
- **Junta Comercial**: Órgão que regulamenta as sociedades comerciais
- **Atos de registro de empresa**: Ações necessárias para o registro de uma empresa
- **Registro das Cooperativas**: Processo específico para a inscrição de cooperativas
- **Regras importantes**: Normas fundamentais para o registro de empresas
- **Processo decisório do registro de empresa**: Procedimento para a aprovação ou rejeição do registro
- **Processo revisional**: Revisão do processo de registro de empresa

### Referências legais
- Art. 1.234 da Lei 9.456/1997

### Dicas de prova
- Entenda a importância do DREI e da Junta Comercial no registro de empresas
- Conheça as regras importantes para o registro de empresas
- Aprenda a diferenciar entre atos de registro de empresa e processos decisórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234 da Lei 9.456/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:36:59.641789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=4", "doc_key": "e52f94db2a310af651f13ed99c95c329"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'efe603e9efc4551a0101fca86e71d6e0777b43c037983f3d3d1f3675c4a14f64'),
  ('cpiuris2025::3faf50e462158673631ecbae0eecac19', 'doutrina', 'cp_iuris', 'Direito Empresarial — Estatuto do Empreendedor', '## Estatuto do Empreendedor

Rege a estabilidade e eficácia dos livros contábeis, bem como os balanços anuais das empresas.

### Conceitos
- **Livro Contábil**: Documento que registra as transações financeiras de uma empresa
- **Eficácia Probatória**: Qualidade da prova que demonstra a veracidade de um fato ou evento
- **Balanço Anual**: Relatório financeiro que apresenta o estado patrimonial e operacional de uma empresa ao final do ano
- **Estabilidade Empresarial**: Condição em que a empresa permanece existente após a alteração de sua estrutura ou capital

### Referências legais
- Art. 153 da Lei 11.101/2005
- Súmula 395 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Estabilidade Empresarial

### Dicas de prova
- Entenda a diferença entre estabilidade e eficácia probatória
- Conheça as implicações da alteração do capital ou estrutura de uma empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Empresarial", "legal_refs": ["Art. 153 da Lei 11.101/2005", "Súmula 395 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Estabilidade Empresarial"], "confidence": 0.8, "extracted_at": "2026-05-27T01:37:26.568835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=4", "doc_key": "3faf50e462158673631ecbae0eecac19"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '17f91e0be1f3df8df276692e1b87f9d4eca945a9497109a2d1c69ec4138b9302'),
  ('cpiuris2025::7f642a4ab9a1a8a778b16abb6bf2f796', 'doutrina', 'cp_iuris', 'Direito Empresarial — Princípios do Nome Empresarial', '## Princípios do Nome Empresarial

Descreve os princípios que regem a formação e proteção do nome empresarial.

### Conceitos
- **Nome Empresarial**: Identidade única da empresa
- **Princípios do Nome Empresarial**: Regulamentam a formação e proteção do nome empresarial

### Referências legais
- Art. 55 da Lei nº 11.1017/2005

### Dicas de prova
- Entenda os princípios que regem o nome empresarial
- Conheça a importância da proteção do nome empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.4 (4)", "page_number": 4, "discipline": "Direito Empresarial", "legal_refs": ["Art. 55 da Lei nº 11.1017/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:37:42.598265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=4", "doc_key": "7f642a4ab9a1a8a778b16abb6bf2f796"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8fa41ce3d15cad821e3299ff95adb49ad9e79bb4988ea4e435fd1c5ca2778c28'),
  ('cpiuris2025::d47449f733679bc19978add287412021', 'doutrina', 'cp_iuris', 'Direito Empresarial — Teoria Geral do Direito Societário', '## Teoria Geral do Direito Societário

Trata-se de capítulo que aborda a teoria geral do direito societário, incluindo conceitos como sociedade empresária, personalização e desconsideração da personalidade jurídica.

### Conceitos
- **Sociedade Empresária**: Entidade jurídica formada por pessoas físicas ou jurídicas para realizar atividades econômicas
- **Personalização**: Atividade que consiste na alteração da estrutura e composição da sociedade para adaptá-la às necessidades específicas de cada caso
- **Desconsideração da Personalidade Jurídica**: Teoria que permite a responsabilização direta do proprietário ou controlador da sociedade por atos cometidos pela mesma

### Referências legais
- Art. 51 da Lei nº 11.101/2005

### Dicas de prova
- Entenda a diferença entre Teoria Menor e Teoria Maior da Desconsideração da Personalidade Jurídica
- Conheça as modalidades de desconsideração da personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Empresarial", "legal_refs": ["Art. 51 da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:38:18.947108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=5", "doc_key": "d47449f733679bc19978add287412021"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f3ff308210daa18ac6b9778228f795e497d2f6e0c2a1bde55faa7c0118754dab'),
  ('cpiuris2025::4959b1d4c27c18233eff6326a8a4f2b7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Classificação das sociedades', '## Classificação das sociedades

O texto aborda a classificação das sociedades, incluindo as formas de exercício da atividade econômica, responsabilidade dos sócios e regime de constituição e dissolução.

### Conceitos
- **Sociedade por Quota**: Sociedade em que os sócios têm direito a um valor determinado sobre o capital social.
- **Sociedade por Ações**: Sociedade em que os sócios são proprietários de ações da empresa.
- **Sociedade por Participação**: Sociedade em que os sócios têm direito a uma participação na gestão e no lucro da empresa.
- **Sociedade Irregular**: Sociedade que não se enquadra nas outras formas de sociedade previstas na lei.

### Referências legais
- Art. 143 do Código Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Sociedades por Quota

### Dicas de prova
- Entenda a diferença entre Sociedade por Quota e Sociedade por Ações.
- Conheça os requisitos para a constituição de uma sociedade irregular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 do Código Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Sociedades por Quota"], "confidence": 0.8, "extracted_at": "2026-05-27T01:38:46.506789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=5", "doc_key": "4959b1d4c27c18233eff6326a8a4f2b7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '29b132b9f953ffae80acff8342994b83e887230698091177f9e0623232d2fbea'),
  ('cpiuris2025::837b55484f2336334dbf034fea024d07', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusulas essenciais e não essenciais no contrato social', '## Cláusulas essenciais e não essenciais no contrato social

Descreve as cláusulas essenciais e não essenciais em um contrato social, bem como as participações nos resultados e a forma do contrato.

### Conceitos
- **Cláusula essencial**: cláusula fundamental e obrigatória para a existência ou continuidade da sociedade
- **Cláusula não essencial**: cláusula que pode ser alterada ou excluída sem impacto na existência da sociedade
- **Participação nos resultados**: direito dos sócios à participação nos lucros e perdas da empresa
- **Forma do contrato social**: regras que regem a formação e a homologação do contrato social

### Referências legais
- Art. 123, Código Civil Brasileiro

### Dicas de prova
- Entenda a distinção entre cláusulas essenciais e não essenciais
- Conheça as participações nos resultados e sua importância para os sócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Empresarial", "legal_refs": ["Art. 123, Código Civil Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:39:13.096335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=5", "doc_key": "837b55484f2336334dbf034fea024d07"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'de644096b92e23a0331e7944b029a5430270d8329e41635473563b74ac473618'),
  ('cpiuris2025::661acd44626dd8f874c40774e061dd1e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos Societários', '## Tipos Societários

Descreve as diferentes formas de sociedades que podem ser criadas, incluindo limitada, unipessoal e outras, destacando suas características e regras.

### Conceitos
- **Sociedade Limitada**: Forma de sociedade em que os sócios são responsáveis apenas pelo valor da quota que detêm.
- **Limitação da Responsabilidade dos Sócios**: Regra que protege os sócios contra perdas pessoais
- **Sociedade Limitada Unipessoal**: Forma de sociedade limitada em que só há um sócio.
- **Código do Consumidor**: Lei que regula as relações entre consumidores e fornecedores
- **Responsabilidade Solidária**: Regra que obriga os sócios a responder solidariamente pelas dívidas da sociedade.
- **Cessão de Quotas**: Ato pelo qual um sócio transfere parte do seu capital para outra pessoa
- **Aquisição de Quotas**: Ato pela qual a sociedade adquire parte do capital de outra empresa

### Referências legais
- Art. 143 da Lei nº 11.101/2005

### Dicas de prova
- Entenda a diferença entre responsabilidade limitada e solidária
- Conheça as regras de cessão e aquisição de quotas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.5 (4)", "page_number": 5, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:39:54.473631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=5", "doc_key": "661acd44626dd8f874c40774e061dd1e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f6f0c675e05570ad5c8e421c657778c75e841436ce20487a2d89ba075dad6fd9'),
  ('cpiuris2025::742e6d8beb69645322b7ddebb9375f50', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Contratualis Menores', '## Sociedades Contratualis Menores

Trata-se de uma seção que aborda as sociedades contratualis menores, incluindo a sociedade em nome coletivo, a sociedade em comandita simples e a sociedade em conta de participação.

### Conceitos
- **Sociedade em Nome Coletivo**: Sociedade onde os sócios são considerados como um único patrimônio
- **Sociedade em Comandita Simples**: Sociedade onde os sócios são responsáveis pelos seus investimentos de forma individual
- **Sociedade em Conta de Participação**: Sociedade que permite aos sócios receber uma parte do lucro proporcional ao seu investimento

### Referências legais
- Art. 141 da CLT
- ...

### Dicas de prova
- Entenda a diferença entre sociedade em nome coletivo e sociedade em comandita simples
- Conheça os requisitos para a constituição de uma sociedade em conta de participação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Empresarial", "legal_refs": ["Art. 141 da CLT", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:40:19.824120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=6", "doc_key": "742e6d8beb69645322b7ddebb9375f50"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '87e46ec040f2cdd81ffff36f35a007436022ebd09d0ef01f7446296515488b7f'),
  ('cpiuris2025::c2447763e12b407fb77afeb07716f5d4', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Anônimas', '## Sociedades Anônimas

Trata-se de uma seção que aborda a formação, classificação e estrutura das sociedades anônimas, bem como os seus órgãos societários, deveres dos administradores e responsabilidade dos acionistas.

### Conceitos
- **Sociedade Anônima**: Entidade jurídica que pode ser aberta ao público
- **Comissão de Valores Mobiliários (CVM)**: Autoridade reguladora do mercado de valores
- **Administrador**: Pessoa responsável pela gestão da sociedade
- **Açõista**: Proprietário de ações da sociedade
- **Controle**: Relação de dependência entre a sociedade e o acionista controlador
- **Governança Corporativa**: Sistema de controle e supervisão dos órgãos societários

### Referências legais
- Art. 143 do Código Civil
- Súmula 455 do STF

### Jurisprudência
- RE 123456
