  ('cpiuris2025::2581942b04d041181a87b6b6d5dfd396', 'doutrina', 'cp_iuris', 'Direito Empresarial — Proteção Intelectual', '## Proteção Intelectual

Trecho aborda a legislação específica de proteção intelectual, incluindo patentes, marcas, designs e indicativos geográficos.

### Conceitos
- **Patente**: direito que concede exclusividade para produzir e vender uma invenção ou modelo de utilidade
- **Design**: direito que protege a forma e a aparência de um produto
- **Marca**: direito que protege o nome, símbolo ou expressão de uma empresa
- **Indicação Geográfica**: direito que protege indiciares geográficos de produtos

### Referências legais
- Art. 9 da Lei 9.472/1997
- Súmula 397 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção Intelectual

### Dicas de prova
- Entenda a diferença entre patente e design
- Conheça as regras de titularidade da patente
- Aprenda a importância das indicativas geográficas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.6 (4)", "page_number": 6, "discipline": "Direito Empresarial", "legal_refs": ["Art. 9 da Lei 9.472/1997", "Súmula 397 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção Intelectual"], "confidence": 0.8, "extracted_at": "2026-05-27T01:41:45.153209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=6", "doc_key": "2581942b04d041181a87b6b6d5dfd396"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7b448f1788bccf7dcba9cf0521fdb32395c4f29e4581f69b692ef0d379dda5f9'),
  ('cpiuris2025::193ea1ed1ce2c93d7f25abba76ad0d55', 'doutrina', 'cp_iuris', 'Direito Empresarial — Direito Cambiário', '## Direito Cambiário

Trata-se de um capítulo que aborda o desenvolvimento histórico do direito cambiário, incluindo as fases do período italiano, francês e alemão, além da classificação dos títulos de crédito.

### Conceitos
- **Direito Cambiário**: Brancha do direito que regula os contratos de crédito
- **Título de Crédito**: Documento que confere ao devedor o direito de adiantar o pagamento de uma dívida
- **Modelo**: Forma como um título de crédito é estruturado e apresentado
- **Estrutura**: Organização interna de um título de crédito

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a classificação dos títulos de crédito e os principais modelos utilizados
- Conheça as fases do desenvolvimento histórico do direito cambiário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:42:09.213434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=7", "doc_key": "193ea1ed1ce2c93d7f25abba76ad0d55"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '69bcfd52b27c01d73cfc55d9513ea2c10334606580d1461cb786c46bb114b35f'),
  ('cpiuris2025::4ee9f3e83122d1d593aad598edd0af29', 'doutrina', 'cp_iuris', 'Direito Empresarial — Hipóteses de emissão e circulação de documentos financeiros', '## Hipóteses de emissão e circulação de documentos financeiros

Resumo do conteúdo das seções 4.3 a 9.2, abordando hipóteses de emissão, circulação, endossos, aval, exigibilidade do crédito cambial, protesto, letra de câmbio e saque.

### Conceitos
- **Emissão de documentos financeiros**: Procedimento pelo qual um documento é criado para representar uma obrigação ou direito
- **Circulação de documentos financeiros**: Movimentação do documento financeiro entre as partes envolvidas
- **Endosso**: Ato de assinar um documento em nome de outrem, confirmando a autenticidade do documento
- **Aval**: Garantia oferecida por uma pessoa para garantir o cumprimento de uma obrigação
- **Fiança**: Garantia oferecida por uma pessoa para garantir o cumprimento de uma obrigação, diferente do aval
- **Outorga conjugal**: Obrigação conjunta de duas pessoas casadas
- **Crédito cambial**: Direito ao recebimento de um valor em moeda estrangeira

### Referências legais
- Art. 1.234 da Lei 9.123/1996

### Dicas de prova
- Entenda a diferença entre aval e fiança
- Conheça as hipóteses de emissão e circulação de documentos financeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234 da Lei 9.123/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:42:52.955381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=7", "doc_key": "4ee9f3e83122d1d593aad598edd0af29"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '20aadce4e159cc47c1a60b5a46de42411cbdfbd231cb10b1f8ded68b2ba0a50e'),
  ('cpiuris2025::b2c34ba41a6f18e4b8bca4ffb397c884', 'doutrina', 'cp_iuris', 'Direito Empresarial — Vencimento e Pagamento de Obrigações', '## Vencimento e Pagamento de Obrigações

Trecho aborda as regras para o vencimento e pagamento de obrigações, incluindo ação cambial e nota promissória.

### Conceitos
- **Ação Cambial**: ação judicial que visa cobrar uma dívida ou obrigação
- **Nota Promissória**: instrumento que compromete o devedor a pagar uma determinada quantia
- **Vencimento**: ocorrência do prazo de vencimento de uma obrigação

### Referências legais
- Art. 173 do Código Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ação cambial e nota promissória
- Conheça os requisitos legais para o vencimento de uma obrigação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito Empresarial", "legal_refs": ["Art. 173 do Código Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:43:13.954984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=7", "doc_key": "b2c34ba41a6f18e4b8bca4ffb397c884"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6d3c3a0ceb26b794f49cc435451fa17d2cf8e0efedbe5debf7e1bcda50617118'),
  ('cpiuris2025::53180e540c0ba5726a10ef595366717f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Duplicata', '## Duplicata

Regras e conceitos relacionados à duplicata, incluindo aceite, protesto e prazos para cobrança.

### Conceitos
- **duplicata**: documento que comprova a existência de uma dívida
- **duplicata virtual**: duplicata eletrônica ou sob forma escritural
- **aceite na duplicata**: conformidade do devedor com as condições estabelecidas no documento
- **protesto da duplicata**: aviso formal que a empresa envia ao devedor para cobrança
- **prazos para cobrança da duplicata**: pontos em que o devedor deve realizar o pagamento

### Referências legais
- Art. 12 da Lei nº 11.101/2005

### Dicas de prova
- Entenda a diferença entre duplicata e duplicata virtual.
- Conheça os requisitos para aceite na duplicata e protesto da duplicata.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.7 (4)", "page_number": 7, "discipline": "Direito Empresarial", "legal_refs": ["Art. 12 da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:43:38.502246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=7", "doc_key": "53180e540c0ba5726a10ef595366717f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '81b25a2287588a1694da55c048557960bf318d7f38c45f5aea3c25fcd7843429'),
  ('cpiuris2025::654201ff80261012b6463c8af250fdcc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Reformas da Lei 11.101/2005', '## Reformas da Lei 11.101/2005

Resumo do conteúdo das inovações e alterações introduzidas pela Lei 11.101/2005 em relação ao Decreto-Lei 7.661/45.

### Conceitos
- **Lei 11.101/2005**: Reformas introduzidas na legislação empresarial
- **Decreto-Lei 7.661/45**: Legislação anterior à reforma
- **Foro competente**: Escolha do juiz competente para processos
- **Participação do Ministério Público**: Função do MP na fiscalização das empresas
- **CPC aplicável**: Legislação que regula procedimentos judiciais
- **Agravo de instrumento**: Recurso especial em processos falimentares e recuperacionais
- **Administrador judicial**: Função do administrador no processo falimentário
- **Recuperação judicial**: Processo que visa reestruturar a empresa

### Referências legais
- Art. 1 da Lei 11.101/2005
- Súmula 455 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Recuperação Judicial

### Dicas de prova
- Entenda a diferença entre recuperação e concordata
- Conheça o processo de recuperação judicial e seus passos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1 da Lei 11.101/2005", "Súmula 455 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Recuperação Judicial"], "confidence": 0.8, "extracted_at": "2026-05-27T01:44:22.943215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=8", "doc_key": "654201ff80261012b6463c8af250fdcc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f63709a5be01f1a376f86091fdef7a42bae29f25dee8557f963f9bb6393644f1'),
  ('cpiuris2025::a3378a80d058091f7a06b7d35802973b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Falências e Recuperação Judicial', '## Falências e Recuperação Judicial

Trecho aborda as etapas do processo falimentar, legitimados a pedir falência, fundamentos do pedido de falência e defesas do devedor.

### Conceitos
- **Recuperação Judicial**: Processo que visa reestruturar dívidas do empresário
- **Falência**: Declaração judicial da insolvência jurídica de uma empresa
- **Devedor**: Parte que contrai débitos
- **Insolvência Jurídica**: Situação em que a empresa não tem recursos para atender aos seus débitos
- **Legitimados a Pedir Falência**: Pessoas ou entidades que podem solicitar a falência de uma empresa
- **Sentença Declaratória da Falência**: Decisão judicial que declara a falência de uma empresa
- **Suspensão das Execuções Individuais**: Mudança na ordem de prioridade das execuções judiciais
- **Termo Legal da Falência**: Prazo para que o devedor execute as medidas necessárias após a declaração da falência

### Referências legais
- Art. 183 do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Falências e Recuperação Judicial

### Dicas de prova
- Entenda a diferença entre recuperação judicial e falência
- Conheça os legitimados a pedir falência e as etapas do processo falimentar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Empresarial", "legal_refs": ["Art. 183 do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Falências e Recuperação Judicial"], "confidence": 0.8, "extracted_at": "2026-05-27T01:44:58.221997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=8", "doc_key": "a3378a80d058091f7a06b7d35802973b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ddd986b03a53b00f83c11d2efd5e445645f18152abdc7bef37d42a6fd111138e'),
  ('cpiuris2025::6026afc8730f60b589becf68ef58625a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recurso contra decisão de falência e outros procedimentos em falências', '## Recurso contra decisão de falência e outros procedimentos em falências

Trecho aborda os procedimentos legais relacionados à falência, incluindo o recurso contra decisões, requerimento doloso de falência e habilitação dos créditos.

### Conceitos
- **Recurso contra decisão**: Ação para impugnar uma decisão tomada em um processo de falência.
- **Decisão de falência**: Título que se refere à decisão do juiz que declara a falência de uma empresa ou pessoa jurídica.
- **Falência**: Processo judicial que visa liquidar os bens e dívidas de uma empresa ou pessoa jurídica incapaz de pagar suas obrigações.
- **Credores do falido**: Partes que têm direito a receber pagamento de uma empresa ou pessoa jurídica em falência.
- **Créditos do falido**: Direitos que o falido tem contra terceiros, como credores e outros devedores.

### Referências legais
- Art. 183 da Lei nº 11.101/2005

### Jurisprudência
- RE 123456

