  ('cpiuris2025::10972402452fa3a6333c1fa7dc4f56e5', 'doutrina', 'cp_iuris', 'Direito Empresarial — Teoria da Imprevisão e Pacta Sunt Servanda', '## Teoria da Imprevisão e Pacta Sunt Servanda

Resumo do capítulo sobre teoria da imprevisão e pacta sunt servanda, incluindo exceções e contratos mercantil.

### Conceitos
- **Pacta sunt servanda**: Cláusula que obriga as partes a cumprir com os acordos feitos
- **Exceção não adimpleti contactus**: Exceção utilizada para negar a eficácia de um contrato por falta de cumprimento das condições estabelecidas

### Referências legais
- Art. 107 do CC/2016
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Pacta sunt servanda

### Dicas de prova
- Entenda a importância da pacta sunt servanda e como ela é aplicada em diferentes situações
- Identifique as exceções à pacta sunt servanda, como a exceção não adimpleti contactus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito Empresarial", "legal_refs": ["Art. 107 do CC/2016", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Pacta sunt servanda"], "confidence": 0.8, "extracted_at": "2026-05-27T01:46:25.760268+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=9", "doc_key": "10972402452fa3a6333c1fa7dc4f56e5"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '311eb8117c5b257b1af60e6aa5d53602ed20dfdd328174e13a574674d52d4d03'),
  ('cpiuris2025::a4d1292c477f5ac0d06f0bb7b0cd9733', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Bancários', '## Contratos Bancários

Trata os requisitos e atividades das contrapções bancárias, incluindo espécies de operações passivas e ativas.

### Conceitos
- **Contrato bancário**: Acordo entre duas ou mais partes que envolve a transferência de valores ou bens.
- **Operação passiva**: Atividade bancária que envolve o recebimento de depósitos ou a emissão de títulos.
- **Operação ativa**: Atividade bancária que envolve o pagamento de saques ou a emissão de cheques.
- **Alienação fiduciária em garantia**: Condição em que um banco detém a posse de um bem, mas não é o proprietário.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Perguntas sobre espécies de operações passivas e ativas podem ser respondidas com base na definição de cada uma.
- A alienação fiduciária em garantia é um conceito importante para entender os contratos bancários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:46:52.213470+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=9", "doc_key": "a4d1292c477f5ac0d06f0bb7b0cd9733"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e9baab3429223575e1cf95d327daa01167eee0564cfcdc0bb98fbc960c0ce241'),
  ('cpiuris2025::ecacc5e5a18071906dd949cfca6e58fc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Seguro', '## Contratos de Seguro

Descreve os diferentes tipos de seguros e suas características, além da natureza do contrato de seguro.

### Conceitos
- **Cessão de registro industrial**: A transferência do direito de registro industrial para outra pessoa.
- **Licença de uso de patente ou registro**: Permissão concedida por um titular de direitos de propriedade intelectual para que outra pessoa use seus bens intelectuais.
- **Transferência de tecnologia**: A mudança de uma empresa de uma tecnologia para outra, geralmente com a compra ou venda de ativos.
- **Comercialização de software**: O processo pelo qual um produto é vendido e distribuído para o público em geral.
- **Seguro de danos**: Um seguro que protege contra perdas ou danos causados por eventos imprevistos.
- **Seguro de pessoas**: Um seguro que protege contra riscos relacionados à vida e à saúde de indivíduos.
- **Seguro-saúde**: Um seguro que cobre os custos médicos e hospitalares de uma pessoa.
- **Capitalização**: A prática de acumular lucros em uma empresa, geralmente para financiar novas operações ou pagar dívidas.

### Referências legais
- Art. 1.234 da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Empresarial Extravagante

### Dicas de prova
- Entenda a natureza do contrato de seguro e suas diferentes formas.
- Conheça as características dos seguros de danos, pessoas e saúde.
- Aprenda sobre a capitalização e sua importância para as empresas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.9 (3)", "page_number": 9, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234 da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Empresarial Extravagante"], "confidence": 0.8, "extracted_at": "2026-05-27T01:47:40.373980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=9", "doc_key": "ecacc5e5a18071906dd949cfca6e58fc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd2e623dd473e1338df303c8c089caaa22a363ac0bedf3a6233b53e803aa9fc3d'),
  ('cpiuris2025::897ba31bf74e1c6c455b0e3dfe6e8692', 'doutrina', 'cp_iuris', 'Direito Empresarial — Marco legal das startups e do empreendedorismo inovador', '## Marco legal das startups e do empreendedorismo inovador

