### Conceitos
- **Startup**: Empreendimento de baixo risco com potencial de crescimento rápido
- **Inovação Empresarial**: Apoio à inovação e ao desenvolvimento de novas ideias em empresas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância do marco legal para startups e empreendedorismo inovador
- Destaque as características que definem uma startup', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.9 (4)", "page_number": 9, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:47:57.384299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=9", "doc_key": "897ba31bf74e1c6c455b0e3dfe6e8692"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fc54e0ec49f9ee90fc9cd87e475aac7a16ab958d3708b2e000d63827de188d29'),
  ('cpiuris2025::91e79cb8fe7426284983977161e9ad09', 'doutrina', 'cp_iuris', 'Direito Empresarial — Origem Histórica do Direito Empresarial', '## Origem Histórica do Direito Empresarial

O Direito Empresarial surgiu após a atividade econômica e se desenvolveu a partir da divisão entre o regime jurídico civil e comercial.

### Conceitos
- **Direito Comercial**: conjunto orgânico de normas relativas à atividade econômica
- **Regime Jurídico Civil**: regime jurídico que disciplina as atividades privadas
- **Regime Jurídico Comercial**: regime jurídico específico para a disciplina das atividades econômicas
- **Normas Particulares**: regras esparsas e difusas que regulam a atividade econômica desde a Antiguidade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre origem do Direito Empresarial

### Dicas de prova
- Entenda a distinção entre o regime jurídico civil e comercial
- Conheça as normas particulares à matéria comercial desde a Antiguidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre origem do Direito Empresarial"], "confidence": 0.8, "extracted_at": "2026-05-27T01:48:29.107352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=10", "doc_key": "91e79cb8fe7426284983977161e9ad09"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e6bc78f8b116a824840879bd1c4b174f958c3a532f32daed7705dd0e0fb85534'),
  ('cpiuris2025::641fef394f69017042652c1c2a71d5b4', 'doutrina', 'cp_iuris', 'Direito Empresarial — Origem e Evolução Histórica do Direito Empresarial', '## Origem e Evolução Histórica do Direito Empresarial

A origem do Direito Comercial está relacionada às mudanças econômicas, sociais, políticas e culturais da Idade Média para a Idade Moderna, com destaque para a ascensão social da burguesia.

### Conceitos
- **Direito Comercial**: relacionado às mudanças econômicas, sociais, políticas e culturais
- **Feudalismo**: regime social e econômico da Idade Média
- **Burguesia**: classe social ascendente na Idade Moderna
- **Comércio**: atividade econômica
- **Economia pré-capitalista**: economia sem capitalismo

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a relação entre o Direito Comercial e as mudanças econômicas da Idade Média para a Idade Moderna.
- Destaque a ascensão social da burguesia como fator importante na evolução do Direito Empresarial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:49:06.467707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=10", "doc_key": "641fef394f69017042652c1c2a71d5b4"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f3b65b815bcb5b1426c85f191e37926d918ae41f3ab8d21bd82a50571db953b1'),
  ('cpiuris2025::5800d11f0c0a3347987df7d16d55e92e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Origem e Evolução Histórica do Direito Empresarial', '## Origem e Evolução Histórica do Direito Empresarial

O Direito Empresarial surgiu na 1ª fase como o Direito Mercantil, caracterizado pela Teoria Subjetiva, onde o direito é produzido e aplicado por uma classe, nas corporações de ofício.

### Conceitos
- **Direito Comercial**: Regras e institutos criados pelas corporações de ofício
- **Corporações de Ofício**: Associações privadas que regulam as atividades dos comerciantes
- **Direito Estatutário**: Regras e institutos compilados em estatutos das corporações de ofício
- **Teoria Subjetiva**: Fase da evolução do Direito Empresarial, caracterizada pela produção e aplicação do direito por uma classe

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a Teoria Subjetiva como o núcleo do Direito Empresarial
- Conheça as corporações de ofício e seu papel na evolução do Direito Comercial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:49:38.503477+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=11", "doc_key": "5800d11f0c0a3347987df7d16d55e92e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1b3638ed919396b4d8c3664b0435876e6030b91671679f7368dad0fa5389783f'),
  ('cpiuris2025::82425cb16dc84be82b7ba18c73a2c4f6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Origem e Desenvolvimento do Direito Comercial', '## Origem e Desenvolvimento do Direito Comercial

A origem do Direito Comercial é marcada pelo surgimento da autonomia desse ramo do direito, com a identificação de características e institutos típicos. O advento da Doutrina Empresarialista, com o Tratactus de Mercatura, marcou um ponto importante no desenvolvimento do Direito Comercial.

### Conceitos
- **Direito Comercial**: ramo do direito que regula as atividades comerciais
- **Autonomia**: característica do Direito Comercial que permite a sua aplicação independente
- **Institutos típicos**: características e regras específicas do Direito Comercial
- **Doutrina Empresarialista**: escola de pensamento que desenvolveu o Direito Comercial
- **Tratactus de Mercatura**: obra de Benvenuto Stracha que marcou o advento da Doutrina Empresarialista
- **Manuais práticos**: obras que auxiliam os comerciantes no exercício de suas atividades
- **Atividade comercial**: exercício das atividades econômicas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Identificar a autonomia do Direito Comercial e seus institutos típicos
- Compreender o advento da Doutrina Empresarialista e sua importância no desenvolvimento do Direito Comercial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:50:11.417728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=11", "doc_key": "82425cb16dc84be82b7ba18c73a2c4f6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd1a0abb828edffb813c8baf8f30e03e4911c233bc6662d00ec3342d8a532a195'),
  ('cpiuris2025::450948a29ffd4c291c392e504c9099e6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Evolução Histórica do Direito Comercial', '## Evolução Histórica do Direito Comercial

O Direito Comercial evoluiu após a codificação, alcançando independência e separação do Direito Civil. Adotou dois sistemas: Teoria dos Atos de Comércio (francês) e Teoria da Empresa (italiana).

### Conceitos
- **Teoria dos Atos de Comércio**: Sistema francês que disciplina as relações comerciais
- **Teoria da Empresa**: Sistema italiano que disciplina a atividade econômica
- **Codificação Napoleônica**: Edição dos códigos civis e comerciais na França no século XIX

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da Teoria dos Atos de Comércio e da Teoria da Empresa no Direito Comercial
- Conheça a Codificação Napoleônica e sua influência no Direito Brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:50:52.462915+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=12", "doc_key": "450948a29ffd4c291c392e504c9099e6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e06b686a8e77e14c53e52653cef1085cadc708e65a4ffdada6a734bd25e69d30'),
  ('cpiuris2025::e18c74c42395b3870535708ef2aea64c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Objetificação do Direito Comercial', '## Objetificação do Direito Comercial

A objetificação do Direito Comercial ocorre com a codificação francesa de princípios do século XIX, abandonando o sistema subjectivo para um sistema objectivo que aplica-se a todos os atos de comércio.

### Conceitos
- **Mercantilidade**: definição do objeto da relação jurídica
- **Sistema Subjectivo**: sistema anterior ao Direito Comercial que se aplicava apenas a quem estivesse inscrito como comerciante
- **Sistema Objectivo**: sistema adotado pelo Direito Comercial que aplica-se a todos os atos de comércio

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Comercial

### Dicas de prova
- Entenda a mudança de mercantilidade e como isso afeta o Direito Comercial.
- Conheça as diferenças entre sistema subjectivo e sistema objectivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Comercial"], "confidence": 0.8, "extracted_at": "2026-05-27T01:51:18.936191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=12", "doc_key": "e18c74c42395b3870535708ef2aea64c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1b66f91e6bca4220211fbaa9c868368fb2a20b9a9fd9cd49c66e51d094cf01ff'),
  ('cpiuris2025::351d1283725d3ae346beb4268faf5367', 'doutrina', 'cp_iuris', 'Direito Empresarial — Teoria Objetiva do Direito Empresarial', '## Teoria Objetiva do Direito Empresarial

A Teoria Objetiva define o Direito Empresarial como o direito dos atos de comércio, considerando o comerciante como o sujeito que pratica atos de comércio, não mais necessariamente o sujeito matriculado em uma Corporação de Ofício.

### Conceitos
- **Teoria Objetiva**: Define o Direito Empresarial como o direito dos atos de comércio
- **Comerciante**: O sujeito que pratica atos de comércio, não necessariamente o sujeito matriculado em uma Corporação de Ofício
- **Atos de Comércio**: Relações jurídicas que se enquadram na definição genérica de atos de comércio

### Referências legais
- Decreto n.º 737 de 1850

### Dicas de prova
- Entenda a diferença entre Teoria Subjetiva e Teoria Objetiva do Direito Empresarial
- Conheça as atividades que não são consideradas atos de comércio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Empresarial", "legal_refs": ["Decreto n.º 737 de 1850"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:51:50.155715+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=13", "doc_key": "351d1283725d3ae346beb4268faf5367"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3c3d325b1e10f44f8a84cfa08b7c58d904b32ace02a34523bbbdc8c44917815c'),
  ('cpiuris2025::84a87e22e0a8ba1f480a41074a995e6a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Teoria dos Atos de Comércio e sua evolução', '## Teoria dos Atos de Comércio e sua evolução

A Teoria dos Atos de Comércio foi desenvolvida para definir o comerciante, mas não havia definição jurídica clara dos atos de comércio. Isso levou à necessidade de uma nova teoria que englobasse mais atividades econômicas.

### Conceitos
- **Teoria dos Atos de Comércio**: teoria que define o comerciante
- **Comerciante**: pessoa que pratica atos de comércio
- **Atos de Comércio**: práticas econômicas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a evolução da Teoria dos Atos de Comércio e sua importância no Direito Empresarial.
- Identifique as características da segunda fase do desenvolvimento da Teoria dos Atos de Comércio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T01:52:24.779406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=13", "doc_key": "84a87e22e0a8ba1f480a41074a995e6a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b9dcc8ae5d24da95a2b802ddcebcee426aff9ba9783c68d0c7742310e62f2668'),
  ('cpiuris2025::81270b881162d06cba76fb524d2c84c4', 'doutrina', 'cp_iuris', 'Direito Empresarial — Teoria da Empresa', '## Teoria da Empresa

A Teoria da Empresa foi desenvolvida após a Revolução Industrial e é baseada na ideia de que a empresa é um fenômeno jurídico poliédrico, com diferentes perfis: subjetivo (pessoa física ou jurídica), funcional (atividade econômica organizada), objetivo (conjunto de bens afetados à atividade econômica) e corporativo (comunidade laboral).

### Conceitos
- **Teoria da Empresa**: fenômeno jurídico poliédrico que abrange diferentes perfis: subjetivo, funcional, objetivo e corporativo.
- **Atos de Comércio**: atividades econômicas organizadas
- **Pessoa Física ou Jurídica**: sujeito da empresa
- **Atividade Econômica Organizada**: atividade econômica com um determinado escopo produtivo
- **Conjunto de Bens**: objeto da atividade econômica desempenhada
- **Comunidade Laboral**: instituição que reúne o empresário e seus auxiliares ou colaboradores

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre os perfis da empresa: subjetivo, funcional, objetivo e corporativo.
- Conheça a contribuição de Alberto Asquini para a formulação do conceito jurídico de empresa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:53:04.141080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=14", "doc_key": "81270b881162d06cba76fb524d2c84c4"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd75ddabe92e31e24321421db07e61e275be939acd3c611d9e3a6d85753873f21'),
  ('cpiuris2025::483b7fc4f2d02b8c3798625fa0c9b747', 'doutrina', 'cp_iuris', 'Direito Empresarial — Perfil Corporativo e Teoria da Empresa', '## Perfil Corporativo e Teoria da Empresa

O perfil corporativo é organizado em função de um fim econômico comum, mas sua validade é questionada. A teoria poliédrica foi reduzida à teoria triédrica, considerando apenas os perfis do empresário, estabelecimento e capital social.

### Conceitos
- **Perfil Corporativo**: Organização da empresa em função de um fim econômico comum
- **Teoria Poliédrica**: Teoria que considera vários perfis na empresa
- **Teoria Triédrica**: Teoria que considera apenas três perfis na empresa: empresário, estabelecimento e capital social

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre teoria poliédrica e triédrica
- Conheça os perfis do empresário, estabelecimento e capital social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T01:53:28.572375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=14", "doc_key": "483b7fc4f2d02b8c3798625fa0c9b747"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8ca5c67a5521f9598da461d4b76525130e738ad801877c54c7386de4eaf97cce'),
  ('cpiuris2025::96f8422926742e5a27574b13c6d007af', 'doutrina', 'cp_iuris', 'Direito Empresarial — Origem e evolução histórica do Direito Empresarial', '## Origem e evolução histórica do Direito Empresarial

O Direito Empresarial surgiu a partir da unificação formal do direito privado, disciplinando as relações civis e comerciais em um único diploma legislativo. O atual Código Civil brasileiro se inspira fortemente na codificação italiana, que promoveu uma mudança no conceito de empresa, passando a ser o direito da empresa organizada.

### Conceitos
- **Unificação formal do direito privado**: Disciplina das relações civis e comerciais em um único diploma legislativo
- **Código Civil italiano**: Promoveu uma mudança no conceito de empresa, passando a ser o direito da empresa organizada
- **Teoria da Empresa**: Orienta todo o regime jurídico empresarial
- **Conceito de empresa**: Atividade econômica organizada, que pode abranger diversas espécies de atividade econômica
- **Empresário**: Aquele que exerce profissionalmente atividade econômica organizada
- **Estabelecimento empresarial**: Complexo de bens usado para o exercício de uma atividade econômica organizada

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a unificação formal do direito privado e sua influência no Direito Empresarial
- Conheça o conceito de empresa e como ele orienta todo o regime jurídico empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T01:54:20.727748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=15", "doc_key": "96f8422926742e5a27574b13c6d007af"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a2b3c3600c9da5b02259ec978407ab5e9dfe407e791a621009742edaf3f8e31c'),
  ('cpiuris2025::4f71bf54176b12aaf9fbb8eedd975674', 'doutrina', 'cp_iuris', 'Direito Empresarial — Unificação do Direito Privado e sua relação com o Direito Empresarial', '## Unificação do Direito Privado e sua relação com o Direito Empresarial

A unificação do Direito Privado no Código Civil italiano de 1942 não significa que o Direito Empresarial perdeu autonomia, mas sim que as regras nucleares estão em um mesmo diploma legislativo.

### Conceitos
- **Direito Empresarial**: direito autônomo e distinto do Direito Civil
- **Unificação do Direito Privado**: regras nucleares no mesmo diploma legislativo, como o Código Civil
- **Teoria da Empresa**: substituiu a Teoria dos Atos de Comércio
- **Código Civil italiano de 1942**: rompe com a tradição das codificações

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a relação entre o Direito Empresarial e o Direito Civil
- Conheça as principais teorias que regem a empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:54:44.255590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=15", "doc_key": "4f71bf54176b12aaf9fbb8eedd975674"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '79092b1fd1f5fbb7255e0035d690626986f63b10e2e0d0721465e8618cd302e7'),
  ('cpiuris2025::18d7850f1483160bcaeda776603711d7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Evolução do Direito Comercial no Brasil', '## Evolução do Direito Comercial no Brasil

A evolução do direito comercial brasileiro, desde as Ordenações Manuelinas até o Código Civil de 2002, que adotou a Teoria da Empresa e abandonou a Teoria dos Atos de Comércio.

### Conceitos
- **Teoria dos Atos de Comércio**: Teoria jurídica que considera as atividades comerciais como atos específicos
- **Teoria da Empresa**: Teoria jurídica que considera a empresa como uma unidade jurídica autônoma
- **Código Comercial Napoleônico**: Código de direito comercial francês que influenciou o desenvolvimento do Código Comercial brasileiro
- **Código Civil Italiano de 1942**: Código civil italiano que introduziu a Teoria da Empresa no direito brasileiro

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Empresarial

### Dicas de prova
- Entenda a evolução histórica do direito comercial brasileiro e as diferenças entre as Teorias dos Atos de Comércio e da Empresa
- Conheça o Código Civil de 2002 e sua adopção da Teoria da Empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Empresarial"], "confidence": 0.8, "extracted_at": "2026-05-27T01:55:20.125075+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=16", "doc_key": "18d7850f1483160bcaeda776603711d7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '92c581f35b9a66bef69e7004d2bdb2b9b6b272a82ab9fd32f930605bfbfd0be3'),
  ('cpiuris2025::8e2066d449b57fbe99f6442abb8298b6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Unificação da codificação no Direito Empresarial', '## Unificação da codificação no Direito Empresarial

A unificação da codificação seria prejudicial para o ramo empresarial do direito, devido à complexidade do mercado e à relação econômica e social. O Código Civil de 2002 tentou trazer essa intenção, mas acabou se concentrando pouco no Direito Empresarial.

### Conceitos
- **Unificação da codificação**: A ideia de unificar as leis do Direito Empresarial em uma única fonte
- **Complexidade do mercado**: A complexidade e a relação econômica e social que afetam o ramo empresarial do direito
- **Código Civil de 2002**: Lei que tentou trazer a unificação formal do direito privado, mas acabou se concentrando pouco no Direito Empresarial
- **Direito Empresarial**: Ramamento do direito que regula as relações entre os empresários e seus clientes
- **Código Comercial brasileiro de 1850**: Lei que foi divida em três partes, mas atualmente está em vigor apenas na ''Parte Segunda — Do Comércio Marítimo''
- **Reforma do Código Comercial**: Projeto de Lei que propõe a reforma do Código Comercial e a alteração da parte do Código Civil que trata do Direito Empresarial
- **Falência**: Lei que tratava sobre falência, foi revogada em 1945
- **Comércio em Geral**: Ramamento do direito que regula as relações entre os empresários e seus clientes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Perguntas sobre a unificação da codificação e sua relação com a complexidade do mercado
- Distinção entre o Código Civil de 2002 e o Direito Empresarial
- Entendimento do Projeto de Lei do Senado (PLS nº 487/2013) e sua proposta de reforma do Código Comercial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:56:15.487291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=16", "doc_key": "8e2066d449b57fbe99f6442abb8298b6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '37ab28dad56ada0393d5231321074687e09e25e7f7bc80149a72cbd1446553c8'),
  ('cpiuris2025::d50f294e21b6810315f365577bff4fc6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Objeto do Direito Empresarial', '## Objeto do Direito Empresarial

O Direito Empresarial cuida da atividade econômica organizada pelo empresário, voltada para a produção e circulação de bens ou serviços.

### Conceitos
- **Empresa**: atividade exercida pela pessoa física ou jurídica
- **Teoria da Empresa**: adotada pelo Código Civil de 2002, substituindo a Teoria dos Atos de Comércio
- **Código Comercial de 1850**: que definia atividades específicas como mercancia
- **Burguesia**: classe social que rompe com o feudo e cria regulamentação para proteger suas atividades

### Referências legais
- Art. 1.234 do Código Civil de 2002
- Súmula 123 da STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: empresa e sua definição

### Dicas de prova
- Entenda a diferença entre Teoria dos Atos de Comércio e Teoria da Empresa
- Conheça as atividades que são consideradas mercancia no Código Comercial de 1850', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.17", "page_number": 17, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234 do Código Civil de 2002", "Súmula 123 da STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: empresa e sua definição"], "confidence": 0.8, "extracted_at": "2026-05-27T01:56:48.158696+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=17", "doc_key": "d50f294e21b6810315f365577bff4fc6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8e7367a02f4b10ae25973c8d4c1c947b4b98f2fbdeb391f22d353e2834931b13'),
  ('cpiuris2025::b1be27a57abea16ec75bcf336f6b4311', 'doutrina', 'cp_iuris', 'Direito Empresarial — Perfil objetivo, funcional e corporativo da empresa', '## Perfil objetivo, funcional e corporativo da empresa

O perfil objetivo se refere aos bens utilizados pelo empresário individual ou sociedade empresária; o perfil funcional à dinâmica empresarial; e o perfil corporativo ou institucional aos colaboradores da empresa.

### Conceitos
- **Perfil objetivo**: Bens corpóreos e incorpóreos utilizados pelo empresário individual ou sociedade empresária
- **Perfil funcional**: Dinâmica empresarial, ou seja, a atividade própria do empresário ou da sociedade empresária
- **Perfil corporativo ou institucional**: Colaboradores da empresa, empregados que com o empresário envidam esforços à consecução dos objetivos empresariais

### Referências legais
- Art. 966 do Código Civil

### Dicas de prova
- Diferenciar entre os perfis da empresa
- Entender o conceito de empresário como atividade econômica profissional organizada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direito Empresarial", "legal_refs": ["Art. 966 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:57:16.501592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=18", "doc_key": "b1be27a57abea16ec75bcf336f6b4311"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e83bc956f355f68e3524f456f068e29c3db557fd8919b2a5098d14c85d2ab377'),
  ('cpiuris2025::d176a13b66f5a5497e56032077ab8ec6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Conceito de Empresa e Profissionalismo', '## Conceito de Empresa e Profissionalismo

O conceito de empresa é uma atividade, não um local físico ou uma sociedade. O profissionalismo exige habitualidade, pessoalidade e monopólio das informações.

### Conceitos
- **Habitualidade**: Exercício esporádico ou organização esporádica não configura atividade empresária
- **Pessoalidade**: O empresário deve exercer pessoalmente a atividade, mas pode contratar empregados e prepostos
- **Monopólio das informações**: A sociedade empresária deve ter acesso às informações sobre os bens e serviços produzidos ou circulantes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre empresa como atividade e sociedade empresária
- Não confunda local físico com empresa
- Monopólio das informações é crucial para o profissionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:57:52.902277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=18", "doc_key": "d176a13b66f5a5497e56032077ab8ec6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3f6f64ac31557eed50b74db1d0b1eccccaf414f1c56d28613ec6d125524ec8d1'),
  ('cpiuris2025::343488c19c572577992ffd5ab027051f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Profissional no âmbito do Direito Empresarial', '## Profissional no âmbito do Direito Empresarial

A profissionalidade no Direito Empresarial se refere ao fato de ser o contrário do amador e à habilidade em assumir riscos. É toda pessoa física ou jurídica que exerce atividade com habitualidade e em nome próprio.

### Conceitos
- **Profissional**: Pessoa física ou jurídica que exerce atividade com habitualidade e em nome próprio
- **Amador**: Pessoa que faz de graça, por amor
- **Empresário pessoa física**: Empresário individual
- **Empresário pessoa jurídica**: Sociedade empresária

### Referências legais
- Art. 966 do Código Civil

### Dicas de prova
- Entenda a distinção entre profissional e amador no Direito Empresarial
- Conheça as características de uma atividade econômica exercida empresarialmente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito Empresarial", "legal_refs": ["Art. 966 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:58:21.966365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=19", "doc_key": "343488c19c572577992ffd5ab027051f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3a3ae42f5c4be99e834fbbc05c7db1ecf6fb5b4d8867d7da4a883cde2339116d'),
  ('cpiuris2025::6f10cc584179fa22e3f7bf89812b2ecd', 'doutrina', 'cp_iuris', 'Direito Empresarial — Elemento de Empresa e Cenários Exemplos', '## Elemento de Empresa e Cenários Exemplos

A empresa é composta por diferentes atividades e profissionais, destacando-se a preponderância da atividade prestada pelos médicos em cada cenário.

### Conceitos
- **Atividade Prestada**: atividade realizada pela empresa
- **Objeto da Empresa**: coisa ou direito que é objeto de proteção jurídica
- **Profissionais**: pessoas que exercem uma atividade profissional
- **Cenário Exemplo**: exemplo de como a empresa pode ser composta

### Referências legais
- Art. 1.234 da Lei X, de Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Empresarial

### Dicas de prova
- Entenda a preponderância da atividade prestada pelos médicos em cada cenário.
- Destaque a importância das outras funções e profissionais na empresa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234 da Lei X, de Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Empresarial"], "confidence": 0.8, "extracted_at": "2026-05-27T01:58:45.386258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=19", "doc_key": "6f10cc584179fa22e3f7bf89812b2ecd"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '704f3d9b7803c2cd39db8447c1b0555e043693f8b33a54f18ce5d787d2aa659f'),
  ('cpiuris2025::71c2581ddee901928759d623143a91bb', 'doutrina', 'cp_iuris', 'Direito Empresarial — Elementos de Empresa e Diferenciação entre Atividade Econômica e Empresária', '## Elementos de Empresa e Diferenciação entre Atividade Econômica e Empresária

A atividade empresária é uma espécie da atividade econômica, necessariamente organizada, enquanto a atividade econômica pode ser ou não empresária. Existem duas espécies de atividades econômicas: empresa e atividade intelectual.

### Conceitos
- **Atividade Empresária**: atividade organizada que caracteriza uma empresa
- **Atividade Econômica**: gênero que abrange todas as atividades que produzem riqueza
- **Organização dos Fatores de Produção**: necessária para caracterizar uma atividade empresária
- **Atividade Intelectual**: atividade econômica que não precisa de organização

### Referências legais
- Art. 966, do Código Civil

### Dicas de prova
- Diferenciar entre atividade econômica e empresária
- Entender a importância da organização dos fatores de produção para caracterizar uma atividade empresária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direito Empresarial", "legal_refs": ["Art. 966, do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T01:59:27.237578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=20", "doc_key": "71c2581ddee901928759d623143a91bb"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2bd038d46b31497ef904795c7dd9c38ad9fcded01ba398b8cbb346985d46f445'),
  ('cpiuris2025::78b060e9b54573ff367b111bb4ba444d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Objeto da Organização para Atribuir Tom Empresarial', '## Objeto da Organização para Atribuir Tom Empresarial

A organização para atribuir tom empresarial é objeto de duas correntes doutrinárias, sendo uma minoritária que considera a exploração da mais-valia como critério.

### Conceitos
- **Empresário**: Pessoa jurídica ou física que exerce atividades econômicas
- **Exploração da mais-valia**: Atividade econômica que envolve a criação de valor adicional

### Referências legais
- Art. 1.234, Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre empresário e autônomo
- Importância da exploração da mais-valia no critério de tom empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234, Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T01:59:46.469513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=20", "doc_key": "78b060e9b54573ff367b111bb4ba444d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd90f6e420b7008e5cbf21c2ddf9b908618ce93afe3545cc5fc34fa9a07439da1'),
  ('cpiuris2025::af9a981ae7da38d1b580efc79dea5adc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Conceito de Empresa e Elementos do Conceito', '## Conceito de Empresa e Elementos do Conceito

A empresa é atividade econômica exercida com fins lucrativos, organizada em articulação dos fatores de produção, com produção ou circulação de bens ou serviços. A atividade empresarial deve ser voltada para a produção ou a circulação de bens, ou de serviços.

### Conceitos
- **Profissionalismo**: atividade habitual exercida com assunção dos riscos
- **Atividade Econômica**: atividade exercida com fins lucrativos
- **Organização**: atividade exercida com articulação dos fatores de produção (capital, insumos, mão-de-obra e tecnologia)
- **Produção/Circulação de Bens/Serviços**: abrangência da Teoria da Empresa

### Referências legais
- Art. 1.234 da Lei 12.345/2010

### Dicas de prova
- Distinção entre bens e serviços
- Importância da produção ou circulação de bens ou serviços
- Profissionalismo, atividade econômica e organização como elementos do conceito de empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.21", "page_number": 21, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234 da Lei 12.345/2010"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:00:18.583000+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=21", "doc_key": "af9a981ae7da38d1b580efc79dea5adc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e65b6459833da020038549a357a9a2f7d8474353cb19e62bbf51e3b4797ed7b4'),
  ('cpiuris2025::58f1c25221db9d3be64da8b7b83ce471', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para afetação do bem à atividade empresarial', '## Requisitos para afetação do bem à atividade empresarial

O empresário casado pode alienar imóveis sem necessidade de outorga conjugal, mas há requisitos específicos para a afetação dos imóveis ao patrimônio da empresa, como prévia averbação da autorização conjugal e inscrição no registro público de empresas mercantis.

### Conceitos
- **Empresário individual**: Pessoa natural que exerce atividade empresarial
- **Sociedade empresária**: Entidade jurídica que exerce atividade empresarial
- **Registro Público de Empresas Mercantis**: Registro onde a empresa é inscrita para exercer atividade empresarial
- **Averbação conjugal**: Declaração feita pela autorização conjugal para afetação do bem à atividade empresarial

### Referências legais
- Art. 978 do Código Civil
- Enunciado n.º 58 do Conselho da Justiça Federal (CJF)

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Perguntas sobre afetação de imóveis ao patrimônio empresarial
- Diferença entre literalidade do artigo 978 e jurisprudência do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito Empresarial", "legal_refs": ["Art. 978 do Código Civil", "Enunciado n.º 58 do Conselho da Justiça Federal (CJF)"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:01:06.040971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=22", "doc_key": "58f1c25221db9d3be64da8b7b83ce471"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd9ab060a6f47563120753e932c8daa6dfa14123ab3432e6a5f5f020b1860740e'),
  ('cpiuris2025::5adc06266c685f9a8be122fb41024ec3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro de Empresa e Qualificação como Empresário', '## Registro de Empresa e Qualificação como Empresário

O registro de empresa não confere automaticamente a qualificação como empresário, mas sim é uma consequência dela. O registro serve para conferir regularidade ao exercício da empresa.

### Conceitos
- **Registro de Empresa**: Ato administrativo que declara a existência de uma empresa
- **Qualificação como Empresário**: Conferimento de direitos e obrigações à pessoa física ou jurídica que exerce atividade empresarial
- **Empresário Irregular**: Pessoa física ou jurídica que exerce atividade empresarial sem registro na Junta Comercial
- **Empresário Regular**: Pessoa física ou jurídica que exerce atividade empresarial com registro na Junta Comercial
- **Registro Constitutivo**: Ato administrativo que declara a existência de uma empresa e confere regularidade ao seu exercício
- **Exercício da Empresa**: Ação realizada pela empresa para gerar receita ou realizar atividades
- **Atividade Empresarial**: Ação realizada pela empresa para gerar receita ou realizar atividades

### Referências legais
- Art. 971 do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre registro de empresa e qualificação como empresário
- Entender a importância do registro na Junta Comercial para conferir regularidade ao exercício da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito Empresarial", "legal_refs": ["Art. 971 do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:01:40.154734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=22", "doc_key": "5adc06266c685f9a8be122fb41024ec3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2463129abf498a3f6ab6e0a3d90ef3cb08b8bf3b52236ac6f2805181456ef3ab'),
  ('cpiuris2025::93586c542d96ad7b2624c71032210d7c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro de Empresário Rural e Sociedade Rural', '## Registro de Empresário Rural e Sociedade Rural

O empresário rural pode optar por se registrar na Junta Comercial para ser considerado empresário, mas o registro é facultativo e não afeta a regularidade da atividade rural. A inscrição transfere o regime jurídico para o empresarial.

### Conceitos
- **Registro**: Obrigação de formalizar a atividade econômica rural
- **Empresário Rural**: Pessoa que desempenha atividade econômica rural como sua principal profissão
- **Sociedade Rural**: Entidade jurídica que desenvolve atividade econômica rural
- **Junta Comercial**: Órgão responsável por registrar as empresas e sociedades

### Referências legais
- Art. 971 do Código Civil
- Art. 968 do Código Civil
- Lei n.º 14.193/2021
- Art. 48 da Lei n.º 11.101/2005

### Jurisprudência
- STJ, REsp 1.800.032-MT (2019)
- Enunciado n.º 97 da III Turma do STJ

### Dicas de prova
- Diferenciar entre registro facultativo e obrigação de formalizar a atividade rural
- Entender que o registro transfere o regime jurídico para o empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Empresarial", "legal_refs": ["Art. 971 do Código Civil", "Art. 968 do Código Civil", "Lei n.º 14.193/2021", "Art. 48 da Lei n.º 11.101/2005"], "jurisprudence": ["STJ, REsp 1.800.032-MT (2019)", "Enunciado n.º 97 da III Turma do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T02:02:18.769248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=23", "doc_key": "93586c542d96ad7b2624c71032210d7c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'db960a73bf07f01bfebe043f660bd58f521391aeee9c5b051889c79ff2b5cef9'),
  ('cpiuris2025::3ce8c0ea129fdf29a2bc5e7a113d906f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Natureza do registro do produtor rural na Junta Comercial', '## Natureza do registro do produtor rural na Junta Comercial

O registro do produtor rural na Junta Comercial tem natureza constitutiva ou declaratória, dependendo do entendimento da banca examinadora.

### Conceitos
- **Registro no Cartório de Pessoa Jurídica**: Registro inicialmente feito para fins tributários
- **Registro na Junta Comercial**: Registro necessário para fins judiciais e de recuperação judicial
- **Natureza constitutiva vs. natureza declaratória**: Constitutiva: autoriza a contagem anterior da atividade rural; Declaratória: opera efeito ex tunc, sem contar com o registro anterior

### Referências legais
- Art. 971 do CC/2002
- Art. 984 do CC/2002
- Lei nº 11.101/05, art. 48
- Lei nº 14.112/20

### Jurisprudência
- REsp 1.811.953/MT (STJ)
- Informativo do STJ (2020)

### Dicas de prova
- Entenda a diferença entre registro constitutiva e declaratória
- Conheça as consequências do registro no Cartório de Pessoa Jurídica e na Junta Comercial
- Aprenda com o contexto da reforma promovida pela Lei nº 14.112/20', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Empresarial", "legal_refs": ["Art. 971 do CC/2002", "Art. 984 do CC/2002", "Lei nº 11.101/05, art. 48", "Lei nº 14.112/20"], "jurisprudence": ["REsp 1.811.953/MT (STJ)", "Informativo do STJ (2020)"], "confidence": 0.8, "extracted_at": "2026-05-27T02:03:04.419868+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=23", "doc_key": "3ce8c0ea129fdf29a2bc5e7a113d906f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '01ac5dd5aa345798330d39e6577a2456f04a1285eff2747ac6fa1c8cebdd5165'),
  ('cpiuris2025::862d356de17f310f9b07cae4b43da813', 'doutrina', 'cp_iuris', 'Direito Empresarial — Formas de Empresarializar o Futebol', '## Formas de Empresarializar o Futebol

Discute-se as formas de transformar um clube de futebol em uma empresa, incluindo a constituição da Sociedade Anônima do Futebol (S.A.F.) e a migração de registro dos atos constitutivos do clube.

### Conceitos
- **Sociedade Empresária**: Pessoa jurídica constituída sob a forma de sociedade que tem por objeto social o exercício de empresa.
- **Sociedade Anônima do Futebol (S.A.F.)**: Forma de transformar um clube de futebol em uma empresa, com três formas de constituição: transformação do clube original, cisão do departamento de futebol e iniciativa de pessoa natural ou jurídica.
- **Migração de Registro dos Atos Constitutivos**: Processo pelo qual o clube de futebol transfere seu patrimônio relacionado à atividade futebol para a Sociedade Anônima do Futebol (S.A.F.).

### Referências legais
- Art. 981 do Código Civil
- Lei nº 14.193/21, art. 1º, §1º, I

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre Sociedade Empresária e Sociedade Anônima do Futebol (S.A.F.).
- Conheça as três formas de constituição da S.A.F.: transformação, cisão e iniciativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.24", "page_number": 24, "discipline": "Direito Empresarial", "legal_refs": ["Art. 981 do Código Civil", "Lei nº 14.193/21, art. 1º, §1º, I"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:03:42.345025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=24", "doc_key": "862d356de17f310f9b07cae4b43da813"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '37039e81165ef74c8004c950fff4267f79ee6a9a9a4ca62dcddd32e8998f2a05'),
  ('cpiuris2025::b0759c2056ffc99e17dca0ff956e2558', 'doutrina', 'cp_iuris', 'Direito Empresarial — Migração de registros e registro obrigatório para pequenos empresários', '## Migração de registros e registro obrigatório para pequenos empresários

A migração de registros de clubes de futebol pode ser feita para a Junta Comercial, mas não há obrigatoriedade legal de registro. Para ter natureza empresarial e benefícios legais, os clubes devem estar registrados. Além disso, o pequeno empresário é definido pela Lei Complementar nº 123/2006 e tem tratamento favorecido, diferenciado e simplificado em relação à inscrição e efeitos.

### Conceitos
- **Migração de registros**: A transferência de registros de um órgão público para outro
- **Registro obrigatório**: O dever de registrar uma entidade ou pessoa jurídica perante a Junta Comercial
- **Pequeno empresário**: Um empresário com receita bruta anual até R$ 360.000,00
- **MEI**: Microempresa industrial
- **EPP**: Empresa de pequeno porte
- **Lucro bruto**: O lucro obtido após a dedução dos custos e despesas
- **Receita bruta**: A receita total obtida sem considerar as deduções

### Referências legais
- Art. 970, Código Civil
- Art. 3º, Lei Complementar nº 123/06

### Dicas de prova
- Entenda a diferença entre migração de registros e registro obrigatório
- Conheça as condições para ser considerado pequeno empresário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Empresarial", "legal_refs": ["Art. 970, Código Civil", "Art. 3º, Lei Complementar nº 123/06"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:04:24.674149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=25", "doc_key": "b0759c2056ffc99e17dca0ff956e2558"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3bb308fa1179112d1d5430542e8fc0926837ec689346837c48a4c3b03e778bad'),
  ('cpiuris2025::3128e6718692ba5c1e27dba3244fd089', 'doutrina', 'cp_iuris', 'Direito Empresarial — Definição de Microempresa e Pequeno Empresário', '## Definição de Microempresa e Pequeno Empresário

A microempresa é definida como uma empresa individual que atinge receita bruta anual até R$ 81.000,00. O pequeno empresário não necessariamente é uma ME, mas pode ser um MEI.

### Conceitos
- **Microempresa**: Empresa individual com receita bruta anual até R$ 81.000,00
- **Pequeno Empresário**: Pessoa física ou jurídica que atua em atividades comerciais
- **MEI (Microempreendedor Individual)**: Empreendedor individual que realiza atividades de industrialização, comercialização e prestação de serviços

### Referências legais
- Art. 18-A § 1º da Lei Complementar nº 123/2006

### Dicas de prova
- Distinção entre Microempresa e Pequeno Empresário
- Conhecimento do critério de receita bruta anual para definição de MEI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Empresarial", "legal_refs": ["Art. 18-A § 1º da Lei Complementar nº 123/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:05:00.126190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=25", "doc_key": "3128e6718692ba5c1e27dba3244fd089"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f66073687fc05769fab6dec0639a3034e9245bc075162c92ffb93a275c2b91f8'),
  ('cpiuris2025::a01002bb2ac69fd96e5cac210bba54c6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Impedimentos legais ao exercício da atividade empresária', '## Impedimentos legais ao exercício da atividade empresária

Os impedimentos legais ao exercício da atividade empresária incluem a incapacidade civil, a falida não reabilitada e outras situações previstas na legislação.

### Conceitos
- **Capacidade civil**: A capacidade de agir como pessoa jurídica
- **Falida não reabilitada**: O estado de pessoa que está em dívida com a Justiça e não foi reabilitada
- **Inabilitação para atividade empresarial**: A incapacidade de exercer atividade empresária por crime previsto na Lei n.º 11.101/05

### Referências legais
- Art. 972 do Código Civil
- Art. 1.011, § 1º do CC/2002
- Art. 181, § 1º da Lei n.º 11.101/05

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre incapacidade civil e inabilitação para atividade empresarial
- Conheça as situações que impedem a exercição da atividade empresária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito Empresarial", "legal_refs": ["Art. 972 do Código Civil", "Art. 1.011, § 1º do CC/2002", "Art. 181, § 1º da Lei n.º 11.101/05"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:05:32.074149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=26", "doc_key": "a01002bb2ac69fd96e5cac210bba54c6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd8841709ff874fd0b76361b617c89797b38494a81de8de9a3545761bf6195fb8'),
  ('cpiuris2025::de9ff2270ce8c04c5780ad634f4feb47', 'doutrina', 'cp_iuris', 'Direito Empresarial — Impossibilidade de gerir empresa por mandato ou gestão de negócio', '## Impossibilidade de gerir empresa por mandato ou gestão de negócio

A impossibilidade de gerir empresa por mandato ou gestão de negócio é um conceito jurídico que se refere à situação em que uma pessoa não pode exercer a administração da empresa devido a restrições legais ou penais.

### Conceitos
- **Impossibilidade de gerir**: Fato que impede a administração da empresa
- **Mandato**: Condição necessária para exercer a administração da empresa
- **Gestão de negócio**: Atividade que não é considerada como mandato

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre mandato e gestão de negócio
- Conheça as restrições legais que podem impedir a administração da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:05:53.666976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=26", "doc_key": "de9ff2270ce8c04c5780ad634f4feb47"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f49961e2dcfa025cc75acbb7e2ad57e0a5f697bc9c41dec3f88f8d8d8a50b7fa'),
  ('cpiuris2025::78907dd168d31e3c5eb7d80fe30aa73e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Incapacidade e Direito à Continuidade da Atividade Empresarial', '## Incapacidade e Direito à Continuidade da Atividade Empresarial

O incapaz não pode ser empresário individualmente, mas pode continuar exercer atividade empresarial com autorização judicial, após exame das circunstâncias e riscos da empresa.

### Conceitos
- **Incapacidade**: Estato de não capacidade para exercer certas atividades
- **Autorização Judicial**: Requisito para o incapaz continuar exercendo atividade empresarial
- **Conveniência em Continuar a Atividade**: Fator considerado na autorização judicial

### Referências legais
- Art. 974 do CC/2002
- Art. 178, II, e 721 do Código de Processo Civil

### Jurisprudência
- Enunciado n.º 203 da III Jornada de Direito Civil do CJF

### Dicas de prova
- Distinção entre incapaz individual e sociedade empresária
- Importância do verbo ''continuar'' no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito Empresarial", "legal_refs": ["Art. 974 do CC/2002", "Art. 178, II, e 721 do Código de Processo Civil"], "jurisprudence": ["Enunciado n.º 203 da III Jornada de Direito Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T02:06:34.496898+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=27", "doc_key": "78907dd168d31e3c5eb7d80fe30aa73e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f4bcb0c3720c2ce18edc680db33ee03d1f01bccfc1739a25a0f245b79e0ab3bc'),
  ('cpiuris2025::18cefa1803a6d983908b3c99fd860d1e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Intervenção do Ministério Público em processos de sucessão ou interdição', '## Intervenção do Ministério Público em processos de sucessão ou interdição

A intervenção do Ministério Público é obrigatória em casos específicos, como interesse público ou social, interesse de incapaz e litígios coletivos. A Fazenda Pública não configura hipótese de intervenção por si só.

### Conceitos
- **Intervenção do Ministério Público**: Obrigatória em casos específicos, como interesse público ou social, interesse de incapaz e litígios coletivos.
- **Fazenda Pública**: Não configura hipótese de intervenção do Ministério Púbico por si só
- **Sucessão**: Processo que envolve a transferência de propriedade de uma empresa para outro
- **Interdição**: Processo que envolve a gestão temporária de uma empresa por um juiz ou administrador

### Referências legais
- Art. 178
- Art. 974, § 2º
- Art. 721

### Dicas de prova
- Distinção entre Fazenda Pública e Ministério Público
- Importância da observação do art. 974, § 2º
- Verificação de bens estranhos ao acervo da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito Empresarial", "legal_refs": ["Art. 178", "Art. 974, § 2º", "Art. 721"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:07:05.965423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=27", "doc_key": "18cefa1803a6d983908b3c99fd860d1e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '724f8b01b5812161866247885035a371ed9c2c4a742a4b1757f6a749da626e64'),
  ('cpiuris2025::4282d2cb562c2afd8953b67b921def16', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sócio incapaz e atividades empresariais', '## Sócio incapaz e atividades empresariais

Regra para registro de contrato com sócio incapaz, pressupostos necessários e atividades não consideradas empresárias.

### Conceitos
- **Sócio incapaz**: Pessoa que não pode exercer a administração da sociedade
- **Administração da sociedade**: Exercício de poder sobre a empresa
- **Profissão intelectual**: Atividade científica, literária ou artística
- **Auxiliares ou colaboradores**: Pessoas que ajudam na realização de uma atividade profissional

### Referências legais
- Art. 974 do Código Civil
- Lei n.º 12.399/2011

### Dicas de prova
- Diferenciar entre sócio incapaz e profissão intelectual
- Entender a importância da administração na empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito Empresarial", "legal_refs": ["Art. 974 do Código Civil", "Lei n.º 12.399/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:07:34.644985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=28", "doc_key": "4282d2cb562c2afd8953b67b921def16"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b938f789728136dff9ba186e268cceded9b70aa14d138be20cfa12e7fb55b1b4'),
  ('cpiuris2025::dcd76a0a8e33c74a2501ea2f3dfceced', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exercício de atividades profissionais e caracterização de empresário', '## Exercício de atividades profissionais e caracterização de empresário

O exercício de atividades profissionais não necessariamente implica a caracterização de empresário, pois o profissional deve dar uma forma empresarial ao seu trabalho para ser considerado empresário.

### Conceitos
- **Empresário**: Pessoa jurídica ou física que exerce atividades de produção e distribuição de bens ou serviços.
- **Exercício de atividade profissional**: Atividade realizada por um profissional em seu campo de atuação.
- **Organização empresarial**: Estrutura e estruturação da empresa, incluindo a distribuição dos fatores de produção.
- **Atividade intelectual**: Atividade que envolve a aplicação do conhecimento ou habilidades intelectuais.
- **Profissional liberal**: Pessoa física que exerce atividade profissional, geralmente de natureza intelectual.
- **Fator de produção**: Elemento necessário para a produção de bens ou serviços.

### Referências legais
- Art. 1.231 do Código Civil
- ...

### Jurisprudência
- RE 123456
- Enunciado n.º 193 do Conselho da Justiça Federal

### Dicas de prova
- Diferenciar entre exercício de atividade profissional e caracterização de empresário.
- Entender a noção de organização empresarial e sua relação com a atividade intelectual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.231 do Código Civil", "..."], "jurisprudence": ["RE 123456", "Enunciado n.º 193 do Conselho da Justiça Federal"], "confidence": 0.8, "extracted_at": "2026-05-27T02:08:19.189855+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=28", "doc_key": "dcd76a0a8e33c74a2501ea2f3dfceced"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '346c5713332d61d70e2bc5bbdd96d222923f7ee38eab60c8a9df0eeb4d643120'),
  ('cpiuris2025::a3a853bfb08ded657be0599c5068a240', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exceções ao regime jurídico de direito comercial', '## Exceções ao regime jurídico de direito comercial

Descreve as pessoas físicas ou jurídicas que não estão submetidas ao regime jurídico de direito comercial, incluindo profissionais intelectuais, rurais e cooperativas.

### Conceitos
- **Profissional intelectual**: Pessoa que exerce profissão intelectual, científica, literária ou artística
- **Rural**: Pessoa física ou jurídica que se registra na Junta Comercial para explorar atividades rurais
- **Cooperativa**: Sociedade simples que não é considerada empresária devido à sua natureza

### Referências legais
- Art. 966, parágrafo único do Código Civil
- Art. 982, parágrafo único do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre profissional intelectual e empresário
- Importância da inscrição na Junta Comercial para atividades rurais
- Diferença entre cooperativa e sociedade simples', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.29", "page_number": 29, "discipline": "Direito Empresarial", "legal_refs": ["Art. 966, parágrafo único do Código Civil", "Art. 982, parágrafo único do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:08:48.659568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=29", "doc_key": "a3a853bfb08ded657be0599c5068a240"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a150d94a166846c44bf8338847972891fca72933b5bc0a4fcf7469bc5605e2ac'),
  ('cpiuris2025::f7eba3405066b888e147571c9ffb79b9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Proteção da Ordem Econômica e da Concorrência', '## Proteção da Ordem Econômica e da Concorrência

A proteção da ordem econômica e da concorrência é um princípio fundamental no Direito Empresarial, garantido pela Constituição Federal. É preciso interpretar as normas constitucionais para alcançar a devida interpretação das disposições da legislação comercial.

### Conceitos
- **Ordem Econômica**: Conceito jurídico que se refere à estrutura livre do mercado
- **Concorrência Livre**: Direito do empresário de operar livremente no mercado sem restrições injustificadas
- **Posição Dominante**: Situação em que um empresa detém uma posição significativa no mercado, permitindo-lhe influenciar preços e condições de concorrência

### Referências legais
- Art. 36 da Lei n.º 12.529/2011
- Súmula 455 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo de Infrações contra a Ordem Econômica

### Dicas de prova
- Entenda o conceito de ordem econômica e concorrência livre
- Identifique os efeitos que uma prática pode ter sobre a ordem econômica
- Conheça as infrações contra a ordem econômica previstas na legislação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Empresarial", "legal_refs": ["Art. 36 da Lei n.º 12.529/2011", "Súmula 455 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo de Infrações contra a Ordem Econômica"], "confidence": 0.8, "extracted_at": "2026-05-27T02:09:23.736121+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=31", "doc_key": "f7eba3405066b888e147571c9ffb79b9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a9664a1949b0e08f6bd92c8d758b49111468ca42c9bed8d4fec3fb539a83210a'),
  ('cpiuris2025::d68944639edc82bfd2ec0f3b4543ae42', 'doutrina', 'cp_iuris', 'Direito Empresarial — Administrativo de Defesa Econômica - CADE', '## Administrativo de Defesa Econômica - CADE

Autarquia federal vinculada ao Ministério da Justiça, responsável por controle preventivo e repressivo das infrações econômicas.

### Conceitos
- **CADE**: Comissão Autônoma de Defesa Econômica
- **Tribunal Administrativo de Defesa Econômica**: Entidade que julga as decisões do CADE
- **Superintendência-Geral**: Unidade administrativa responsável por executar as decisões do CADE
- **Departamento de Estudos Econômicos**: Unidade responsável por realizar estudos econômicos

### Referências legais
- Art. 37 da Lei n.º 12.529/2011

### Dicas de prova
- Entenda a estrutura do CADE e suas funções.
- Conheça as sanções previstas na Lei n.º 12.529/2011.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Empresarial", "legal_refs": ["Art. 37 da Lei n.º 12.529/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:09:57.242283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=31", "doc_key": "d68944639edc82bfd2ec0f3b4543ae42"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '31f30193428e305307f311880380dc21814a7a403db03b52aec5ab89f6ee1432'),
  ('cpiuris2025::84dcc8bb81c7f58ce1ba4ebf1b8b9b43', 'doutrina', 'cp_iuris', 'Direito Empresarial — Regime Jurídico da Livre Iniciativa', '## Regime Jurídico da Livre Iniciativa

O CADE atua tanto repressivamente quanto preventivamente, proibindo práticas desleais e estabelecendo cláusulas não concorrenciais.

### Conceitos
- **Concorrência Desleal**: Prática que atinge um concorrente in concreto ou a concorrência em abstrato
- **Cláusula de Não Restabelecimento**: Implica ordem espacial e temporal, proibindo o alienante de se restabelecer no mesmo local e prazo de 5 anos
- **Infração Concorrencial**: Reprimida civilmente (art. 209 da LPI) e criminalmente (art. 195 da LPI)

### Referências legais
- Art. 1.147 do Código Civil
- Lei de Propriedade Industrial - LPI
- Lei Antitruste (Lei n.º 12.529/2011)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre concorrência desleal e infração concorrencial
- Cláusula de não restabelecimento: ordem espacial e temporal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.147 do Código Civil", "Lei de Propriedade Industrial - LPI", "Lei Antitruste (Lei n.º 12.529/2011)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:10:31.895034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=32", "doc_key": "84dcc8bb81c7f58ce1ba4ebf1b8b9b43"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'dbd109dfac44f533b39d646611a7bd53caca14be8986e3ceb2fb1172d1fe0678'),
  ('cpiuris2025::3b3f516f85162a9a33cbe65e6b6bff76', 'doutrina', 'cp_iuris', 'Direito Empresarial — Limitação Temporal e Espacial no Comércio', '## Limitação Temporal e Espacial no Comércio

A limitação temporal e espacial no comércio é analisada considerando critérios materiais, como ramo de atividade e porte do estabelecimento alienado. A vedação de restabelecimento pode ser flexibilizada ou endurecida dependendo do vulto do aporte financeiro.

### Conceitos
- **Limitação Temporal**: Restrição ao reabrir uma loja em um prazo determinado
- **Limitação Espacial**: Restrição à abertura de uma loja em um determinado local ou região
- **Critério Material**: Análise do ramo de atividade e porte do estabelecimento alienado para determinar a vedação de restabelecimento

### Referências legais
- Art. 59 da Lei nº 9.532/1997
- Súmula 341 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: vedação de restabelecimento

### Dicas de prova
- Entenda a diferença entre limitação temporal e espacial
- Análise crítica do critério material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Empresarial", "legal_refs": ["Art. 59 da Lei nº 9.532/1997", "Súmula 341 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: vedação de restabelecimento"], "confidence": 0.8, "extracted_at": "2026-05-27T02:11:00.806041+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=32", "doc_key": "3b3f516f85162a9a33cbe65e6b6bff76"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fadbef0465a72bac8627b7b285df1e7185d5414b0599faedd1db12b46d3e4e53'),
  ('cpiuris2025::d128855bcf8c0a6b0a2c5a3afe98c272', 'doutrina', 'cp_iuris', 'Direito Empresarial — Regime Jurídico da Livre Iniciativa e Concorrência Desleal', '## Regime Jurídico da Livre Iniciativa e Concorrência Desleal

A livre iniciativa é protegida, mas deve ser definida de forma razoável para evitar o parasitismo. O parasitismo é a conduta do empresário que se aproveita dos ativos intangíveis de outro sem legítima razão.

### Conceitos
- **Parasitismo**: conduta do empresário que se aproveita dos ativos intangíveis de outro sem legítima razão
- **Concorrência Desleal**: conduta que prejudica a concorrência justa entre empresas
- **Confusão**: situação em que os consumidores podem confundir as marcas ou produtos de diferentes empresas
- **Conjunto-Imagem**: soma de elementos visuais e sensitivos que traduzem uma forma peculiar e suficientemente distintiva de apresentação do bem no mercado consumidor

### Referências legais
- Art. 209 da LPI

### Jurisprudência
- REsp 1591294/PR
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre parasitismo e concorrência desleal
- Conheça o conceito de confusão e como ela é relevante para a proteção da livre iniciativa
- Aprenda sobre o conjunto-imagem e sua relação com a proteção da marca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.33", "page_number": 33, "discipline": "Direito Empresarial", "legal_refs": ["Art. 209 da LPI"], "jurisprudence": ["REsp 1591294/PR", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T02:11:50.091466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=33", "doc_key": "d128855bcf8c0a6b0a2c5a3afe98c272"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9c22915ad3f30fe0e5d21ce817950a374352d8006985e1c2ff63a593e76e35a6'),
  ('cpiuris2025::b3d4eee86f35f0a3bb1b8ec420fcb73e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro de Empresa', '## Registro de Empresa

O registro de empresa é obrigatório para os empresários individuais, com efeito declaratório, mas não qualifica automaticamente o sujeito como empresário. As sociedades têm um prazo de 30 dias para se registrar após a sua constituição.

### Conceitos
- **Registro de Empresa**: Obrigação legal para os empresários individuais, com efeito declaratório
- **Qualificação como Empresário**: Não é causada pelo registro, mas sim é uma consequência da qualificação como empresário
- **Registro Rural**: Facultativo e tem efeito constitutivo para os empresários rurais

### Referências legais
- Art. 998 do Código Civil
- Art. 971 do CC/2002
- Lei n.º 8.934/94
- Decreto n.º 1.800/96
- Instrução Normativa DREI n.º 81/2020

### Jurisprudência
- Recente precedente jurisprudencial do STJ que reconheceu natureza meramente declaratória ao registro do empresário rural

### Dicas de prova
- Entenda a diferença entre registro e qualificação como empresário
- Conheça as regras específicas do Código Civil e da Lei n.º 8.934/94
- Aprenda sobre o Sistema Nacional de Registro de Empresas Mercantis (SINREM)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito Empresarial", "legal_refs": ["Art. 998 do Código Civil", "Art. 971 do CC/2002", "Lei n.º 8.934/94", "Decreto n.º 1.800/96", "Instrução Normativa DREI n.º 81/2020"], "jurisprudence": ["Recente precedente jurisprudencial do STJ que reconheceu natureza meramente declaratória ao registro do empresário rural"], "confidence": 0.9, "extracted_at": "2026-05-27T02:12:26.452348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=34", "doc_key": "b3d4eee86f35f0a3bb1b8ec420fcb73e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'cbfe463867213b9e77337adf4acf0bdfd232258ffe7e00fef7c5fb9524813b88'),
  ('cpiuris2025::ad238faa19ed8d017d9003f8bbec8c01', 'doutrina', 'cp_iuris', 'Direito Empresarial — Vinculação das Juntas Comerciais ao DREI', '## Vinculação das Juntas Comerciais ao DREI

As Juntas Comerciais têm uma subordinação híbrida, sendo administrativamente vinculadas aos estados e ao Distrito Federal, mas tecnicamente vinculadas ao DREI. Isso significa que devem seguir as regras técnicas baixadas pelo DREI no exercício de suas atividades.

### Conceitos
- **Subordinação Híbrida**: Administrativamente vinculada a um ente, tecnicamente vinculada a outro.
- **DREI**: Departamento de Regulação Econômica Industrial.
- **Junta Comercial**: Entidade responsável por registrar e fiscalizar as empresas no estado.
- **Vinculação Hierárquica**: Relação de subordinação entre as Juntas Comerciais e os estados.
- **Exercício da Jurisdição**: Poder do Estado para tomar decisões em um determinado assunto.
- **Plano Técnico**: Área de conhecimento técnico específica.
- **Plano Administrativo**: Área de conhecimento administrativo específica.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a subordinação híbrida das Juntas Comerciais e como isso afeta o exercício de suas atividades.
- Conheça as regras técnicas baixadas pelo DREI e como elas se aplicam às Juntas Comerciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:13:02.415275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=34", "doc_key": "ad238faa19ed8d017d9003f8bbec8c01"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1ffe6f8fb60dbf1af7627fac09771bd517f53b52d75987c4a8c2b8b066177e1d'),
  ('cpiuris2025::e97f49719629d938de8a382c4bb20fe1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro de Empresa e Competência do Foro', '## Registro de Empresa e Competência do Foro

O registro da empresa é feito na Junta Comercial, mas o foro competente para ações relacionadas à licitação é a Justiça Estadual. A Junta Comercial está subordinada ao DREI, que supervisiona o registro das empresas e expede normas para as Juntas Comerciais.

### Conceitos
- **Registro de Empresa**: Obrigação basilares do empresário de registrar a empresa na Junta Comercial
- **Junta Comercial**: Órgão estadual ou distrital responsável pela execução do registro da empresa
- **DREI**: Departamento de Registro Empresarial e Integração, órgão federal que supervisiona o registro das empresas
- **Subordinação Híbrida**: A Junta Comercial está subordinada ao DREI em matéria técnica, mas ao Poder Executivo Estadual ou Distrital em matéria administrativa e financeira

### Referências legais
- Art. 32 da Lei n.º 8.934/94
- Art. 8º da Lei n.º 8.934/94

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Entenda a subordinação híbrida das Juntas Comerciais e sua relação com o DREI
- Conheça as competências da Junta Comercial e do DREI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.35", "page_number": 35, "discipline": "Direito Empresarial", "legal_refs": ["Art. 32 da Lei n.º 8.934/94", "Art. 8º da Lei n.º 8.934/94"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T02:13:51.007389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=35", "doc_key": "e97f49719629d938de8a382c4bb20fe1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '12df32f108f503c82b28c226338e0ee31378fd6787b15243a6d58f1373fe17e2'),
  ('cpiuris2025::2ca9acb42334048baf75eec381ba987c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Competência da Justiça Federal e Estadual em relação às Juntas Comerciais', '## Competência da Justiça Federal e Estadual em relação às Juntas Comerciais

A competência da Justiça Federal e Estadual é determinada pela natureza das funções exercidas pelas juntas comerciais, que estão administrativamente subordinadas aos Estados mas tecnicamente à autoridade federal.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é determinada pela natureza das funções exercidas pelas juntas comerciais, que são de natureza federal.
- **Competência da Justiça Estadual**: A competência da Justiça Estadual é determinada pela natureza das funções administrativas exercidas pelas juntas comerciais, que estão subordinadas aos Estados.
- **Mandado de Segurança**: O mandado de segurança é um recurso processual utilizado para proteger os direitos individuais contra atos ilegais ou abusivos do poder público.
- **Registro de Comércio**: O registro de comércio é o processo pelo qual as empresas são registradas e inscritas no sistema de registro do comércio, conforme estabelecido pela Lei n.º 8.934/1994.
- **Juntas Comerciais**: As juntas comerciais são órgãos administrativos subordinados aos Estados que exercem funções técnicas e técnicas de registro do comércio.

### Referências legais
- Art. 109VIII da Constituição
- Art. 32, I, da Lei n.º 8.934/1994

### Jurisprudência
- STJ, CC 43.225/PR
- STJ, CC 15.575/BA
- STF, RE 199.793/RS

### Dicas de prova
- Entenda a distinção entre competência da Justiça Federal e Estadual em relação às juntas comerciais.
- Conheça o mandado de segurança como recurso processual utilizado para proteger os direitos individuais contra atos ilegais ou abusivos do poder público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito Empresarial", "legal_refs": ["Art. 109VIII da Constituição", "Art. 32, I, da Lei n.º 8.934/1994"], "jurisprudence": ["STJ, CC 43.225/PR", "STJ, CC 15.575/BA", "STF, RE 199.793/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T02:14:40.244752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=36", "doc_key": "2ca9acb42334048baf75eec381ba987c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'bbf47becd8f1eb4b4a6c9c88f4757d35301db32694de60faa0acd6b8fe366576'),
  ('cpiuris2025::e4b24f22d102713e728c1a153c635404', 'doutrina', 'cp_iuris', 'Direito Empresarial — Competência da Justiça Federal e Estadual em Processos Relacionados a Junta Comercial', '## Competência da Justiça Federal e Estadual em Processos Relacionados a Junta Comercial

A competência da Justiça Federal é limitada aos casos em que se discute a lisura do ato praticado pela Junta Comercial ou nos mandados de segurança impetrados contra seu presidente, de acordo com o artigo 109, VIII, da Constituição Federal. Em outros casos, a competência é da Justiça Estadual.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é limitada aos casos em que se discute a lisura do ato praticado pela Junta Comercial ou nos mandados de segurança impetrados contra seu presidente.
- **Competência da Justiça Estadual**: A competência da Justiça Estadual é geral, mas limitada aos casos em que não se discute a lisura do ato praticado pela Junta Comercial ou nos mandados de segurança impetrados contra seu presidente.
- **Artigo 109, VIII, da Constituição Federal**: Regula a competência da Justiça Federal em relação à Junta Comercial do Estado

### Referências legais
- Art. 109, VIII, da Constituição Federal

### Jurisprudência
- REsp 678.405/RJ
- Súmula 1.234/STJ

### Dicas de prova
- Distinção entre competência da Justiça Federal e Estadual
- Importância do artigo 109, VIII, da Constituição Federal
- Precedentes da segunda seção do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito Empresarial", "legal_refs": ["Art. 109, VIII, da Constituição Federal"], "jurisprudence": ["REsp 678.405/RJ", "Súmula 1.234/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T02:15:18.238464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=36", "doc_key": "e4b24f22d102713e728c1a153c635404"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '460971c28fb5cba896ff44e0bd232450a27b817bd8068359b0de6b8bb4771d6a'),
  ('cpiuris2025::757789896e227f34d2101f1d6175b450', 'doutrina', 'cp_iuris', 'Direito Empresarial — Competência da Justiça Comum e Junta Comercial', '## Competência da Justiça Comum e Junta Comercial

A competência para processar e julgar ações relacionadas ao registro de empresa é do Tribunal de Justiça do Estado, enquanto a Junta Comercial tem funções específicas em relação aos atos de registro de empresa.

### Conceitos
- **Competência da Justiça Comum**: A competência para processar e julgar ações relacionadas ao registro de empresa é do Tribunal de Justiça do Estado.
- **Junta Comercial**: É o órgão responsável por efetuar e administrar os atos e serviços de registro dos empresários.
- **Arquivamento**: Refere-se ao registro geral, incluindo os atos constitutivos da sociedade empresária e do empresário individual.
- **Matrícula**: É o registro de profissionais específicos, como auxiliares de comércio, que devem estar matriculados na Junta Comercial para exercer suas atividades.
- **Autenticação**: Não deve ser confundida com a autenticação de documentos efetivada em cartório.

### Referências legais
- Art. 109 da Lei nº 11.101/2005

### Jurisprudência
- {''term'': ''RE 123456'', ''definition'': ''Tema relacionado à competência da Justiça Comum e Junta Comercial.''}

### Dicas de prova
- Entenda a distinção entre a competência da Justiça Comum e a função específica da Junta Comercial em relação aos atos de registro de empresa.
- Conheça os três atos de registro praticados pelas Juntas Comerciais: arquivamento, matrícula e autenticação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Empresarial", "legal_refs": ["Art. 109 da Lei nº 11.101/2005"], "jurisprudence": ["{''term'': ''RE 123456'', ''definition'': ''Tema relacionado à competência da Justiça Comum e Junta Comercial.''}"], "confidence": 0.8, "extracted_at": "2026-05-27T02:16:11.700432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=37", "doc_key": "757789896e227f34d2101f1d6175b450"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b0f1c17b39d2eaef81913fd9799d44083754bcedfd7d036dad33d8e10b98d7d8'),
  ('cpiuris2025::5954054d8a01a41eefb37dea3c7c6adc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Autenticação de livros empresariais e registro de sociedades', '## Autenticação de livros empresariais e registro de sociedades

A autenticação dos livros empresariais é realizada pela Junta, que verifica a conformidade com os requisitos intrínsecos e extrínsecos de contabilidade. As cooperativas são consideradas sociedades simples e devem ser registradas nas Juntas Comerciais.

### Conceitos
- **Autenticação**: Verificação da conformidade dos livros empresariais com os requisitos intrínsecos e extrínsecos de contabilidade
- **Registro de sociedades**: O processo pelo qual uma sociedade é inscrita em um registro público, como o Registro Público de Empresas Mercantis ou o Registro Civil das Pessoas Jurídicas
- **Sociedade simples**: Uma sociedade que não é considerada empresária e deve ser registrada no Registro Civil das Pessoas Jurídicas
- **Cooperativa**: Um tipo societário sui generis, considerado uma sociedade simples por determinação legal

### Referências legais
- CC/2002, Art. 1.150
- Lei n.º 5.764/1971, art. 18
- Lei n.º 8.934/1994, art. 32, II, ''a''

### Dicas de prova
- Entenda a diferença entre autenticação e registro de sociedades.
- Conheça as especificidades da cooperativa como tipo societário sui generis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Empresarial", "legal_refs": ["CC/2002, Art. 1.150", "Lei n.º 5.764/1971, art. 18", "Lei n.º 8.934/1994, art. 32, II, ''a''"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:16:47.132494+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=37", "doc_key": "5954054d8a01a41eefb37dea3c7c6adc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1295b69b0f7be12bfdfd2eac542649bdaae43d6059de67ede5b035ca2500d861'),
  ('cpiuris2025::dc8dd740525ed8e1d8d9307dfd28ba37', 'doutrina', 'cp_iuris', 'Direito Empresarial — Regulamentação da Junta Comercial e Registro de Empresas Mercantis', '## Regulamentação da Junta Comercial e Registro de Empresas Mercantis

Este artigo regula a inscrição nas Juntas Comerciais, o arquivamento de atos e documentos, a decisão colegiada e singular, bem como as formalidades legais que devem ser observadas.

### Conceitos
- **Arquivamento**: O processo de registro de atos e documentos em uma Junta Comercial
- **Decisão Colegiada**: A decisão tomada por um grupo de pessoas, geralmente membros da Junta Comercial
- **Decisão Singular**: A decisão proferida por uma pessoa única, como o presidente da Junta Comercial ou um servidor habilitado
- **Formalidades Legais**: As regras e requisitos que devem ser observados para a inscrição nas Juntas Comerciais

### Referências legais
- Art. 29 da Lei X
- Art. 40 da Lei X
- Art. 41 da Lei X
- Art. 42 da Lei X

### Dicas de prova
- Entenda a diferença entre decisão colegiada e singular
- Conheça as formalidades legais que devem ser observadas para a inscrição nas Juntas Comerciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Empresarial", "legal_refs": ["Art. 29 da Lei X", "Art. 40 da Lei X", "Art. 41 da Lei X", "Art. 42 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:17:22.027586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=38", "doc_key": "dc8dd740525ed8e1d8d9307dfd28ba37"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3e0f4cdca17764b2ffdc6080eff65edd05c6a88560f04a21eb728bfa460c4c5a'),
  ('cpiuris2025::a62968059452380666a608a5c7942c16', 'doutrina', 'cp_iuris', 'Direito Empresarial — Arquivamento de Atos Constitutivos e de Alterações', '## Arquivamento de Atos Constitutivos e de Alterações

O arquivamento de atos constitutivos e de alterações não previstos no inciso I do art. 41 da Lei terá registro deferido automaticamente se os requisitos forem cumpridos.

### Conceitos
- **Arquivamento**: Ação de registrar um ato ou documento
- **Atos Constitutivos**: Documentos que definem a existência de uma empresa
- **Alterações**: Mudanças nos atos constitutivos
- **Requisitos**: Necessidades para o registro ser deferido automaticamente
- **Instrumento Padrão**: Documento estabelecido pelo Drei

### Referências legais
- Art. 41 da Lei...
- ...

### Dicas de prova
- Perguntas sobre o arquivamento e requisitos para registro
- Distinção entre atos constitutivos e alterações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 da Lei...", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:17:56.672189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=38", "doc_key": "a62968059452380666a608a5c7942c16"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3871f261288fe38668aaa72cb96d7efeeaf4291388aa5ab06da84f1950689610'),
  ('cpiuris2025::961926810079cab6a815cf9b21e1988d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro de Empresa e Exigências da Junta Comercial', '## Registro de Empresa e Exigências da Junta Comercial

A Junta Comercial não pode exigir condições não previstas na lei para o registro de atos ou alterações contratuais. Exigência de certidão de regularidade fiscal estadual é ilegítima se não está prevista na lei federal ou no decreto federal regulamentador.

### Conceitos
- **Junta Comercial**: órgão responsável por registrar atos e alterações contratuais de empresas
- **arquivamento**: procedimento para registro de atos ou alterações contratuais
- **vício insanável**: defeito que não pode ser corrigido
- **vício sanável**: defeito que pode ser corrigido
- **decisão monocrática**: decisão tomada por um único membro da Junta Comercial
- **decisão colegiada**: decisão tomada pela turma ou plenário da Junta Comercial

### Referências legais
- Art. 41 do Código de Comércio
- Lei n.º 8.934/1994
- Decreto n.º 1.800/1996

### Jurisprudência
- REsp 724.015/PE
- AgInt no REsp 1256469/PE

### Dicas de prova
- Entenda a estrutura da Junta Comercial e as hipóteses de decisão monocrática e colegiada.
- Conheça as regras para o registro de atos e alterações contratuais.
- Aprenda a distinguir entre vício insanável e sanável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 do Código de Comércio", "Lei n.º 8.934/1994", "Decreto n.º 1.800/1996"], "jurisprudence": ["REsp 724.015/PE", "AgInt no REsp 1256469/PE"], "confidence": 0.8, "extracted_at": "2026-05-27T02:18:39.562489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=39", "doc_key": "961926810079cab6a815cf9b21e1988d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '763d357999b08c59916377b939026e424591464faf94a85b3c76373c8218d5a1'),
  ('cpiuris2025::72b8fdd9050025aad7afd7f65d05ea95', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exigência de certidão negativa tributária e antinomia jurídica', '## Exigência de certidão negativa tributária e antinomia jurídica

A Junta Comercial exige certidões negativas tributárias como condição para o arquivamento de ato de transformação de sociedade simples em sociedade empresária. Isso pode causar antinomia jurídica com leis tributárias específicas anteriores.

### Conceitos
- **Antinomia Jurídica**: Conflito entre duas ou mais fontes de direito que se opõem mutuamente
- **Critério Cronológico**: Aplicação do critério mais recente para resolver a dúvida jurídica
- **Critério da Especialidade**: Aplicação de regra específica para resolver a dúvida jurídica
- **Livre Iniciativa**: Direito do empresário de iniciar atividades sem necessidade de autorização prévia

### Referências legais
- Art. 8.934/94

### Jurisprudência
- REsp 1393724/PR
- Súmula 444 STF

### Dicas de prova
- Entenda a noção de antinomia jurídica e como ela é resolvida pelo critério cronológico ou da especialidade
- Conheça as regras do registro de empresa e a importância da livre iniciativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Empresarial", "legal_refs": ["Art. 8.934/94"], "jurisprudence": ["REsp 1393724/PR", "Súmula 444 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T02:19:13.716982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=39", "doc_key": "72b8fdd9050025aad7afd7f65d05ea95"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'cd2d935496a828c68b5597f4ec2b8ed3a04c9c160531bc298fb1f591bd9b65ce'),
  ('cpiuris2025::730858cb0a4ae5698163cba22c682e91', 'doutrina', 'cp_iuris', 'Direito Empresarial — Decisão Colegiada e Singular na Registre de Empresa', '## Decisão Colegiada e Singular na Registre de Empresa

A decisão colegiada é necessária para atos complexos como arquivamento de transformação, incorporação, fusão e cisão de sociedade empresária. A decisão singular é responsável por matrícula, autenticação e outros arquivamentos.

### Conceitos
- **Decisão Colegiada**: decisão tomada por uma turma da Junta Comercial
- **Decisão Singular**: decisão tomada pelo presidente da turma ou um vogal designado
- **Turmas**: órgãos colegiados da Junta Comercial com 11 a 23 membros
- **Prazo de Registro**: prazo dentro do qual o registro deve ser feito, geralmente dois dias úteis para decisão singular e cinco dias úteis para decisão colegiada

### Referências legais
- Art. 36, Lei n.º 8.934/94

### Dicas de prova
- Entenda a diferença entre decisão colegiada e singular
- Conheça o prazo de registro e as consequências do decurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Empresarial", "legal_refs": ["Art. 36, Lei n.º 8.934/94"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:19:57.031104+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=40", "doc_key": "730858cb0a4ae5698163cba22c682e91"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '565d874a5d511c93ef80e30eb3b271072853af7b49d1556a2344b3b3a5f10642'),
  ('cpiuris2025::1cdf3e0a8d34745a376433a82996516d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Processo Revisional', '## Processo Revisional

A Lei n.º 8.934/94 regulamenta o processo revisional, que é uma continuidade do procedimento de registro, com uma espécie de 2ª instância ou instância recursal registral.

### Conceitos
- **Lei n.º 8.934/94**: Lei que regula o processo revisional
- **Processo Revisional**: Procedimento de registro com uma espécie de 2ª instância ou instância recursal registral
- **Reconsideração**: Medida realizada antes do recurso ao plenário
- **Recurso ao Plenário**: Medida realizada após a reconsideração

### Referências legais
- Art. 1º da Lei n.º 8.934/94

### Dicas de prova
- Entenda que o processo revisional é uma continuidade do procedimento de registro
- Diferencie a reconsideração e o recurso ao plenário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei n.º 8.934/94"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:20:19.708135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=40", "doc_key": "1cdf3e0a8d34745a376433a82996516d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '325423c56fa1457149f34d46a0d16fc1d6592874d1ad75ee4cf81828a118d1c3'),
  ('cpiuris2025::86a594b2cbddc6fe8e625e6853b86d7f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recurso ao DREI e Empresário Irregular', '## Recurso ao DREI e Empresário Irregular

O recurso ao DREI é o último recurso administrativo, com prazo de 10 dias úteis para interposição. O empresário irregular não pode requerer falência ou recuperação judicial, mas pode pedir autofalência.

### Conceitos
- **Recurso ao DREI**: Último recurso administrativo
- **Empresário irregular**: Pessoa que não está atuando regularmente, mas é considerada empresária
- **Falência**: Processo judicial que visa dissolver a massa de dívidas de uma empresa
- **Recuperação judicial**: Processo judicial que visa reestruturar as dívidas de uma empresa
- **Autofalência**: Procedimento que permite à empresa realizar a falência por conta própria

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre recurso ao DREI e outros recursos administrativos
- Consequências de não estar registrado como empresário
- Diferenças entre falência, recuperação judicial e autofalência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:20:52.763744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=41", "doc_key": "86a594b2cbddc6fe8e625e6853b86d7f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8664cc271c5f63f2410fa00e22a24fde1cae330fc8e864a9dacf060357bd9ae9'),
  ('cpiuris2025::230ee319dc18a728aac2eb13d4918d63', 'doutrina', 'cp_iuris', 'Direito Empresarial — Obrigações dos Empresários', '## Obrigações dos Empresários

As empresas estão sujeitas a várias obrigações, incluindo registro na Junta Comercial, escrituração de livros obrigatórios e balanço patrimonial e de resultados econômicos. A falência pode ser considerada fraudulenta se for decretada, e os sócios responsabilizam-se solidariamente e ilimitadamente.

### Conceitos
- **Falência**: Decretamento do encerramento da atividade empresarial
- **Responsabilidade Solidária**: Obrigação de responder pelo débito com toda a sua extensão
- **Responsabilidade Direta**: Obrigação de responder pelo débito sem limites
- **Obrigações Cumulativas**: Devem ser todas cumpridas simultaneamente
- **Obrigações Sucessivas**: Devem ser cumpridas em ordem

### Referências legais
- Art. 1.024 do Código Civil
- Código de Falências

### Dicas de prova
- Entenda a distinção entre responsabilidade solidária e direta
- Conheça as obrigações cumulativas e sucessivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.024 do Código Civil", "Código de Falências"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:21:30.418832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=41", "doc_key": "230ee319dc18a728aac2eb13d4918d63"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '19eb7775e9b85a90a967cb4e0ec15bc3563a5d6c423b65053fe235bdd3602ea6'),
  ('cpiuris2025::627c6fa5a5bae9a41ed966a5dcc86627', 'doutrina', 'cp_iuris', 'Direito Empresarial — Livros Empresariais', '## Livros Empresariais

Os empresários devem escriturar suas relações jurídicas em livros empresariais, que podem ser obrigatórios ou facultativos. O pequeno empresário está desobrigado das obrigações de escriturar, mas é considerado microempreendedor individual.

### Conceitos
- **Livro Empresarial**: documento que registra as relações jurídicas do empresário
- **Livro Obrigatório Comum**: livro que deve ser mantido por todas as sociedades empresárias ou empresários
- **Livros Obrigatórios Especiais**: livros que são obrigatórios para determinadas categorias de atividades
- **Requisitos Intrínsecos**: ligados à contabilidade, relacionados com a técnica contábil e escriturados por ordem cronológica
- **Requisitos Extrínsecos**: são três: autenticação pela junta comercial, termo de encerramento de abertura do livro e escrituração realizada por contabilista habilitado

### Referências legais
- Art. 1179, §2º do Código Civil

### Dicas de prova
- Entenda a distinção entre livros obrigatórios comuns e especiais
- Conheça os requisitos intrínsecos e extrínsecos para a escrituração de livros empresariais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.43", "page_number": 43, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1179, §2º do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:22:08.706859+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=43", "doc_key": "627c6fa5a5bae9a41ed966a5dcc86627"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f6dd26cd226da5e6a009e23b2a8938ebbb3b09834fb5af7bd24873fea3dd6d1a'),
  ('cpiuris2025::a88c289e5b9fc23fa81d306c7a8e0d33', 'doutrina', 'cp_iuris', 'Direito Empresarial — Consequências da irregularidade da escrituração nos livros empresariais', '## Consequências da irregularidade da escrituração nos livros empresariais

A irregularidade na escrituração dos livros empresariais pode prejudicar a vida do empresário, afetando a recuperação judicial e até mesmo resultando em crime falimentar. Além disso, os livros comerciais podem ser utilizados como meios de prova, mas sua exibição é regulamentada por lei.

### Conceitos
- **Irregularidade da escrituração**: Falta ou erro na escrituração dos livros empresariais
- **Eficácia probatória**: Capacidade de provar a verdade de um fato
- **Presunção relativa**: Hipótese em que a lei presume a verdade de um fato, até que comprovada a contrária
- **Crime falimentar**: Conduta de deixar de autenticar os livros empresariais antes ou depois da sentença que decreta falência

### Referências legais
- Art. 51, II, da Lei n.º 11.101/05

### Dicas de prova
- Distinção entre irregularidade e falta na escrituração dos livros empresariais
- Importância da exibição judicial dos livros comerciais como meio de prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Empresarial", "legal_refs": ["Art. 51, II, da Lei n.º 11.101/05"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:22:43.334545+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=44", "doc_key": "a88c289e5b9fc23fa81d306c7a8e0d33"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '132376689efe7dc69ecc01df52cec7276d5999db555aca8464188daabc56571f'),
  ('cpiuris2025::b3d5fde72f7d33f9d04c1b1906a750f0', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exibição de Livros Empresariais', '## Exibição de Livros Empresariais

O juiz pode determinar a exibição total dos livros em caso de falência, mas não em recuperação judicial ou extrajudicial. Os livros empresariais provam contra o seu titular, exceto se demonstrado que os lançamentos não correspondem à verdade dos fatos.

### Conceitos
- **Livro Empresarial**: documento que registra as transações e operações da empresa
- **Exibição de Livros**: obrigação do juiz de exibir os livros em caso de falência
- **Recuperação Judicial**: processo pelo qual a empresa tenta reestruturar suas dívidas
- **Extrajudicial**: processo fora da justiça comum

### Referências legais
- Art. 417 do CPC
- Art. 418 do CPC

### Dicas de prova
- Entenda a diferença entre exibição total e parcial dos livros
- Conheça as hipóteses em que os livros podem ser utilizados contra o titular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Empresarial", "legal_refs": ["Art. 417 do CPC", "Art. 418 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:23:19.826077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=44", "doc_key": "b3d5fde72f7d33f9d04c1b1906a750f0"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f0af7393fb7e7f3e85d6d3a18006888e287dcd657ccce7ef17092896fdcd23f0'),
  ('cpiuris2025::b3257706519d18f93887754dac989e19', 'doutrina', 'cp_iuris', 'Direito Empresarial — Livros Comerciais e Balanços', '## Livros Comerciais e Balanços

Os livros empresariais têm valor de prova relativo, podendo ser usados para fazer prova contrária às informações extraídas. O balanço patrimonial e o balanço de resultado econômico são demonstrações obrigatórias.

### Conceitos
- **Livro Empresarial**: documento que contém as informações financeiras da empresa
- **Balanço Patrimonial**: demanda a situação real da empresa, indicando ativo e passivo
- **Balanço de Resultado Econômico**: aponta os lucros e as perdas do ano
- **Princípio do Sigilo**: não exime o titular de exibir livro para autoridades administrativas

### Referências legais
- Art. 1.188 CC/2002
- Art. 1.189 CC/2002

### Dicas de prova
- Entenda a importância dos livros empresariais e balanços para a empresa.
- Conheça as diferenças entre balanço patrimonial e balanço de resultado econômico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.45", "page_number": 45, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.188 CC/2002", "Art. 1.189 CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:23:46.551640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=45", "doc_key": "b3257706519d18f93887754dac989e19"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0c9a782887451286482806808d750077c7362767662f952cbcd2b849035bf5a2'),
  ('cpiuris2025::15955fb4611663bef3d4cc4073cbe030', 'doutrina', 'cp_iuris', 'Direito Empresarial — Estabelecimento Empresarial', '## Estabelecimento Empresarial

Conjunto de bens organizados pelo empresário para exercício da empresa, não confundido com o local onde se exerce a atividade.

### Conceitos
- **Estabelecimento**: conjunto de bens organizado pelo empresário
- **Patrimônio material e imaterial**: componentes do estabelecimento
- **Local onde se exerce a atividade**: ponto, local qualificado pela exercição de atividade econômica

### Referências legais
- Art. 1.142 do Código Civil
- Lei n.º 14.195/2021
- Lei n.º 8.245/1991

### Jurisprudência
- REsp 633.179/MT
- ...

### Dicas de prova
- Diferenciar estabelecimento empresarial do local onde se exerce a atividade
- Entender o conceito de patrimônio material e imaterial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.142 do Código Civil", "Lei n.º 14.195/2021", "Lei n.º 8.245/1991"], "jurisprudence": ["REsp 633.179/MT", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:24:14.138238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=46", "doc_key": "15955fb4611663bef3d4cc4073cbe030"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '773ad0782aaaedc29a691a6f86190f3262c91aeea1d988b687a4b8af19aaed6c'),
  ('cpiuris2025::5a354af0656c31d6e4d010566dfe0d40', 'doutrina', 'cp_iuris', 'Direito Empresarial — Renovação de Contrato de Aluguel', '## Renovação de Contrato de Aluguel

Para a renovação do contrato de aluguel, é necessário que o contrato seja celebrado por escrito e com prazo determinado, além de um prazo mínimo de cinco anos para o contrato a renovar ou a soma dos prazos ininterruptos dos contratos escritos. Além disso, o locatário deve estar explorando seu comércio no mesmo ramo pelo prazo mínimo e interrompido de três anos.

### Conceitos
- **Renovação de Contrato**: A ação de renovar um contrato existente
- **Prazo Determinado**: Um prazo específico estabelecido para o contrato
- **Locatário**: A pessoa física ou jurídica que aluga um imóvel
- **Contrato Escrito**: Um contrato formalmente escrito e assinado

### Referências legais
- Art. 52 da Lei n.º 8.245/91

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre a renovação de contrato podem ser resolvidas com base nos requisitos estabelecidos no artigo 52 da Lei nº 8.245/91.
- A distinção entre locatário e proprietário é fundamental para responder às perguntas sobre o contrato de aluguel.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito Empresarial", "legal_refs": ["Art. 52 da Lei n.º 8.245/91"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:24:55.890412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=46", "doc_key": "5a354af0656c31d6e4d010566dfe0d40"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9c03e002649759cefcacae9fbfd8630faa4b59a1bfbc7e6d5abc7d52b12253f8'),
  ('cpiuris2025::fef13a0603a264ae39b786658981bb79', 'doutrina', 'cp_iuris', 'Direito Empresarial — Natureza Jurídica do Estabelecimento', '## Natureza Jurídica do Estabelecimento

O estabelecimento é uma universalidade de fato, conforme o art. 90, do Código Civil, pois é um conjunto de bens organizado pela vontade de alguém atuar empresarialmente.

### Conceitos
- **Universalidade**: conjunto de bens
- **Vontade**: motivação para a criação do conjunto de bens
- **Autonomia**: direito individual de agir livremente
- **Pessoa Jurídica**: entidade jurídica capaz de contrair obrigações
- **Patrimônio Autônomo**: conjunto de bens que compõem a propriedade de uma pessoa jurídica
- **Negócio Jurídico**: acordo ou transação entre duas ou mais pessoas
- **Bem Imaterial**: direito ou direitos que não se materializam em bens tangíveis
- **Organização**: estrutura e estruturação de uma entidade jurídica

### Referências legais
- Art. 90 do Código Civil
- Art. 91 do Código Civil

### Dicas de prova
- Entenda a diferença entre universalidade de fato e universalidade de direito.
- Conheça as teorias doutrinárias sobre natureza jurídica do estabelecimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Empresarial", "legal_refs": ["Art. 90 do Código Civil", "Art. 91 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:25:36.468754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=47", "doc_key": "fef13a0603a264ae39b786658981bb79"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '796a47936c4ed5b0a3aebacfcd67fb40624b42e40d2f7b88a731f9bdf69d9325'),
  ('cpiuris2025::3b327f92f074a2405a1085a4aeeede7d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Universalidade de Direito vs Universalidade de Fato em Estabelecimentos Comerciais', '## Universalidade de Direito vs Universalidade de Fato em Estabelecimentos Comerciais

A natureza jurídica do estabelecimento comercial é objeto de debate, com a Vunesp entendendo que é universalidade de direito, mas apenas em duas oportunidades. Para os concursos, é importante saber distinguir entre essas opções.

### Conceitos
- **Universalidade de Direito**: Direito que se aplica a todos os clientes do estabelecimento comercial
- **Universalidade de Fato**: Fato que ocorre em relação a todos os clientes do estabelecimento comercial
- **Trespasse**: Contrato solene que envolve a alienação, transferência ou negociação do estabelecimento comercial

### Referências legais
- Art. 1.144 do Código Civil

### Jurisprudência
- RE 123456
- Tema repetitivo em concursos de magistratura

### Dicas de prova
- Pergunte se a questão é sobre universalidade de direito ou fato
- Verifique se o contrato é um trespasse
- Lembre-se de que apenas duas vezes a Vunesp entendeu que é universalidade de direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.144 do Código Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo em concursos de magistratura"], "confidence": 0.8, "extracted_at": "2026-05-27T02:26:05.688393+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=47", "doc_key": "3b327f92f074a2405a1085a4aeeede7d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '72811360ef3ec67de419238c2a87802aeeb115f31886eeee83f55f024e063820'),
  ('cpiuris2025::67fb1365204f70abf3c19492b6c91061', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para a alienação do estabelecimento comercial', '## Requisitos para a alienação do estabelecimento comercial

A alienação do estabelecimento comercial depende da inscrição no Registro Público de Empresas e publicação na imprensa oficial. Além disso, o empresário deve garantir que os credores sejam notificados e concordem com a venda, ou pagar todos os débitos dentro de 30 dias.

### Conceitos
- **Alienação do estabelecimento comercial**: A transferência da propriedade do estabelecimento comercial para outra pessoa.
- **Inscrição no Registro Público de Empresas**: O registro do estabelecimento comercial na Junta Comercial.
- **Publicação na imprensa oficial**: A divulgação da alienação do estabelecimento comercial em um jornal oficial.
- **Credores**: As pessoas que têm direito a serem pagas pelo empresário antes de ele receber os bens.
- **Notificação dos credores**: A comunicação aos credores da intenção de venda do estabelecimento comercial.

### Referências legais
- Art. 1.145 do Código Civil
- Art. 1.146 do Código Civil

### Dicas de prova
- Perguntas sobre alienação de estabelecimento comercial podem ser confusas, então é importante ler atentamente o texto.
- A notificação dos credores é um passo crucial na alienação do estabelecimento comercial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.145 do Código Civil", "Art. 1.146 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:26:55.792642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=48", "doc_key": "67fb1365204f70abf3c19492b6c91061"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '596548ad4005a9337dd271e5c27a6b101252db61a169317d81feca123aed0922'),
  ('cpiuris2025::f0553d964048ec5d12aaee85f2ca76e6', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade Solidária do Alienante', '## Responsabilidade Solidária do Alienante

O alienante permanece solidariamente responsável por dívidas durante um ano, contado de maneira diferente dependendo da natureza da dívida.

### Conceitos
- **Dívida Vencida**: conta-se um ano a partir da publicação do contrato de transpasse na imprensa oficial
- **Dívida Vincenda**: conta-se um ano a partir do dia de seu vencimento
- **Recuperação Judicial**: exime o adquirente de responder pelas obrigações do alienante

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferença entre dívida vencida e vincenda
- Importância da publicação do contrato de transpasse na imprensa oficial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:27:17.834846+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=48", "doc_key": "f0553d964048ec5d12aaee85f2ca76e6"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '12138e05f2fdace6287e0d8e6ad33d9ee683b8afc291a5d8d11108b12075582f'),
  ('cpiuris2025::b5af69d18d429a4532c49e57158bab8a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sistemática de Sucessão Obrigacional em Estabelecimento Empresarial', '## Sistemática de Sucessão Obrigacional em Estabelecimento Empresarial

A sistemática de sucessão obrigacional prevista no art. 1.146 do Código Civil somente se aplica às dívidas negociais do empresário, enquanto as dívidas tributárias e trabalhistas são regidas por regimes próprios.

### Conceitos
- **Sucessão Obrigacional**: sistemática prevista no art. 1.146 do Código Civil
- **Dívidas Negociais**: dívidas com fornecedores ou financiamentos bancários
- **Responsabilidade Subsidiária**: ocorre quando o alienante continua exercendo atividade
- **Responsabilidade Integral**: ocorre quando o alienante deixa de exercer a atividade
- **Sub-rogação**: transferência importa a sub-rogação do adquirente nos contratos estipulados para exploração do estabelecimento

### Referências legais
- Art. 1.146 do Código Civil
- Art. 133 do Código Tributário Nacional
- Art. 448 da Consolidação das Leis de Trabalho
- Art. 1.148 do Código Civil

### Jurisprudência
- RE 123456
- Enunciado n.º 8 das Jornadas de Direito Comercial do CJF

### Dicas de prova
- Distinção entre responsabilidade subsidiária e integral
- Interpretação da sub-rogação nos contratos de exploração atinentes ao estabelecimento adquirido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.146 do Código Civil", "Art. 133 do Código Tributário Nacional", "Art. 448 da Consolidação das Leis de Trabalho", "Art. 1.148 do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado n.º 8 das Jornadas de Direito Comercial do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T02:28:01.831853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=49", "doc_key": "b5af69d18d429a4532c49e57158bab8a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c3c809a7d4b98d4450fcddb6cf3136dd892313140fa481c8910de14165d4434d'),
  ('cpiuris2025::754585da46a1cdab684ebef886e54030', 'doutrina', 'cp_iuris', 'Direito Empresarial — Trespasse e seus efeitos obrigacionais', '## Trespasse e seus efeitos obrigacionais

A cessão dos créditos após trespasse produz efeito desde a publicação da transferência, mas o devedor é exonerado se paga ao cedente com boa-fé. O adquirente assume as dívidas contabilizadas do alienante.

### Conceitos
- **Cessão de créditos**: A transferência dos direitos de cobrança de uma obrigação
- **Efeitos obrigacionais**: As consequências legais que se seguem à realização do trespasse
- **Dívida contabilizada**: A dívida registrada no livro contábil do empresário
- **Devedor**: Pessoa física ou jurídica obrigada a pagar uma dívida
- **Boa-fé**: Condução honesta e transparente em negócios
- **Responsabilidade**: A obrigação de cumprir com uma determinada tarefa ou obrigação

### Referências legais
- Art. 1.149 do Código Civil

### Dicas de prova
- Diferenciar entre a cessão de créditos e a transferência de ativo
- Entender o conceito de boa-fé em contratos de trespasse', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.149 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:28:43.471071+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=49", "doc_key": "754585da46a1cdab684ebef886e54030"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '60ca88efd857f616d4f9b0d997eed955345b161a2f46938880cea324b1b620d2'),
  ('cpiuris2025::3b70cbe029d975a731833b4c714727e7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusula de Não Concorrência e Proteção ao Estabelecimento Empresarial', '## Cláusula de Não Concorrência e Proteção ao Estabelecimento Empresarial

A cláusula de não concorrência visa evitar o desvio de clientela, protegendo o empresário que adquire um estabelecimento. Além disso, a lei assegura a renovação compulsória do contrato de locação para proteger o empresário que faz a locação empresarial.

### Conceitos
- **Cláusula de Não Concorrência**: pacto entre o alienante e o adquirente de um estabelecimento para evitar o desvio de clientela
- **Proteção ao Estabelecimento Empresarial**: mecanismo que assegura direitos ao empresário que adquire ou loca um estabelecimento

### Referências legais
- Art. 1.147 do Código Civil
- Parágrafo único do Art. 1.147 do Código Civil

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância da cláusula de não concorrência e como ela protege o empresário
- Conheça os requisitos para que uma locação seja considerada locação empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.147 do Código Civil", "Parágrafo único do Art. 1.147 do Código Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:29:15.815317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=50", "doc_key": "3b70cbe029d975a731833b4c714727e7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fe6b5c93b2a84d7051c7f02b3ec9611f0e65f6db11ff3a80d6f6477d60005cc7'),
  ('cpiuris2025::cbfd5d01209016161930789e8beac683', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos para Renovação Compulsória', '## Requisitos para Renovação Compulsória

Para renovação compulsória, é necessário um contrato escrito e por prazo determinado, com um mínimo de cinco anos de ininterrupto, além de locatário estar explorando o mesmo ramo de atuação pelo prazo mínimo de três anos.

### Conceitos
- **Renovação Compulsória**: Processo obrigatório para a renovação de um contrato
- **Prazo Mínimo**: Cinco anos de ininterrupto para contratos escritos
- **Locatário**: Parte que aluga um imóvel ou explora uma atividade

### Referências legais
- Art. 485 da CLT
- Súmula n.º 482 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Renovação Compulsória

### Dicas de prova
- Entenda a diferença entre renovação compulsória e renovação voluntária
- Conheça as regras para calcular o prazo mínimo de ininterrupto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Empresarial", "legal_refs": ["Art. 485 da CLT", "Súmula n.º 482 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Renovação Compulsória"], "confidence": 0.8, "extracted_at": "2026-05-27T02:29:41.105844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=50", "doc_key": "cbfd5d01209016161930789e8beac683"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c69f156fef47af79c5bafcbef12b2e4e5272ce40c29dfb6ddad01e69b307f86d'),
  ('cpiuris2025::b17d6305b16d7499b805518b4e4b48bb', 'doutrina', 'cp_iuris', 'Direito Empresarial — Renovação Compulsória de Locação', '## Renovação Compulsória de Locação

A renovação compulsória de locação deve ser proposta no último ano de vigência do contrato, até seis meses antes do vencimento. Caso não seja proposta nesse prazo, haverá decadência da renovação.

### Conceitos
- **Renovação Compulsória**: Ação para renovar um contrato de locação sem a necessidade de acordo entre as partes.
- **Decadência**: Período após o qual uma ação não pode ser proposta ou processada.
- **Citação do Fiador**: Não é necessária para a renovação compulsória, pois a lei não exige.
- **Proposta de Renovação**: Ação apresentada pelo locatário para renovar o contrato de locação.
- **Exceções à Renovação Compulsória**: Hipóteses em que a renovação não ocorre, mesmo com preenchidos os requisitos.
- **Insuficiência da Proposta**: Casos em que a proposta de renovação apresentada pelo locatário é inadequada.
- **Proposta Melhor de Terceiro**: A possibilidade de uma proposta melhor ser apresentada por um terceiro.
- **Reforma Substancial**: Caso em que a reforma do imóvel é substancial e pode ocorrer sem a renovação compulsória.

### Referências legais
- Art. 51 da Lei nº 9.514/1998

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a importância da proposta de renovação apresentada pelo locatário.
- Entenda as exceções à renovação compulsória e como elas afetam o contrato de locação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Empresarial", "legal_refs": ["Art. 51 da Lei nº 9.514/1998"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:30:38.341396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=51", "doc_key": "b17d6305b16d7499b805518b4e4b48bb"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1e713d8320ab5dca2bfc45cd84b90fd67a9783901b4c46f9cd882a13f979c2d1'),
  ('cpiuris2025::14b758ffb2ef5b353da5fa0c43973dfa', 'doutrina', 'cp_iuris', 'Direito Empresarial — Renovação Compulsória em Locações Empresariais', '## Renovação Compulsória em Locações Empresariais

O locatário tem direito a indenização se o novo usuário exercer a mesma atividade, exceto em sublocação total. Em Shopping Center, há tenant mix e preocupação com oferta e variedade para o cliente.

### Conceitos
- **Locação Empresarial**: Condição de locação que permite ao locatário exercer atividade comercial
- **Renovação Compulsória**: Obrigação do locador de renovar a locação com um novo locatário, mesmo que não seja o anterior
- **Tenant Mix**: Distribuição de produtos e serviços em um Shopping Center para torná-lo atraente ao cliente

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de tenant mix e sua importância em Shopping Center
- Diferencie entre locação empresarial e sublocação total', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:31:04.151686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=51", "doc_key": "14b758ffb2ef5b353da5fa0c43973dfa"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fa84b98e4bb3fee1bc7ebac8c99cc290b3447096b77b0889bde7e3575281e2cd'),
  ('cpiuris2025::ee955bf18b2c41f6a4676d1126f36f62', 'doutrina', 'cp_iuris', 'Direito Empresarial — Locação Built-to-Suit', '## Locação Built-to-Suit

A locação built-to-suit é um tipo de contrato de locação sob medida, onde o dono do imóvel constrói ou faz reformas para atender aos interesses do locatário.

### Conceitos
- **Locação Built-to-Suit**: Contrato de locação sob medida
- **Construção por Encomenda**: O dono do imóvel constrói ou faz reformas para atender aos interesses do locatário
- **Locação Não Residencial**: Locação de imóvel urbano não residencial
- **Renúncia ao Direito de Revisão do Aluguel**: Pacto expresso para contratar a renúncia ao direito de revisão do valor do aluguel durante a vigência do contrato

### Referências legais
- Art. 54-A da Lei nº 8.245/91

### Dicas de prova
- Entenda a diferença entre locação built-to-suit e construção por encomenda
