O texto destaca a proteção do estabelecimento empresarial, abordando casos de responsabilidade civil e penal por desvio de clientela e concorrência desleal.

### Conceitos
- **Concorrência Desleal**: Prática que envolve o uso de meios fraudulosos para obter vantagem em proveito próprio ou alheio
- **Responsabilidade Civil**: Obrigação de reparar os danos causados a terceiros
- **Responsabilidade Penal**: Obrigação de punir o indivíduo que cometeu um crime

### Referências legais
- Art. 195, III, da Lei de Propriedade Industrial (LPI)

