- **Nome de Domínio**: Função de identificação do empresário na rede mundial de computadores
- **Título de Estabelecimento**: Canal de identificação da clientela
- **Proteção ao Nome Empresarial**: Necessidade de proteger o nome empresarial para evitar concorrência desleal

