  ('cpiuris2025::8ac38d0ac4581e5e357cd780780598f3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Nome Empresarial', '## Nome Empresarial

O Nome Empresarial é um direito da personalidade do empresário, identificando-o como sujeito de direitos no mercado. É composto pela firma e denominação, com princípios de veracidade e novidade.

### Conceitos
- **Nome Empresarial**: Expressão que identifica o empresário ou sociedade como sujeito de direitos no mercado
- **Firma**: Composição do Nome Empresarial, incluindo nome civil e denominação
- **Denominação**: Parte do Nome Empresarial que pode incluir palavras da língua nacional ou estrangeira
- **Grupo**: Uso exclusivo dos grupos de sociedades organizados, mediante convenção
- **Registro de Empresas**: Ogivo onde são registradas as empresas e seus nomes

