- Art. 19 da Instrução Normativa DREI n.º 81/2020
- Art. 20 da Instrução Normativa DREI n.º 81/2020
- Art. 21 da Instrução Normativa DREI n.º 81/2020
- Art. 22 da Instrução Normativa DREI n.º 81/2020

