  ('cpiuris2025::6c1710b387120528110f769968617f03', 'doutrina', 'cp_iuris', 'Direito Empresarial — Proteção ao Nome Empresarial', '## Proteção ao Nome Empresarial

Rege-se a proteção ao nome empresarial pelo ato de registro e circunscribe-se à unidade federativa da jurisdição da Junta Comercial que o tiver procedido.

### Conceitos
- **Novidade**: Princípio que impede a coexistência de dois nomes empresariais idênticos ou semelhantes na mesma unidade federativa.
- **Identidade**: Considera-se o nome empresarial que tem exatamente a mesma composição do anteriormente registrado na mesma Junta Comercial.
- **Semelhança**: Considera-se o nome empresarial que tem distinção em relação a apenas alguns caracteres, mas não resulta em diferença significativa quanto à grafia ou à pronúncia.
- **Análise de identidade e semelhança**: Será feita considerando-se os nomes empresariais por inteiro, desconsiderando-se apenas as expressões relativas ao tipo jurídico adotado.

### Referências legais
- Art. 23 da Lei X da Empresa

### Dicas de prova
- Distinção entre identidade e semelhança
- Análise de identidade e semelhança
- Importância do ato de registro na proteção ao nome empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direito Empresarial", "legal_refs": ["Art. 23 da Lei X da Empresa"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:34:27.713469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=55", "doc_key": "6c1710b387120528110f769968617f03"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7cea4df02dd9d9129f6ca140c74f09017141a416cac3f6aa2aa9c9f865a56269'),
  ('cpiuris2025::eeb22d640a1d35b7c6ab1f0d345eb899', 'doutrina', 'cp_iuris', 'Direito Empresarial — Nome Empresarial e Transferência de Sede', '## Nome Empresarial e Transferência de Sede

A transferência de sede de empresa individual ou sociedade empresária requer a alteração do nome empresarial, com exceção de casos em que o nome é mantido na Junta Comercial da unidade federativa de destino.

### Conceitos
- **Firma**: Assinatura do empresário ou sociedade, composta por um nome civil completo ou abreviado
- **Denominação**: Nome da empresa que inclui a descrição do ramo de atividade e pode conter elementos fantasia

### Referências legais
- Art. 1.156 CC/02
- Art. 26

