  ('cpiuris2025::497822e2b0db7a4a0e0b4f739026ab53', 'doutrina', 'cp_iuris', 'Direito Empresarial — Nome Empresarial e Elementos de Identificação', '## Nome Empresarial e Elementos de Identificação

O nome empresarial é expressão que identifica o empresário como sujeito de direitos, enquanto outros elementos são título do estabelecimento, marca e nome de domínio.

### Conceitos
- **Nome Empresarial**: expressão que identifica o empresário como sujeito de direitos
- **Nome Fantasia**: expressão que identifica o título do estabelecimento
- **Marca**: expressão que identifica produtos ou serviços do empresário
- **Nome de Domínio**: endereço eletrônico dos sites dos empresários na internet

### Referências legais
- Art. 55 da Lei nº 9.532/1997

### Jurisprudência
- REsp 594404/DF
- Súmula 373 do STJ

### Dicas de prova
- Diferenciar entre nome empresarial e outros elementos de identificação
