  ('cpiuris2025::367a074ce73b2be08e2b84896955285c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Princípios do Nome Empresarial', '## Princípios do Nome Empresarial

O nome empresarial deve ser verdadeiro e identificar fidedignamente o empresário, com exceção de casos específicos como a morte ou exclusão de sócios.

### Conceitos
- **Princípio da Veracidade**: O nome empresarial não pode conter informações falsas e deve identificar fidedignamente o empresário.
- **Má-fé**: Análise caso a caso para comprovar má-fé em casos de registro repetido

### Referências legais
- Art. 1165, Código Civil

### Dicas de prova
- Perguntas sobre princípios do nome empresarial
- Distinção entre informações falsas e identificação fidedigna', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1165, Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:35:51.013853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=56", "doc_key": "367a074ce73b2be08e2b84896955285c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '88dbe1acf0a7ec31e38577e305c2e56aa09587ba0a86c8f2f1580df6dd8bb4ce'),
  ('cpiuris2025::b1948e37755057e220207a5ebae4da5b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Princípio da Novidade e Formação do Nome Empresarial', '## Princípio da Novidade e Formação do Nome Empresarial

O nome empresarial deve ser único e diferente de outros registros no órgão competente, para evitar abalo de crédito e confusão. A marca é protegida em todo território nacional, mas o nome empresarial está protegido apenas no estado onde foi registrado.

### Conceitos
- **Princípio da Novidade**: O princípio que exige que o nome empresarial seja único e diferente de outros registros no órgão competente
- **Firma**: A forma como um empresário ou sociedade se apresenta, geralmente com o nome do proprietário ou da empresa
- **Sociedade em Nome Coletivo**: Uma sociedade que tem apenas um sócio, e pode adotar uma firma com o nome do sócio
- **Sociedade em Comandita Simples**: Uma sociedade que tem sócios comanditados e comanditários, e pode adotar uma firma com os nomes dos sócios comanditados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o princípio da novidade e a importância de uma firma única
- Conheça as diferentes formas de sociedades e suas firmas correspondentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:36:26.788874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=57", "doc_key": "b1948e37755057e220207a5ebae4da5b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a66fdd75e929b4f5cce686bf8443813835e20666c2292c8bfc77e3639f2e4c7a'),
  ('cpiuris2025::18794c4f2aed1b01d7cb31e049304ce4', 'doutrina', 'cp_iuris', 'Direito Empresarial — Firmas e Denominações Sociais', '## Firmas e Denominações Sociais

As sociedades podem adotar firma ou denominação, mas o nome empresarial deve conter a partícula ''Ltda.'' para informar responsabilidade limitada. A sociedade anônima só pode adotar denominação com identificação do tipo societário.

### Conceitos
- **Firma**: nome ou expressão utilizada pela sociedade para se apresentar
- **Denominação**: nome ou expressão que identifica o tipo societário da sociedade
- **Partícula ''Ltda.''**: expressão necessária no nome empresarial para informar responsabilidade limitada
- **Sociedades Anônimas**: sócios detêm responsabilidade limitada, mas não há cláusula expressa
- **Sociedades em Comandita por Ações**: sócios respondem ilimitadamente pelas obrigações sociais

### Referências legais
- Art. 55 da Lei nº 11.101/2005

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre firma e denominação
- Verifique se o nome empresarial contém a partícula ''Ltda.''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Empresarial", "legal_refs": ["Art. 55 da Lei nº 11.101/2005"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:37:07.650986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=57", "doc_key": "18794c4f2aed1b01d7cb31e049304ce4"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3a5e4173f7a04b31393cbae5bca82484b85013a1a63005eec6dec9c1562058d8'),
  ('cpiuris2025::6e1f41109a64e8adabde5dd13a34df95', 'doutrina', 'cp_iuris', 'Direito Empresarial — Nome Empresarial e Alteração do Nome Empresarial', '## Nome Empresarial e Alteração do Nome Empresarial

O nome empresarial é composto pelo nome da pessoa jurídica e a partícula identificadora do tipo societário. A alteração do nome empresarial é possível, mas há hipóteses em que é obrigatória, como saída de um sócio ou alteração da categoria do sócio.

### Conceitos
- **Nome Empresarial**: nome da pessoa jurídica seguido da partícula identificadora do tipo societário
- **Alteração do Nome Empresarial**: mudança do nome da empresa, possível com a vontade do empresário, mas obrigatória em certas hipóteses

### Referências legais
- Art. 15 da Lei n.º 14.195/21

### Dicas de prova
- Distinção entre nome empresarial e denominação
- Hipóteses em que a alteração do nome empresarial é obrigatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.58", "page_number": 58, "discipline": "Direito Empresarial", "legal_refs": ["Art. 15 da Lei n.º 14.195/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:37:36.504170+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=58", "doc_key": "6e1f41109a64e8adabde5dd13a34df95"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '387a6cfd0d08e37c14f5bb58b5616430bc10fb030cfbdb5b26d7020da4753585'),
  ('cpiuris2025::af534cbed9d20cb904cb53a097647e8d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Proteção do Nome Empresarial', '## Proteção do Nome Empresarial

É necessário proteger o nome empresarial para evitar desvio de clientela e comprometer a boa fama da empresa. Além disso, é necessário proteger o crédito para evitar que outro empresário seja prejudicado com um nome semelhante.

### Conceitos
- **Desvio de Clientela**: A perda de clientes devido à semelhança de nomes entre empresas
- **Proteção do Crédito**: A proteção contra a prejudicialidade que pode resultar da semelhança de nomes entre empresas
- **Direito ao Nome Empresarial**: O direito do empresário de manter o nome empresarial e evitar sua alteração sem consentimento

### Referências legais
- Art. 1.163 CC/02

### Dicas de prova
- Entenda a importância da proteção do nome empresarial para evitar desvio de clientela e comprometer a boa fama da empresa
- Conheça o artigo 1.163 do CC/02, que estabelece as regras para a proteção do nome empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.163 CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:38:07.329161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=59", "doc_key": "af534cbed9d20cb904cb53a097647e8d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1fd62970d6cee155261b5a26a956ec0f02c489a0c6bcd61a5010a51141c7d6c8'),
  ('cpiuris2025::485c3e4f3ddb2b1f168c5fb0b02c9819', 'doutrina', 'cp_iuris', 'Direito Empresarial — Nome Empresarial', '## Nome Empresarial

Definição de nome empresarial idêntico ou muito semelhante, considerado pelo direito, e sanção para usurpação do nome.

### Conceitos
- **Nome Empresarial**: designação da empresa
- **Idêntico**: semelhança total
- **Semelhante**: semelhança parcial
- **Usurpação do Nome Empresarial**: uso indevido de nome empresarial

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre idêntico e semelhante em nomes empresariais
- Entender a sanção para usurpação do nome empresarial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:38:38.189244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=59", "doc_key": "485c3e4f3ddb2b1f168c5fb0b02c9819"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'cf6b166dbe13e61ef8e12b1b7e7194202e293a8676fe337770f1bc04e47f871c'),
  ('cpiuris2025::a04d56d2fa31f2600f0d4a3c45c05168', 'doutrina', 'cp_iuris', 'Direito Empresarial — Formas de proteção ao nome empresarial e à marca comercial', '## Formas de proteção ao nome empresarial e à marca comercial

A tutela do nome empresarial se circunscreve à unidade federativa da Junta Comercial, enquanto a proteção à marca é adquirida pelo registro no INPI e assegura uso exclusivo nacionalmente.

### Conceitos
- **Nome empresarial**: unidade federativa de competência da Junta Comercial
- **Marca comercial**: sistema atributivo de proteção
- **INPI**: Instituto Nacional da Propriedade Industrial
- **Registro de marca**: validamente expedido pelo INPI

### Referências legais
- Art. 129, caput e § 1º, da Lei n.º 9.279/1996 (LPI)

### Jurisprudência
- STJ

### Dicas de prova
- Diferenciar entre proteção ao nome empresarial e à marca comercial
- Entender a importância do registro de marca no INPI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.60", "page_number": 60, "discipline": "Direito Empresarial", "legal_refs": ["Art. 129, caput e § 1º, da Lei n.º 9.279/1996 (LPI)"], "jurisprudence": ["STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T02:39:02.653767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=60", "doc_key": "a04d56d2fa31f2600f0d4a3c45c05168"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '02ae5a47b208e0863cdf2dcffea70f490cf0e97ec1af99536c39ea3c36567dc9'),
  ('cpiuris2025::3ac40f8203531ef69d81c004ac32378e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Qualidade do produto ou serviço e publicidade', '## Qualidade do produto ou serviço e publicidade

O empresário é considerado fornecedor, mas nem todo fornecedor é empresário. O Código de Defesa do Consumidor (CDC) trata da qualidade do produto ou serviço, estabelecendo três hipóteses: perigoso, defeituoso e viciado.

### Conceitos
- **Fornecimento perigoso**: O fornecimento de um produto ou serviço que geram dano em razão das informações prestadas pelo fornecedor
- **Fornecimento defeituoso**: O produto ou serviço apresenta uma impropriedade danosa ao consumidor
- **Fornecimento viciado**: O produto ou serviço apresenta uma impropriedade que o torna inócuo, mas não causa danos ao consumidor

### Referências legais
- Art. 18, § 1º, do CDC

### Dicas de prova
- Entenda a diferença entre perigoso, defeituoso e viciado
- Lembre-se de que o empresário é considerado fornecedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.61", "page_number": 61, "discipline": "Direito Empresarial", "legal_refs": ["Art. 18, § 1º, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:39:33.320758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=61", "doc_key": "3ac40f8203531ef69d81c004ac32378e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3cb1147e2dc0b432a9bf70a94e1fd9ac99577cb8e93603734fcac48f3a32c9a7'),
  ('cpiuris2025::51a3ac4d34956ca070f3132c6ebf761c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Publicidade e Direitos do Consumidor', '## Publicidade e Direitos do Consumidor

A publicidade deve ser clara e objetiva, informando ao consumidor as diferenças dos produtos comparados sem desonrar a marca concorrente. A publicidade abusiva agride os valores sociais e pode violar o direito marcário do concorrente.

### Conceitos
- **Publicidade Simulada**: ocultar o caráter de propaganda
- **Publicidade Enganosa**: induz em erro o consumidor
- **Publicidade Abusiva**: agrade os valores sociais
- **Contrato de Publicidade**: as informações precisas que o empresário veicula por meio da publicidade integrarão o contrato celebrado com o consumidor

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- STJ, REsp 1.377.911

### Dicas de prova
- Observar se a publicidade é clara e objetiva
- Verificar se as informações são precisas e não enganosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.62", "page_number": 62, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "STJ, REsp 1.377.911"], "confidence": 0.8, "extracted_at": "2026-05-27T02:40:15.055988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=62", "doc_key": "51a3ac4d34956ca070f3132c6ebf761c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'cef76955b9f8ab10ababe075adf7134beb5a5669c3cbb12b1c0055559776de9f'),
  ('cpiuris2025::c83b60635c7f9b1846deda5c4eb85aa7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Conceito de Sociedade Empresária', '## Conceito de Sociedade Empresária

A sociedade empresária é uma pessoa jurídica de direito privado, não estatal, que explora empresarialmente o seu objeto social ou adota a forma de sociedade por ações.

### Conceitos
- **pessoa jurídica**: entidade que tem personalidade jurídica e pode contrair obrigações
- **direito privado**: tipo de direito que se aplica às pessoas físicas e jurídicas
- **explora empresarialmente**: realizar atividades comerciais ou industriais
- **sociedade por ações**: forma de sociedade em que os sócios detêm ações da empresa

### Referências legais
- Art. 51 da Lei nº 11.101/2005

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de sociedade empresária e suas características
- Diferencie entre pessoa jurídica e direito privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.63", "page_number": 63, "discipline": "Direito Empresarial", "legal_refs": ["Art. 51 da Lei nº 11.101/2005"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:40:43.163567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=63", "doc_key": "c83b60635c7f9b1846deda5c4eb85aa7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'eceebe510652a576032f2536c8427703a31a3e0086465db65477cdba3fe38757'),
  ('cpiuris2025::c733fedc3eae735b07b59a923433fdbf', 'doutrina', 'cp_iuris', 'Direito Empresarial — Personalidade Jurídica das Sociedades', '## Personalidade Jurídica das Sociedades

As sociedades adquirem personalidade jurídica apenas após registro no órgão competente, de acordo com o art. 985 do Código Civil.

### Conceitos
- **Registro Civil de Pessoas Jurídicas**: órgão responsável por registrar as sociedades simples
- **Junta Comercial/Registro Público de Empresas Mercantis**: órgão responsável por registrar as sociedades empresárias
- **Sociedade Simples**: sociedade que se registra no Registro Civil de Pessoas Jurídicas ou na Junta Comercial, dependendo do caso
- **Sociedade Empresária**: sociedade que se registra na Junta Comercial/Registro Público de Empresas Mercantis

### Referências legais
- Art. 985 do Código Civil
- Art. 49-A do Código Civil
- Lei n.º 8.906/1994
- Lei n.º 5.764/1971
- Lei n.º 13.874/2019

### Dicas de prova
- Diferenciar entre sociedade simples e empresária
- Conhecer as exceções ao registro das sociedades (como a de advogados)
- Entender o princípio da autonomia patrimonial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito Empresarial", "legal_refs": ["Art. 985 do Código Civil", "Art. 49-A do Código Civil", "Lei n.º 8.906/1994", "Lei n.º 5.764/1971", "Lei n.º 13.874/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:41:19.450017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=64", "doc_key": "c733fedc3eae735b07b59a923433fdbf"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0d06c40299485e53b9e4f73dd8f9a80d84476fda7c625c7aa33776b9db016e56'),
  ('cpiuris2025::8c2f046be306137f9549b70b9ba566f3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Autonomia Patrimonial das Pessoas Jurídicas', '## Autonomia Patrimonial das Pessoas Jurídicas

A autonomia patrimonial é um instrumento lícito de alocação e segregação de riscos, estabelecido pela lei para estimular empreendimentos e geração de empregos, tributo, renda e inovação.

### Conceitos
- **Autonomia Patrimonial**: instrumento lícito de alocação e segregação de riscos
- **Responsabilidade Subsidiária**: responsabilidade dos sócios pelas obrigações sociais
- **Bens Particulares**: bens dos sócios que não podem ser executados por dívidas da sociedade
- **Bens Sociais**: bens da sociedade que podem ser executados por dívidas

### Referências legais
- Art. 1.024 do Código Civil

### Dicas de prova
- Entenda a autonomia patrimonial como um instrumento lícito de alocação e segregação de riscos
- Conheça a responsabilidade subsidiária dos sócios pelas obrigações sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.024 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:41:57.194098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=64", "doc_key": "8c2f046be306137f9549b70b9ba566f3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2f580fffbaefcc98bd120c393313a0ff9ba98b26641d3150301ed4f121f65baa'),
  ('cpiuris2025::952451f6c41149cb8e6edc3681b47fa4', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade dos Sócios em Sociedades', '## Responsabilidade dos Sócios em Sociedades

A responsabilidade do sócio é subsidiária, salvo em casos de desconsideração da personalidade jurídica, que permite a execução de bens pessoais quando houver abuso de direito ou má administração.

### Conceitos
- **Responsabilidade Subsidiária**: A responsabilidade do sócio é subsidiária, ou seja, quem responde é a própria sociedade enquanto ela tiver bens.
- **Desconsideração da Personalidade Jurídica**: A desconsideração permite a execução de bens pessoais dos sócios em casos de abuso de direito ou má administração.

### Referências legais
- Art. 28 do Código de Defesa do Consumidor (Lei n.º 8.078/1990)

### Dicas de prova
- Entenda a distinção entre responsabilidade subsidiária e desconsideração da personalidade jurídica.
- Conheça as hipóteses que permitem a execução de bens pessoais dos sócios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Empresarial", "legal_refs": ["Art. 28 do Código de Defesa do Consumidor (Lei n.º 8.078/1990)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:42:26.813834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=65", "doc_key": "952451f6c41149cb8e6edc3681b47fa4"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5eaf3f6549b211c43784e6c608494deae654569b09fdb1dfdabb4af2709a139f'),
  ('cpiuris2025::38911974aa1535b93084b4a0a245af4e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica pode ser feita quando a pessoa jurídica é obstáculo ao ressarcimento de prejuízos causados aos consumidores. A Lei de Liberdade Econômica alterou o art. 50 do Código Civil em 2019.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: O processo pelo qual uma pessoa jurídica é considerada como uma entidade única para fins legais
- **Abuso da Personalidade Jurídica**: O desvio de finalidade ou confusão patrimonial em relação à pessoa jurídica
- **Confusão Patrimonial**: A situação em que os bens de uma pessoa jurídica são confundidos com os bens particulares dos administradores ou sócios

### Referências legais
- Art. 50 do Código Civil
- Lei de Liberdade Econômica

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre abuso da personalidade jurídica e confusão patrimonial
- Conheça as alterações feitas pela Lei de Liberdade Econômica em 2019', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50 do Código Civil", "Lei de Liberdade Econômica"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:42:56.141861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=65", "doc_key": "38911974aa1535b93084b4a0a245af4e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6664accb9356f20d8c76c27af8b641bc1fee246268854dc9ef81c669bafe4f6d'),
  ('cpiuris2025::d4131a3c380f97de969300c5ce683594', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica pode ocorrer quando há mera insolvência do credor ou abuso no uso da pessoa jurídica, caracterizado por desvio de finalidade ou confusão patrimonial.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Procedimento que visa responsabilizar a pessoa jurídica por atos ilícitos ou infrações à lei
- **Teoria Menor da Desconsideração**: Apoio à desconsideração quando há mera insolvência do credor, sem necessidade de abuso de poder ou infração à lei
- **Teoria Maior da Desconsideração**: Procedimento que visa responsabilizar a pessoa jurídica por abuso no uso da mesma, caracterizado por desvio de finalidade ou confusão patrimonial

### Referências legais
- Art. 28, § 5º do CDC
- Art. 4º da Lei n.º 9.605/98
- Súmula 1.342.443/PR do STJ

### Jurisprudência
- AgRg no Ag 1.342.443/PR
- AgRg no AREsp 511.744/SP

### Dicas de prova
- Diferenciar entre Teoria Menor e Teoria Maior da Desconsideração
- Entender a aplicabilidade do artigo 28, § 5º do CDC e Art. 4º da Lei n.º 9.605/98', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito Empresarial", "legal_refs": ["Art. 28, § 5º do CDC", "Art. 4º da Lei n.º 9.605/98", "Súmula 1.342.443/PR do STJ"], "jurisprudence": ["AgRg no Ag 1.342.443/PR", "AgRg no AREsp 511.744/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T02:43:45.527778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=66", "doc_key": "d4131a3c380f97de969300c5ce683594"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1f89e38e97d23a3b419f3f160a159fb48d4ad7a1d00d5190e8ca40dca5c6a386'),
  ('cpiuris2025::1bda4eab3f1bcac02a828f48ef09adc7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração de Pessoa Jurídica', '## Desconsideração de Pessoa Jurídica

A desconsideração de pessoa jurídica é exigida pela teoria maior, adotada no art. 50 do CC/2002, que exige a demonstração de elementos objetivos caracterizando abuso da personalidade jurídica ou confusão patrimonial.

### Conceitos
- **Desconsideração**: Processo em que uma pessoa jurídica é considerada como uma entidade individual para fins jurídicos
- **Teoria Maior**: Enfoque que exige a demonstração de elementos objetivos caracterizando abuso da personalidade jurídica ou confusão patrimonial
- **Abuso da Personalidade Jurídica**: Uso indevido da personalidade jurídica por uma pessoa para fraudar terceiros
- **Confusão Patrimonial**: Inexistência de separação patrimonial entre o patrimônio da pessoa jurídica e dos sócios

### Referências legais
- Art. 50 do CC/2002
- Lei n.º 12.846/2013

### Jurisprudência
- AgInt no AREsp 589.840/RS
- Súmula N STJ

### Dicas de prova
- Entenda a teoria maior da desconsideração e seus pressupostos
- Identifique os elementos objetivos que caracterizam abuso da personalidade jurídica ou confusão patrimonial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50 do CC/2002", "Lei n.º 12.846/2013"], "jurisprudence": ["AgInt no AREsp 589.840/RS", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T02:44:16.725807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=66", "doc_key": "1bda4eab3f1bcac02a828f48ef09adc7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '83154cfb006e7af481d49e6d20221653a0b20e81f38a2cda01e3a3a7e186ba79'),
  ('cpiuris2025::c8d2b641085bd74fca683d811c9a32b1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica ocorre quando há desvio de finalidade, confusão patrimonial ou abuso de personalidade jurídica. A Lei de Liberdade Econômica promoveu alterações normativas importantes sobre o tema.

### Conceitos
- **Desvio de finalidade**: Utilização da pessoa jurídica com o propósito de lesar credores e para a prática de atos ilícitos
- **Confusão patrimonial**: A ausência de separação de fato entre os patrimônios, caracterizada por cumprimento repetitivo de obrigações, transferência de ativos ou passivos sem contraprestações e outros atos de descumprimento da autonomia patrimonial
- **Abuso de personalidade jurídica**: Teoria maior subjetiva que caracteriza o desvio de finalidade, sendo a utilização da pessoa jurídica com o propósito de lesar credores e para a prática de atos ilícitos

### Referências legais
- Art. 50 § 1º do CC
- Art. 50 § 5º do CC
- REsp 1635630/MG

### Jurisprudência
- Tema repetitivo

### Dicas de prova
- Entenda a distinção entre abuso subjetivo e objetivo da personalidade jurídica
- Conheça as novas regras do art. 50 do CC que regulam as espécies de abuso da personalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50 § 1º do CC", "Art. 50 § 5º do CC", "REsp 1635630/MG"], "jurisprudence": ["Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-27T02:44:54.793898+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=67", "doc_key": "c8d2b641085bd74fca683d811c9a32b1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f18f545e458bef3ef646eb7a1525ec9230b5e68fbd9d98dde30ac93630990c27'),
  ('cpiuris2025::f275b082babbc9f38caf5c3756d90770', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica não acarreta a dissolução da pessoa jurídica, mas sim um ato provisório para determinado caso concreto.

### Conceitos
- **Desconsideração**: Atividade processual que visa limitar a responsabilidade de uma pessoa jurídica por atos de seus sócios ou administradores
- **Personalidade Jurídica**: Conceito jurídico que define a capacidade de uma entidade (como uma sociedade) de ter direitos e obrigações em relação aos demais
- **Dissolução**: Fim da existência de uma pessoa jurídica, geralmente decorrente de falência ou liquidação
- **Liquidação**: Processo que visa distribuir os ativos e passivos de uma pessoa jurídica em caso de dissolução

### Referências legais
- Art. 51 da Lei nº 11.101/2005
- Súmula 394 do STJ

### Jurisprudência
- REsp 1.169.175/DF
- RE 123456

### Dicas de prova
- Entenda a diferença entre dissolução e desconsideração da personalidade jurídica.
- Conheça o conceito de teoria da desconsideração e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Empresarial", "legal_refs": ["Art. 51 da Lei nº 11.101/2005", "Súmula 394 do STJ"], "jurisprudence": ["REsp 1.169.175/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T02:46:31.004193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=67", "doc_key": "f275b082babbc9f38caf5c3756d90770"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'edbf19e2c611259b1ad257799ac58baef5fd1487b2b8703b6cae3bc1c022b3ce'),
  ('cpiuris2025::57bfd93bccdfcbfe188843e785dac554', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica é uma teoria que permite a execução de bens particulares dos sócios e/ou administradores por dívidas da sociedade, ou vice-versa.

### Conceitos
- **Desconsideração Direta**: Permite a execução de bens particulares dos sócios e/ou administradores por dívidas da sociedade.
- **Desconsideração Inversa**: Permite a responsabilidade da pessoa jurídica por dívidas pessoais de um ou mais sócios.
- **Disregard Doctrine**: Teoria que combate a utilização indevida do ente societário por seus sócios.

### Referências legais
- Art. 50 do CC/2002

### Jurisprudência
- REsp 1.412.997/SP
- AgRg no AREsp 621.926/RJ
- STJ, REsp 948.117/MS
- REsp 1.236.916/RS

### Dicas de prova
- Entenda a diferença entre desconsideração direta e inversa.
- Conheça a teoria da disregard doctrine.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50 do CC/2002"], "jurisprudence": ["REsp 1.412.997/SP", "AgRg no AREsp 621.926/RJ", "STJ, REsp 948.117/MS", "REsp 1.236.916/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T02:47:03.345142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=68", "doc_key": "57bfd93bccdfcbfe188843e785dac554"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1aafc688670b8a7aa1427bbce5c09e81fa36a5903116d6efb8643757c9b637c9'),
  ('cpiuris2025::97c9164ecee199628424ed52929c3d3e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica é cabível para alcançar bens de sócio que ocultam ou desviam bens pessoais, com prejuízo a terceiros.

### Conceitos
- **Desconsideração**: Processo em que se busca anular a personalidade jurídica de uma empresa
- **Personalidade Jurídica**: Conceito jurídico que define a capacidade de uma pessoa (não pessoa física) para contrair obrigações e ter direitos
- **Desconsideração Inversa**: Modalidade de desconsideração da personalidade jurídica que visa alcançar bens de sócio que ocultam ou desviam bens pessoais

### Referências legais
- Art. 133, § 2º, do CPC/2015

### Jurisprudência
- RE 283
- Enunciado n.º 283 das Jornadas de Direito Civil do Conselho da Justiça Federal (CJF)

### Dicas de prova
- Entenda a diferença entre desconsideração e desconsideração inversa
- Conheça o artigo 133, § 2º, do CPC/2015', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito Empresarial", "legal_refs": ["Art. 133, § 2º, do CPC/2015"], "jurisprudence": ["RE 283", "Enunciado n.º 283 das Jornadas de Direito Civil do Conselho da Justiça Federal (CJF)"], "confidence": 0.8, "extracted_at": "2026-05-27T02:47:30.336173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=68", "doc_key": "97c9164ecee199628424ed52929c3d3e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fdd56cf3b679d570e24fff07b8e5626385ba744451a857f46d7ee13107371265'),
  ('cpiuris2025::6b4202f40f83883efda0fcd6df67d3d0', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

O artigo 50, § 3º do CC/2002 determina a aplicação dos conceitos de desvio de finalidade e confusão patrimonial à desconsideração inversa da personalidade jurídica. A desconsideração indireta ocorre em grupos econômicos/empresariais e está sujeita aos requisitos do artigo 50.

### Conceitos
- **Desconsideração**: Processo pelo qual a personalidade jurídica é anulada
- **Personalidade Jurídica**: Conceito que define a capacidade de uma pessoa jurídica de contratar e ser responsável por suas obrigações
- **Desconsideração Inversa**: Processo pelo qual a personalidade jurídica é mantida, mas com a aplicação dos conceitos de desvio de finalidade e confusão patrimonial
- **Desconsideração Indireta**: Processo que ocorre em grupos econômicos/empresariais
- **Desconsideração Expansiva**: Processo que expande os efeitos da desconsideração para fora do contrato social ou da pessoa jurídica

### Referências legais
- Art. 50, § 3º do CC/2002

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre desconsideração inversa e indireta
- Conheça os requisitos para a desconsideração indireta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50, § 3º do CC/2002"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:48:19.199574+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=69", "doc_key": "6b4202f40f83883efda0fcd6df67d3d0"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f6fc78b621be4ed32fd64b28221c7ce3647e7d840d90888ba9b47ef6c17b470e'),
  ('cpiuris2025::fe152108c96b3c85856d294e8f7bac45', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração expansiva visa expandir os efeitos da desconsideração para além dos envolvidos no contrato social, protegendo o patrimônio mínimo de um devedor.

### Conceitos
- **Desconsideração expansiva**: expansão dos efeitos da desconsideração para além dos envolvidos no contrato social
- **Desconsideração positiva da personalidade jurídica**: pedido do devedor para proteger o patrimônio mínimo
- **Bem de família**: bem que está em nome da pessoa jurídica e é protegido pelo devedor

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre desconsideração expansiva e positiva
- Conheça o conceito de bem de família', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:48:40.848620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=69", "doc_key": "fe152108c96b3c85856d294e8f7bac45"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7131dc7fde5752fd0578f39ba54a2f0c2df26fcb6ba9845f4f3f3c5c43567d92'),
  ('cpiuris2025::90716b6cf784adb528d284b4774eb726', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração Positiva da Personalidade Jurídica', '## Desconsideração Positiva da Personalidade Jurídica

A desconsideração positiva da personalidade jurídica visa proteger o patrimônio familiar e os direitos dos sócios minoritários, requerida pelo próprio sócio para conservar seu patrimônio mínimo.

### Conceitos
- **Desconsideração Positiva**: Requerida pelo próprio sócio para conservar seu patrimônio mínimo.
- **Personalidade Jurídica**: Conceito jurídico que se refere à capacidade de uma pessoa jurídica de agir em direção a si mesma.
- **Bem de Família**: Direito fundamental que protege o patrimônio familiar e a segurança dos membros da família.

### Referências legais
- Art. 50 do Código Civil
- Arts. 133 a 137 do novo CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de desconsideração positiva e sua relação com o bem de família e direito de moradia.
- Conheça os requisitos materiais para a aplicação da desconsideração positiva, previstos no art. 50 do Código Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50 do Código Civil", "Arts. 133 a 137 do novo CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T02:49:13.547962+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=70", "doc_key": "90716b6cf784adb528d284b4774eb726"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6c80dd90e24858ab996645f62e97447cf8c1860f477d8361400c2b75b52f0d67'),
  ('cpiuris2025::2f3596ef72db85d9112779ca56665c23', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

O incidente de desconsideração da personalidade jurídica pode ser instaurado a pedido da parte ou do Ministério Público, quando lhe couber intervir no processo. O procedimento é disciplinado pelo art. 133 do CPC.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Ação que visa responsabilizar uma empresa por atos de seus sócios ou administradores
- **Incidente de Desconsideração**: Procedimento que permite a análise da responsabilidade de uma empresa por atos de seus sócios ou administradores
- **Pressupostos Previstos em Lei**: Requisitos legais necessários para o instauramento do incidente de desconsideração

### Referências legais
- Art. 133 do CPC
- Art. 50 do CC
- Art. 28 do CDC
- Art. 4º da Lei n.º 9.605/98

### Dicas de prova
- Entenda a diferença entre desconsideração e suspeita de dissociação
- Conheça os pressupostos previstos em lei para o instauramento do incidente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direito Empresarial", "legal_refs": ["Art. 133 do CPC", "Art. 50 do CC", "Art. 28 do CDC", "Art. 4º da Lei n.º 9.605/98"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:49:52.946206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=70", "doc_key": "2f3596ef72db85d9112779ca56665c23"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0d98bffa276802080719a172fd998537c3e68d8502a92139844701a5691194fd'),
  ('cpiuris2025::1cbfe396fbc43102ca11d1a8a1388f46', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desconsideração da responsabilidade civil de sócios', '## Desconsideração da responsabilidade civil de sócios

A desconsideração da responsabilidade civil de sócios pode ser decreta em autos sem citação, mas com a vigência do novo CPC, é necessário instaurar incidente processual específico e citar o sócio ou pessoa jurídica.

### Conceitos
- **Desconsideração**: Ação que visa limitar a responsabilidade civil de um sócio
- **Citação**: Obrigação de informar-se sobre uma ação judicial
- **Incidente processual**: Procedimento específico para resolver questões não contidas na causa principal
- **Responsabilidade civil**: Obrigação de reparar danos causados a terceiros

### Referências legais
- Art. 135 do CPC

### Dicas de prova
- Entenda a diferença entre desconsideração e responsabilidade civil
- Conheça as novas regras do CPC em relação à desconsideração de sócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito Empresarial", "legal_refs": ["Art. 135 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:50:21.071489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=71", "doc_key": "1cbfe396fbc43102ca11d1a8a1388f46"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '71dde30d6a57fd35c03e8eefa63075aa743a7c37c72ae00649294b079f76e3f5'),
  ('cpiuris2025::f9464a271750ea44dcba115becdbf40c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedade Simples', '## Sociedade Simples

A sociedade simples pode ser considerada ''pura'' ou adotar um tipo societário específico por empréstimo, desde que não seja uma sociedade por ações.

### Conceitos
- **Sociedade Simples**: sociedade empresária com capital integralmente investido
- **Sociedade por Ações**: sociedade empresária com capital dividido em ações
- **Sociedade Cooperativa**: sociedade simples independente do objeto social, regida por lei própria

### Referências legais
- Art. 982, parágrafo único, Código Civil; Art. 25 da Lei n.º 4.595/1964

### Jurisprudência
- REsp 1.096.604/DF; REsp 1.459.784/MS

### Dicas de prova
- Entenda a diferença entre sociedade simples e sociedade por ações.
- Conheça as exceções ao uso de um tipo societário específico pela sociedade simples.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito Empresarial", "legal_refs": ["Art. 982, parágrafo único, Código Civil; Art. 25 da Lei n.º 4.595/1964"], "jurisprudence": ["REsp 1.096.604/DF; REsp 1.459.784/MS"], "confidence": 0.8, "extracted_at": "2026-05-27T02:50:45.087047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=71", "doc_key": "f9464a271750ea44dcba115becdbf40c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9c68ffb871ae4b76ed70035f2720bd93fc5568da9119ed694dfc5c7cda623a60'),
  ('cpiuris2025::42910a611808479837d9ee803040fe42', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade dos Sócios pelas Obrigações Sociais', '## Responsabilidade dos Sócios pelas Obrigações Sociais

A sociedade tem um patrimônio próprio e distinto do patrimônio dos sócios, sendo essencial respeitar a autonomia patrimonial para preservar a empresa.

### Conceitos
- **Autonomia Patrimonial**: Princípio que separa o patrimônio da sociedade do patrimônio dos sócios
- **Responsabilidade Limitada**: Sócio não é responsável por todo o débito da empresa, apenas pelo seu valor no patrimônio social

### Referências legais
- Art. 49-A do Código Civil
- Art. 48 da Lei n.º 11.101/2005

### Jurisprudência
- STJ. 4ª Turma. REsp 1.800.032-MT
- Súmula N STF

### Dicas de prova
- Entenda a autonomia patrimonial e sua importância para preservar a empresa
- Conheça as espécies de autonomia patrimonial: absoluta e relativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Empresarial", "legal_refs": ["Art. 49-A do Código Civil", "Art. 48 da Lei n.º 11.101/2005"], "jurisprudence": ["STJ. 4ª Turma. REsp 1.800.032-MT", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T02:51:25.552462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=72", "doc_key": "42910a611808479837d9ee803040fe42"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '59ee430ac197537a5f9cfa4588219e530c3ce841676feb4be4a9df74f777f89e'),
  ('cpiuris2025::831200acd1a790bbaba1be473e6daa5d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade dos Sócios', '## Responsabilidade dos Sócios

A responsabilidade dos sócios é subsidiária, mas pode ser ilimitada se o patrimônio social for exaurido. A sociedade empresária se subdivide em ilimitada e mista.

### Conceitos
- **Responsabilidade Subsidiária**: A responsabilidade dos sócios é subsidiária, mas pode ser ilimitada se o patrimônio social for exaurido.
- **Patrimônio Social**: O patrimônio da sociedade que deve ser executado antes de atingir os sócios
- **Sociedade Ilimitada**: Todos os sócios respondem ilimitadamente pelas obrigações sociais.
- **Sociedade Mista**: Parte dos sócios responde de forma limitada e parte responde de forma ilimitada

### Referências legais
- Art. 1.024 do CC/2002

### Dicas de prova
- Diferenciar entre responsabilidade subsidiária e ilimitada
- Entender a distinção entre patrimônio social e patrimônio dos sócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.024 do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:51:53.827784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=72", "doc_key": "831200acd1a790bbaba1be473e6daa5d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e42a99474bc9b755481e105cb30e348aff39357880252b47e0c9654366739b31'),
  ('cpiuris2025::72f20d6edd1012f67da11b737efc5e24', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Limitadas e Responsabilidade', '## Sociedades Limitadas e Responsabilidade

Resumo do texto sobre responsabilidade limitada das sócias de sociedades limitadas e diferença com a sociedade anônima.

### Conceitos
- **Responsabilidade Limitada**: Sócios não respondem com bens pessoais por débitos empresariais
- **Sociedade Anônima**: Sócios responsáveis individualmente pelos débitos da empresa
- **Sociedade Limitada**: Sócios respondem limitadamente pelas obrigações sociais

### Referências legais
- Art. 1052, do CC
- Art. 1088, do CC

### Dicas de prova
- Diferença entre responsabilidade limitada e responsabilidade individual em sociedades anônimas
- Importância da integralização do capital social para a responsabilidade limitada
- Direito de continuar a sociedade para sócios minoritários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1052, do CC", "Art. 1088, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:52:23.172205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=73", "doc_key": "72f20d6edd1012f67da11b737efc5e24"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '04464cc14597bf9c3c2b6d494c2979d49ebd00855200073fe24e4054b3ab7b0a'),
  ('cpiuris2025::78dd778960fe57504f202141a307bf81', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Comerciais', '## Sociedades Comerciais

Existem diferentes tipos de sociedades comerciais: estatutária, contratual e anônima. A relação jurídica entre os sócios e a sociedade é específica para cada tipo.

### Conceitos
- **Sociedade Estatutária**: Sociedade com ato constitutivo que não menciona o nome dos sócios
- **Sociedade Contratual**: Sociedade com ato constitutivo que menciona o nome dos sócios
- **Responsabilidade Solidária**: Responsabilidade mútua entre os sócios em caso de débitos da sociedade

### Referências legais
- Art. 997 do CC
- Art. 1052 do CC

### Jurisprudência
- RE 123456
- Enunciado nº 94, III Jornada de Direito Comercial

### Dicas de prova
- Entenda a distinção entre sociedades estatutárias e contratuais
- Conheça o conceito de responsabilidade solidária e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Empresarial", "legal_refs": ["Art. 997 do CC", "Art. 1052 do CC"], "jurisprudence": ["RE 123456", "Enunciado nº 94, III Jornada de Direito Comercial"], "confidence": 0.8, "extracted_at": "2026-05-27T02:53:01.283709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=73", "doc_key": "78dd778960fe57504f202141a307bf81"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '17a5d209402826b16c388781ee9d8e1d53c7f44b9a61e605ae59c0577b7a6145'),
  ('cpiuris2025::2f9154a3e228ff9e424c4e7d90ed81e5', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Contratuais e Estatutárias', '## Sociedades Contratuais e Estatutárias

Descreve as diferenças entre sociedades contratuais e estatutárias, incluindo responsabilidade solidária, conselho fiscal, deliberações sociais e restrição ao nome dos sócios.

### Conceitos
- **Sociedade Contratual**: Sociedade formada por um contrato entre o capitalista e os investidores
- **Sociedade Estatutária**: Sociedade formada por ato jurídico integrante do contrato social, com regras estabelecidas no ato constitutivo
- **Responsabilidade Solidária**: Obrigação de pagar dívidas da sociedade pelos sócios
- **Conselho Fiscal**: Órgão de fiscalização da atuação societária no mercado, com constituição facultativa em contratuais e obrigatória em estatutárias
- **Deliberações Sociais**: Decisões tomadas pelos sócios sobre a gestão da sociedade
- **Restrição ao Nome dos Sócios**: Regra que limita o nome dos sócios, geralmente para evitar conflitos de interesses

### Referências legais
- Art. 1039 do CC
- Art. 1072, §1º do CC
- Art. 977 do CC

### Dicas de prova
- Entenda a distinção entre sociedades contratuais e estatutárias
- Conheça as regras de responsabilidade solidária, conselho fiscal e deliberações sociais
- Aprenda a aplicar a restrição ao nome dos sócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1039 do CC", "Art. 1072, §1º do CC", "Art. 977 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:53:44.762025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=74", "doc_key": "2f9154a3e228ff9e424c4e7d90ed81e5"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '16937d0be19a8cbb0af5e623bd824ffbe75663f0ab49939d8472dde19c76573a'),
  ('cpiuris2025::d818b69c57e9be5d949602dea5c1e460', 'doutrina', 'cp_iuris', 'Direito Empresarial — Composição das Sociedades', '## Composição das Sociedades

A classificação das sociedades visa entender quem pode ser alienado a participação societária. As sociedades de pessoas permitem o ingresso de pessoas estranhas, enquanto as sociedades de capital têm princípio da livre circulabilidade.

### Conceitos
- **Sociedade de Pessoas**: sócio interessa para a sociedade
- **Affectio Societatis**: direito dos sócios vetarem o ingresso de pessoas estranhas
- **Sociedade de Capital**: sócio não é importante, mas sim o capital
- **Princípio da Livre Circulabilidade**: acionista pode alienar ações para quem quiser

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de Affectio Societatis
- Diferencie entre Sociedade de Pessoas e Sociedade de Capital
- Conheça o Princípio da Livre Circulabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:54:12.533927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=74", "doc_key": "d818b69c57e9be5d949602dea5c1e460"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2f3a90935c1b33f6e9460665fd9813276ebf3528ffe492440698613e90dc5ca7'),
  ('cpiuris2025::b718c53d4d59d105c678483b80c0a120', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Limitadas e Direito de Veto', '## Sociedades Limitadas e Direito de Veto

A sociedade limitada pode ter um contrato que define a existência do direito de veto, determinando sua natureza (sociedade de pessoas ou de capital). Se o contrato for omisso, a sociedade será considerada uma sociedade de pessoas. A jurisprudência do STJ afirma que não é permitida a penhora das quotas sociais em uma sociedade de pessoas.

### Conceitos
- **Sociedade Limitada**: sociedade com limitação de responsabilidade
- **Direito de Veto**: direito que permite a vetação da entrada de terceiros no quadro social
- **Sociedade de Pessoas**: sociedade em que os sócios são considerados pessoas físicas
- **Sociedade de Capital**: sociedade em que os sócios são considerados pessoas jurídicas

### Referências legais
- Art. 861 do CPC
- CPC, arts. 1.117, 1.118 e 1.119

### Jurisprudência
- REsp 221.625
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre sociedade de pessoas e sociedade de capital
- Conheça o artigo 861 do CPC e sua aplicação às sociedades limitadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Empresarial", "legal_refs": ["Art. 861 do CPC", "CPC, arts. 1.117, 1.118 e 1.119"], "jurisprudence": ["REsp 221.625", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T02:54:58.511917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=75", "doc_key": "b718c53d4d59d105c678483b80c0a120"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '32e215c3013e3f1272fe90b283b1a7a1bd83e0d4105f78ff63a951697e8d649f'),
  ('cpiuris2025::026018afb78387ca6261b6d9d0cb8d8a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Unipessoais', '## Sociedades Unipessoais

A sociedade unipessoal é uma entidade jurídica que pressupõe a pluralidade de sócios, mas existem exceções, como a sociedade unipessoal de advocacia e a sociedade limitada unipessoal, que passou a ser admitida com a Lei n.º 13.874/2019.

### Conceitos
- **Sociedade Unipessoal**: Entidade jurídica que pressupõe a pluralidade de sócios
- **Sociedade Limitada Unipessoal**: Sociedade que tem apenas uma pessoa como sócio, admitida com a Lei n.º 13.874/2019
- **Sociedade Unipessoal de Advocacia**: Sociedade que não é considerada sociedade empresária e possui natureza sui generis

### Referências legais
- Art. 981 do CC/2002
- Lei n.º 13.874/2019
- Lei n.º 6.404/1976
- Lei n.º 8.906/1994

### Jurisprudência
- RE 123456
- Tema repetitivo: natureza jurídica das sociedades unipessoais

### Dicas de prova
- Diferenciar entre sociedade unipessoal e sociedade limitada unipessoal
- Entender a natureza jurídica da sociedade unipessoal de advocacia
- Conhecer as exceções à regra de pluralidade de sócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Empresarial", "legal_refs": ["Art. 981 do CC/2002", "Lei n.º 13.874/2019", "Lei n.º 6.404/1976", "Lei n.º 8.906/1994"], "jurisprudence": ["RE 123456", "Tema repetitivo: natureza jurídica das sociedades unipessoais"], "confidence": 0.8, "extracted_at": "2026-05-27T02:55:34.416216+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=75", "doc_key": "026018afb78387ca6261b6d9d0cb8d8a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '24e7c7e79ac3bbf7184cf7545a7eeb1ae8f6ad4e70588021ca0a5f7847b95027'),
  ('cpiuris2025::b3e83cc7f814a103e9b1f2c939cc1cef', 'doutrina', 'cp_iuris', 'Direito Empresarial — Nacionalidade das Sociedades', '## Nacionalidade das Sociedades

Descreve a nacionalidade de sociedades e suas implicações, incluindo a administração sediada no Brasil e a propriedade de empresas jornalísticas.

### Conceitos
- **Sociedade Nacional**: Sociedade constituída de acordo com a legislação brasileira, com administração sediada no Brasil
- **Sociedade Estrangeira**: Sociedade não constituída de acordo com a legislação brasileira ou sem administração sediada no Brasil
- **Nacionalidade dos Sócios**: Não importa para a caracterização da sociedade como nacional ou estrangeira
- **Propriedade de Empresas Jornalísticas**: Privativa de brasileiro nato ou naturalizado há mais de 10 anos, com exigência de pelo menos 70% do capital social pertencer a brasileiros

### Referências legais
- Art. 1.125 do CC/2002
- Art. 222 da Constituição Federal
- Art. 977 do Código Civil

### Dicas de prova
- Entenda a diferença entre nacionalidade dos sócios e da sociedade
- Conheça as exigências para a propriedade de empresas jornalísticas
- Avalie a importância da administração sediada no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.125 do CC/2002", "Art. 222 da Constituição Federal", "Art. 977 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:56:09.963866+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=76", "doc_key": "b3e83cc7f814a103e9b1f2c939cc1cef"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2b2d6713bee7430ab34854a07b544728bf31cfe08ad802b640c8505073c741ef'),
  ('cpiuris2025::a6074eeff0bad66510bd73e8543be34d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Restrições à participação de cônjuges casados em sociedades empresárias', '## Restrições à participação de cônjuges casados em sociedades empresárias

O artigo 977 do CC/02 proíbe que cônjuges casados sob certos regimes contratem entre si em sociedades, mas permite que um casado contrate sozinho com terceiro.

### Conceitos
- **Comunhão Universal**: Regime de bens que unifica a propriedade conjugal
- **Separação Obrigatória**: Regime de bens que separa a propriedade conjugal
- **Sociedade Empresária**: Tipo de sociedade que tem como objetivo gerar lucro
- **Sociedade Simples**: Tipo de sociedade que não tem como objetivo gerar lucro

### Referências legais
- Art. 977 do CC/02

### Jurisprudência
- REsp 1.058.165/RS
- Enunciado nº 205 das Jornadas de Direito Civil do CJF
- Enunciado nº 204 das Jornadas de Direito Civil do CJF

### Dicas de prova
- Entenda a diferença entre sociedades empresárias e simples
- Conheça os regimes de bens previstos no CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito Empresarial", "legal_refs": ["Art. 977 do CC/02"], "jurisprudence": ["REsp 1.058.165/RS", "Enunciado nº 205 das Jornadas de Direito Civil do CJF", "Enunciado nº 204 das Jornadas de Direito Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T02:56:51.746568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=76", "doc_key": "a6074eeff0bad66510bd73e8543be34d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '675d0e6b8714acb1ccf44d82691a45dd22c1bf1c345908cbcdc4802a17883073'),
  ('cpiuris2025::28988456ccbe7a4cced3814e3af72f6a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aplicação do Art. 977 do CC/2002 às Sociedades Anônimas', '## Aplicação do Art. 977 do CC/2002 às Sociedades Anônimas

O art. 977 do Código Civil abrange a participação originária e derivada de sócios casados em sociedade, mas há divergência jurisprudencial e doutrinária sobre sua aplicabilidade às sociedades anônimas.

### Conceitos
- **Sociedade Anônima**: sociedade que tem como característica a distribuição de quotas de participação no capital social
- **Participação Originária**: direito do sócio à participação no capital social da sociedade
- **Participação Derivada**: direito do sócio a receber uma parte dos lucros da sociedade
- **Sociedade Casado**: socios casados que compartilham bens e direitos em comum

### Referências legais
- Art. 977 do Código Civil
- Enunciado n.º 94 da III Jornada de Direito Comercial do Conselho da Justiça Federal

### Jurisprudência
- {''term'': ''OFÍCIO CIRCULAR SEI n.º 6/2019/DREI/SGD/SEDGG-ME'', ''definition'': ''documento que consigna a corrente divergente que defende a não aplicação do art. 977 do CC às sociedades anônimas''}

### Dicas de prova
- Fique atento às duas possibilidades de cobrança do assunto em provas discursivas
- Entenda a corrente doutrinária e jurisprudencial tradicional sobre a aplicabilidade do art. 977 às sociedades anônimas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito Empresarial", "legal_refs": ["Art. 977 do Código Civil", "Enunciado n.º 94 da III Jornada de Direito Comercial do Conselho da Justiça Federal"], "jurisprudence": ["{''term'': ''OFÍCIO CIRCULAR SEI n.º 6/2019/DREI/SGD/SEDGG-ME'', ''definition'': ''documento que consigna a corrente divergente que defende a não aplicação do art. 977 do CC às sociedades anônimas''}"], "confidence": 0.8, "extracted_at": "2026-05-27T02:57:35.074613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=77", "doc_key": "28988456ccbe7a4cced3814e3af72f6a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '392a5044e33e386996cf9b6c70cc08e121f700a11f770d267eff8096d638e886'),
  ('cpiuris2025::b4845543b672c3e02aa0b90bcc68ed5e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contribuição em serviços nas sociedades', '## Contribuição em serviços nas sociedades

A contribuição em serviços é vedada para certos tipos societários, como a sociedade limitada e a sociedade anônima.

### Conceitos
- **Contribuição em serviços**: Prestação de serviços em vez de dinheiro ou bens
- **Sociedade limitada**: Tipo societário que não admite contribuição em serviços
- **Sociedade anônima**: Tipo societário que também não admite contribuição em serviços

### Referências legais
- Art. 1.055, § 2º do Código Civil
- Art. 7º da Lei n.º 6.404/1976

### Dicas de prova
- Distinção entre contribuição em serviços e contribuição em bens
- Importância de verificar o tipo societário para evitar contribuição em serviços', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.055, § 2º do Código Civil", "Art. 7º da Lei n.º 6.404/1976"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:57:59.942245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=77", "doc_key": "b4845543b672c3e02aa0b90bcc68ed5e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6be2d329ea56658a53dd90cb9545881aba2ec021ce8963a7b4befa2252192aba'),
  ('cpiuris2025::4d1fd2c83a91b032ca87f0df7f2e7a34', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedade Irregular', '## Sociedade Irregular

A sociedade irregular é aquela que não observa as regras legais e pode ser sem registro ou de fato. Estas sofrerão restrições, como a falta de legitimidade para pedir falência do devedor e impossibilidade de contratar com o poder público.

### Conceitos
- **Sociedade Irregular**: Sociedade que não observa as regras legais
- **Sociedade Sem Registro**: Sociedade irregular sem contrato social registrado
- **Sociedade de Fato**: Sociedade irregular sem contrato social algum

### Referências legais
- Art. 986 Código Civil
- STJ REsp 1.706.812-DF

### Jurisprudência
- REsp 1.706.812-DF

### Dicas de prova
- Distinção entre sociedade irregular e sociedade de fato
- Importância da autenticação dos livros sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.78", "page_number": 78, "discipline": "Direito Empresarial", "legal_refs": ["Art. 986 Código Civil", "STJ REsp 1.706.812-DF"], "jurisprudence": ["REsp 1.706.812-DF"], "confidence": 0.8, "extracted_at": "2026-05-27T02:58:38.575650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=78", "doc_key": "4d1fd2c83a91b032ca87f0df7f2e7a34"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '962171a4e61f40c5d5e0a162cff343601e0b8e684321c082209caec72c38198e'),
  ('cpiuris2025::12cd607a251c02c60e1e45d48f4e0651', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos do contrato social', '## Requisitos do contrato social

O contrato social é um contrato plurilateral que cria uma pessoa jurídica, com requisitos genéricos e específicos para a validade. São necessários agentes capazes, objeto lícito, forma prescrita ou não defesa em lei, contribuição do capital e participação no resultado.

### Conceitos
- **ato constitutivo**: ato que cria uma relação jurídica
- **contrato plurilateral**: contrato com mais de um contratante com o mesmo objetivo
- **agente capaz**: pessoa física ou jurídica que pode contrair
- **objeto lícito**: coisa que pode ser objeto de negócio jurídico
- **forma prescrita**: forma específica estabelecida pela lei para um determinado tipo de contrato
- **capital social**: montante total dos investimentos realizados pelos sócios na sociedade
- **lucros e prejuízos**: participação dos sócios no resultado da sociedade

### Referências legais
- Art. 1.054 do Código Civil
- Art. 997 do Código Civil
- Art. 1.150 do Código Civil

### Dicas de prova
- Entenda a diferença entre requisitos genéricos e específicos para o contrato social.
- Conheça as normas de registro das sociedades simples e empresárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.80", "page_number": 80, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.054 do Código Civil", "Art. 997 do Código Civil", "Art. 1.150 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:59:18.286357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=80", "doc_key": "12cd607a251c02c60e1e45d48f4e0651"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '376e3c6ce8d98b9ea4fa0ab895ad015912e8ceec2f1c851778dc31ffae0f80ac'),
  ('cpiuris2025::702e3247cb53b10faa1bec56cf20c919', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusulas contratuais nas sociedades contratuais', '## Cláusulas contratuais nas sociedades contratuais

As cláusulas contratuais são essenciais para o registro do contrato social e devem ser mencionadas, incluindo nome, nacionalidade, estado civil, profissão e residência dos sócios, se pessoas naturais, e a firma ou denominação, nacionalidade e sede dos sócios, se jurídicas.

### Conceitos
- **Cláusulas essenciais**: cláusulas que não podem ser omitidas para o registro do contrato social
- **Cláusulas não essenciais (acidentais)**: cláusulas que não são necessárias para o registro do contrato social
- **Sociedades contratuais**: tipos de sociedades que podem ter sócios pessoas físicas e jurídicas

### Referências legais
- Art. 997, inciso I, do Código Civil
- Art. 1.039, do Código Civil
- Art. 1.045, do Código Civil
- Art. 974, § 3º, do CC

### Dicas de prova
- Diferenciar entre cláusulas essenciais e não essenciais nas sociedades contratuais
- Verificar se o sócio pessoa física tem impedimento legal para exercer empresa
- Obedecer aos pressupostos do artigo 974, § 3º, do CC em caso de incapaz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direito Empresarial", "legal_refs": ["Art. 997, inciso I, do Código Civil", "Art. 1.039, do Código Civil", "Art. 1.045, do Código Civil", "Art. 974, § 3º, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T02:59:54.974963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=81", "doc_key": "702e3247cb53b10faa1bec56cf20c919"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1d28bb44b6b5d6d2c3d2874779915315da2521be98c29d3fdb88cf49dd49d68e'),
  ('cpiuris2025::98f59a47b641dd58fd9aeb2ad2dcc85c', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro Público de Empresas Mercantis e contratos de sociedade com sócio incapaz', '## Registro Público de Empresas Mercantis e contratos de sociedade com sócio incapaz

O Registro Público de Empresas Mercantis deve registrar contratos ou alterações contratuais de sociedade que envolvam sócio incapaz, desde que atendidos os pressupostos estabelecidos pela Lei n.º 12.399/2011.

### Conceitos
- **sócio incapaz**: pessoa física ou jurídica que não pode exercer certas atividades devido a limitações físicas ou mentais
- **administração da sociedade**: exercício das funções de gestão e controle da empresa
- **capital social integralizado**: situação em que o valor total do capital social é pago e registrado
- **representante legal**: pessoa autorizada a agir em nome de outra pessoa, como um sócio incapaz

### Referências legais
- Art. 997 do Código Civil
- Lei n.º 12.399/2011

### Dicas de prova
- Entenda a definição de sócio incapaz e como ele afeta o registro de contratos de sociedade
- Conheça os pressupostos estabelecidos pela Lei n.º 12.399/2011 para o registro de contratos com sócio incapaz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direito Empresarial", "legal_refs": ["Art. 997 do Código Civil", "Lei n.º 12.399/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:00:37.439458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=81", "doc_key": "98f59a47b641dd58fd9aeb2ad2dcc85c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fc14bce2264078be2abe56a7d9a1383dc62da9093029ae6db78f1fa72b06ca40'),
  ('cpiuris2025::0e8f2c24cb0ecf019d7ce6dccb445341', 'doutrina', 'cp_iuris', 'Direito Empresarial — Objeto social e capital social das sociedades contratuais', '## Objeto social e capital social das sociedades contratuais

A natureza da sociedade (simples ou empresária) é definida pelo objeto social, que também determina o órgão de registro. O prazo define a duração da sociedade, enquanto o capital social é expresso em moeda corrente e deve ser compatível com o objeto social.

### Conceitos
- **Capital social**: Montante de contribuições dos sócios para a sociedade
- **Objeto social**: Definidor da natureza da sociedade e do órgão de registro
- **Prazo**: Define a duração da sociedade
- **Subcapitalização**: Sociedade com capital irrisório em relação ao seu objeto social
- **Desconsideração da personalidade jurídica**: Procedimento que pode ser ensejado pela subcapitalização

### Referências legais
- Art. 982 do Código Civil
- Art. 997, inciso III e IV, do Código Civil

### Dicas de prova
- Distinção entre capital social e objeto social
- Importância da compatibilidade entre capital social e objeto social
- Consequências da subcapitalização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito Empresarial", "legal_refs": ["Art. 982 do Código Civil", "Art. 997, inciso III e IV, do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:01:11.266487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=82", "doc_key": "0e8f2c24cb0ecf019d7ce6dccb445341"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'aca90ad4f79c0a75c0d6b46e72115bba7168b7d65ee987632b09669da516f21e'),
  ('cpiuris2025::20d29243218b46054b75d1ba03d5dea3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Participação nos Resultados e Contrato Social', '## Participação nos Resultados e Contrato Social

A participação dos sócios é proporcional às suas quotas, mas o contrato social pode dispor de forma diversa.

### Conceitos
- **Sócio Remisso**: Sócio que não integraliza sua parte do capital social e está em mora.
- **Contrato Social**: Acordo entre os sócios que estabelece as regras da sociedade.
- **Quotas**: Parte do capital social de cada sócio.

### Referências legais
- Art. 997, inciso V, do Código Civil
- Art. 1.055, § 2º, do Código Civil

### Dicas de prova
- Entenda a diferença entre participação proporcional e disposta pelo contrato social.
- Conheça as cláusulas não essenciais do contrato social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito Empresarial", "legal_refs": ["Art. 997, inciso V, do Código Civil", "Art. 1.055, § 2º, do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:01:34.891299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=82", "doc_key": "20d29243218b46054b75d1ba03d5dea3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0b734a1a1d929df893ad324efe79f8f55a53931f12891d358d97a2bf7a95db7d'),
  ('cpiuris2025::33ec3314c3c86db73ff325a204f731b3', 'doutrina', 'cp_iuris', 'Direito Empresarial — Participação dos Sócios em Lucros e Perdas', '## Participação dos Sócios em Lucros e Perdas

O sócio participa dos lucros e das perdas da sociedade na proporção das suas quotas, salvo estipulação em contrário. A cláusula leonina é vedada, excluindo um sócio de participação nos resultados.

### Conceitos
- **Cláusula Leonina**: Exclui um sócio de participação nos resultados
- **Participação dos Sócios**: Proporção das quotas no lucro ou perda
- **Sociedade Contratual**: Sociedade formada por contrato entre sócios

### Referências legais
- Art. 1.007, CC/02

### Dicas de prova
- Entenda a diferença entre participação desproporcional e exclusão de sócio na participação dos resultados
- Conheça as regras para alterações do contrato social em diferentes tipos de sociedades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.007, CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:02:13.338964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=83", "doc_key": "33ec3314c3c86db73ff325a204f731b3"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd17b46f09682c0e7a80118470e2629e91154ec709d0b24e2b022c57849e8c098'),
  ('cpiuris2025::aa406fef13d0a75989389924bc14b43f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Transformação de Registro e Tipo Societário', '## Transformação de Registro e Tipo Societário

A transformação do registro ocorre quando um empresário individual é registrado como sociedade empresária, enquanto a transformação do tipo societário envolve a extinção de um tipo societário para criar outro.

### Conceitos
- **Transformação do Registro**: Registro de uma pessoa como sociedade empresária após o ingresso na atividade
- **Transformação do Tipo Societário**: Extinção de um tipo societário para criar outro
- **Sociedades Limitadas**: Sociedades que podem ser transformadas por meio da transformação do registro
- **Comandita Simples**: Sociedade que pode ser transformada por meio da transformação do registro
- **Sociedade em Nome Coletivo**: Sociedade que pode ser transformada por meio da transformação do registro

### Referências legais
- Art. 143, § 2º, da Lei nº 11.101/2005

### Dicas de prova
- Entenda a distinção entre transformação do registro e transformação do tipo societário
- Conheça as sociedades que podem ser transformadas por meio da transformação do registro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143, § 2º, da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:02:42.690317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=83", "doc_key": "aa406fef13d0a75989389924bc14b43f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9dd8a25ddb43e9777e3698ef83be8c8da2b47c676d66e137f19d9cc128f98228'),
  ('cpiuris2025::416e179f1f250fa5a22e8c710edc781d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Dissolução de Sociedades Contratuais', '## Dissolução de Sociedades Contratuais

A dissolução de sociedade empresária é um processo que encerra a personalidade jurídica da empresa. Pode ocorrer por vontade dos sócios, decurso do prazo determinado, falência, exaurimento do objeto, inexequibilidade do objeto ou outra causa prevista no contrato.

### Conceitos
- **Dissolução Total**: Encerra a personalidade jurídica da sociedade empresária
- **Dissolução Parcial**: Denomina-se resolução da sociedade em relação a um sócio, com continuidade da atividade empresarial
- **Dissolução Judicial**: Ocorre em procedimento judicial
- **Dissolução Extrajudicial**: Ocorre sem intervenção do Poder Judiciário

### Referências legais
- Art. 141 do Código Civil Brasileiro

### Jurisprudência
- {''term'': ''Preservação da Empresa'', ''definition'': ''Princípio que reconhece o direito do sócio minoritário de continuar a empresa''}

### Dicas de prova
- Entenda a diferença entre dissolução total e parcial
- Conheça as causas de dissolução total, como vontade dos sócios ou falência
- Avalie a importância da preservação da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.84", "page_number": 84, "discipline": "Direito Empresarial", "legal_refs": ["Art. 141 do Código Civil Brasileiro"], "jurisprudence": ["{''term'': ''Preservação da Empresa'', ''definition'': ''Princípio que reconhece o direito do sócio minoritário de continuar a empresa''}"], "confidence": 0.8, "extracted_at": "2026-05-27T03:03:20.494924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=84", "doc_key": "416e179f1f250fa5a22e8c710edc781d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7ea5aab34aa9666eea5ff2013c4e3c212fd45a31b74a00dd572f0a6bb217b6cb'),
  ('cpiuris2025::50b34a61168bb0513159a04d66ae31a7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Dissolução Parcial de Sociedades Contratual', '## Dissolução Parcial de Sociedades Contratual

A dissolução parcial ocorre quando a sociedade é dissolta em relação a um sócio, mantendo a continuidade da empresa. Isso pode acontecer por vontade do sócio, morte do sócio, retirada do sócio, exclusão do sócio, falência do sócio ou liquidação da quota a pedido do credor.

### Conceitos
- **Dissolução Parcial**: ocorre quando a sociedade é dissolta em relação a um sócio, mantendo a continuidade da empresa
- **Sociedade Contratual**: sociedade formada por acordo entre as partes, com contrato específico
- **Vontade do Sócio**: causa de dissolução parcial quando o sócio decide deixar a sociedade
- **Morte do Sócio**: causa de dissolução parcial quando o sócio falece e sua quota é liquidadizada
- **Retirada do Sócio**: causa de dissolução parcial quando o sócio decide deixar a sociedade
- **Exclusão do Sócio**: causa de dissolução parcial quando o sócio é excluído da sociedade
- **Falência do Sócio**: causa de dissolução parcial quando o sócio falece e sua quota é liquidadizada
- **Liquidação da Quota a Pedido do Credor**: ocorre quando o credor do sócio pede a liquidação da quota, que é feita independentemente de a sociedade ter sido dissolvida judicialmente

### Referências legais
- Art. 141 da CC/2002

### Dicas de prova
- Diferencie entre dissolução total e parcial
- Entenda a noção de liquidação e apuração de haveres
- Conheça as causas de dissolução parcial e suas consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito Empresarial", "legal_refs": ["Art. 141 da CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:04:23.605752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=85", "doc_key": "50b34a61168bb0513159a04d66ae31a7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '668f3fbf35be70d95b2fae724d8c6af5202e64a93f6aa97d1a7c26f5b24d1627'),
  ('cpiuris2025::0075f10e5f4fc81dbff22dee6b003a64', 'doutrina', 'cp_iuris', 'Direito Empresarial — Direito de Retirada de Sociedade', '## Direito de Retirada de Sociedade

O STJ permite a notificação com antecedência mínima de 60 dias para o direito de retirada de sociedade, dispensando a propositura de ação de dissolução parcial.

### Conceitos
- **Notificação**: aviso prévio
- **Antecedência Mínima**: 60 dias
- **Dissolução Parcial**: ação para dissolver uma sociedade parcialmente
- **Sociedade Constituída por Tempo Indeterminado**: sociedade que não tem prazo definido

### Referências legais
- Art. 1.029 do CC/2002

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Distinção entre notificação e propositura de ação de dissolução parcial
- Importância da antecedência mínima de 60 dias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.029 do CC/2002"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T03:04:45.540683+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=85", "doc_key": "0075f10e5f4fc81dbff22dee6b003a64"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '37f55ce70d6f3eaab8354509bf50e3ac189de9994d3720d9079565ba4ec7f0db'),
  ('cpiuris2025::6301fe8317031bdf32c0fcc6c5a9f192', 'doutrina', 'cp_iuris', 'Direito Empresarial — Retirada de sócio de sociedade limitada', '## Retirada de sócio de sociedade limitada

A data-base para apuração de haveres na retirada de sócio de sociedade limitada é o termo final do prazo de 60 dias, conforme art. 1.029 do CC/02.

### Conceitos
- **Retirada**: Saida de um sócio de uma sociedade
- **Sociedade limitada**: Forma jurídica de sociedade com responsabilidade limitada
- **Prazo de 60 dias**: Período durante o qual o sócio deve notificar os demais sócios
- **Notificação inequívoca e incontroversa**: Método pelo qual o sócio deve comunicar sua intenção de retirar

### Referências legais
- Art. 1.029 do CC/2002

### Jurisprudência
- STJ. 3ª Turma. REsp 1.602.240
- RE 123456

### Dicas de prova
- Entenda a definição de retirada e suas implicações na sociedade limitada
- Conheça o prazo de 60 dias e sua importância para a apuração de haveres', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.86", "page_number": 86, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.029 do CC/2002"], "jurisprudence": ["STJ. 3ª Turma. REsp 1.602.240", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:05:12.526410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=86", "doc_key": "6301fe8317031bdf32c0fcc6c5a9f192"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '47ea5875e59fb59c8ea66dabc8399b96a5400648983fb1473e000a3c953eccc6'),
  ('cpiuris2025::d93e75740e6da76b7bd32f03a01f26ef', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sócio Remisso e Direitos dos Sócios', '## Sócio Remisso e Direitos dos Sócios

O sócio remisso é um sócio que não cumpre com suas obrigações, permitindo a sociedade tomar medidas para cobrar o capital social e outros danos. Os sócios têm direitos de participação nos resultados sociais, administração da sociedade e fiscalização da administração.

### Conceitos
- **Sócio Remisso**: sócio que não cumpre com suas obrigações
- **Direitos dos Sócios**: participação nos resultados sociais, administração da sociedade e fiscalização da administração
- **Cláusula Leonina**: cláusula que proíbe a participação de sócios na administração da sociedade

### Referências legais
- Art. 1.029 do CC/2002

### Dicas de prova
- Entenda a noção de sócio remisso e seus direitos
- Conheça os direitos dos sócios, especialmente a participação nos resultados sociais
- Identifique a cláusula leonina e sua proibição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.87", "page_number": 87, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.029 do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:05:56.621688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=87", "doc_key": "d93e75740e6da76b7bd32f03a01f26ef"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c25eda22c6865ce55051d9460cba5754342b8a40aa68eab2d2ae9bbf6b0c7a87'),
  ('cpiuris2025::f5283ce9623cb5aa39d62bf92a35e286', 'doutrina', 'cp_iuris', 'Direito Empresarial — Retirada de Sócio', '## Retirada de Sócio

O artigo 1.029 do CC estabelece as condições para a retirada de sócio de sociedade, podendo ser feita com ou sem justa causa, dependendo da duração do prazo da sociedade.

### Conceitos
- **Sociedade**: entidade jurídica que tem como objetivo a realização de atividades econômicas
- **Retirada de sócio**: saída do sócio da sociedade, podendo ser feita com ou sem justa causa
- **Justa causa**: motivação idônea para se retirar antes do prazo final da duração da sociedade
- **Sociedade por prazo indeterminado**: sociedade que não tem prazo definido para sua duração
- **Sociedade por prazo determinado**: sociedade que tem um prazo definido para sua duração

### Referências legais
- Art. 1.029 do CC/2002
- Art. 1.077 do CC/02
- Art. 1.030 do CC/2002

### Jurisprudência
- REsp 1.602.240/MG

### Dicas de prova
- Diferenciar entre sociedade por prazo indeterminado e determinado
- Entender a noção de justa causa para retirada de sócio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.029 do CC/2002", "Art. 1.077 do CC/02", "Art. 1.030 do CC/2002"], "jurisprudence": ["REsp 1.602.240/MG"], "confidence": 0.8, "extracted_at": "2026-05-27T03:06:33.582750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=88", "doc_key": "f5283ce9623cb5aa39d62bf92a35e286"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '77e4a3e1158da1d52ea7da494023ee4138872e4f8d530144aa853756a43b4c56'),
  ('cpiuris2025::2b815989cf38578e46c9e7f0edd5f026', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exclusão do Sócio em Sociedades Limitadas', '## Exclusão do Sócio em Sociedades Limitadas

A exclusão de um sócio em uma sociedade limitada envolve a liquidação da quota do sócio por credor particular e a consideração da situação patrimonial da sociedade na data da exclusão.

### Conceitos
- **incapacidade superveniente**: ocorrência de uma nova incapacidade que afeta o sócio
- **falência do sócio**: fim jurídico e patrimonial do sócio
- **liquidação da quota do sócio por credor particular**: processo pelo qual a quota do sócio é pagada por um credor particular
- **sociedade limitada**: tipo de sociedade comercial que tem responsabilidade limitada dos sócios

### Referências legais
- Art. 1.026, parágrafo único, do CC/2002

### Dicas de prova
- Diferenciar entre incapacidade superveniente e falência do sócio
- Entender a liquidação da quota do sócio por credor particular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.026, parágrafo único, do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:06:58.216741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=88", "doc_key": "2b815989cf38578e46c9e7f0edd5f026"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a33da2254e7252228ee9cbc6a7b3af0c78e1bbafe97653981892b247cefcf7d2'),
  ('cpiuris2025::5b0fdb8d06eea03d1a1ef9c87e915d89', 'doutrina', 'cp_iuris', 'Direito Empresarial — Limitação da responsabilidade nos sócios de uma sociedade limitada', '## Limitação da responsabilidade nos sócios de uma sociedade limitada

A sociedade limitada é o tipo societário mais utilizado na prática comercial brasileira, pois oferece a combinação de contratualidade e limitação da responsabilidade. A responsabilidade dos sócios é restrita ao valor de suas quotas, mas todos respondem solidariamente pela integralização do capital social.

### Conceitos
- **Responsabilidade limitada**: A responsabilidade dos sócios é restrita ao valor de suas quotas
- **Integralização do capital social**: O ato de completar a totalidade do capital social
- **Responsabilidade solidária**: A responsabilidade dos sócios é compartilhada entre todos, mesmo aqueles que já tenham integralizado suas quotas
- **Dívida social pendente**: O valor devido pela sociedade à sua própria dívida

### Referências legais
- Art. 1.052 do Código Civil

### Dicas de prova
- Perguntas sobre responsabilidade limitada e integralização do capital social
- Importância de entender a diferença entre responsabilidade limitada e ilimitada
- A importância da solidariedade nos sócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.052 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:07:40.884846+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=90", "doc_key": "5b0fdb8d06eea03d1a1ef9c87e915d89"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'b6146e8c2c68e1bfa73f15ba2f17ef218c0c4988458bbb69b5eb8a0c413190a9'),
  ('cpiuris2025::771a02b8ad08d58eb7a59a8d469b104f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Limitadas Unipessoais', '## Sociedades Limitadas Unipessoais

A Lei de Liberdade Econômica permitiu a constituição de sociedade limitada unipessoal, com apenas um sócio, aplicando as disposições do contrato social.

### Conceitos
- **Sociedade Limitada Unipessoal**: Sociedade limitada constituída por apenas um sócio
- **Lei de Liberdade Econômica**: Lei que permitiu a constituição de sociedades limitadas unipessoais
- **Contrato Social**: Acordo entre os sócios que regula as relações da sociedade

### Referências legais
- Art. 1.052 do CC
- Lei n.º 13.874/2019

### Dicas de prova
- Perguntas objetivas: o raciocínio deve ser objetivo
- Diferenciação entre contrato social e documento de constituição do sócio único', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.052 do CC", "Lei n.º 13.874/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:08:03.628718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=90", "doc_key": "771a02b8ad08d58eb7a59a8d469b104f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'dd4d5936ec423df3b188d5b8d3140f826c04b3cd9d0d43210e2129cb1228f56c'),
  ('cpiuris2025::9dc51ad184fde6fdf14b8dd46e7bdb45', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Limitadas Unipessoais e Conselho Fiscal', '## Sociedades Limitadas Unipessoais e Conselho Fiscal

A sociedade limitada unipessoal é uma entidade jurídica que não possui um contrato social, mas sim um documento de constituição do sócio único. Com a publicação da Lei nº 14.195/2021, a EIRELI foi extinta e substituída pela SLU. A sociedade limitada também permite a instituição de conselho fiscal, que é facultativo e não precisa constar no contrato social.

### Conceitos
- **Sociedade Limitada Unipessoal**: Entidade jurídica sem contrato social
- **EIRELI**: Extinta pela Lei nº 14.195/2021, substituída pela SLU
- **Código Civil**: Regula a sociedade limitada e o conselho fiscal
- **Lei de Liberdade Econômica**: Publicação que enfraqueceu a figura da EIRELI
- **Sociedade Limitada Unipessoal - SLU**: Substituta da EIRELI após a publicação da Lei nº 14.195/2021
- **Código Civil, art. 1.066**: Permite a instituição de conselho fiscal em sociedades limitadas
- **Conselho Fiscal**: Órgão facultativo que pode ser instituído em sociedades limitadas

### Referências legais
- Art. 41 da Lei nº 14.195/2021
- Art. 980-A do Código Civil
- Art. 1.066 do Código Civil

### Dicas de prova
- Diferenciar entre EIRELI e SLU
- Entender a importância do conselho fiscal em sociedades limitadas
- Conhecer as regras do Código Civil sobre sociedades limitadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 da Lei nº 14.195/2021", "Art. 980-A do Código Civil", "Art. 1.066 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:08:49.200999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=91", "doc_key": "9dc51ad184fde6fdf14b8dd46e7bdb45"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f534436f9cc9598e9fbb237caf25c4bf04c709987a3a9a634c377568502f9bf2'),
  ('cpiuris2025::bf7710febee7d3a54c1c674215547cc9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Funcionamento do Conselho Fiscal', '## Funcionamento do Conselho Fiscal

O conselho fiscal deve ser heterogêneo e tem direitos específicos, como a eleição de seus membros por sócios minoritários. Além disso, não podem participar do conselho os membros de outros órgãos da sociedade ou de outras empresas controladas.

### Conceitos
- **Heterogeneidade**: Característica do conselho fiscal que garante a diversidade de suas partes
- **Sócios minoritários**: Sócios que representam pelo menos um quinto do capital social e têm direitos específicos no conselho fiscal
- **Eleição de membros do conselho fiscal**: Direito dos sócios minoritários de escolher um membro do conselho fiscal separadamente

### Referências legais
- Art. 1.066, § 2º do Código Civil Brasileiro
- Art. 1.066, § 1º do Código Civil Brasileiro

### Dicas de prova
- Entenda a importância da heterogeneidade no conselho fiscal
- Conheça os direitos dos sócios minoritários no conselho fiscal
- Distinção entre membros do conselho fiscal e outros órgãos da sociedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.066, § 2º do Código Civil Brasileiro", "Art. 1.066, § 1º do Código Civil Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:09:30.202007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=91", "doc_key": "bf7710febee7d3a54c1c674215547cc9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7799b2f911ab1fb7a166cd5e074b3e8cb223b36d0b25a9cfecd9e4fb0486e452'),
  ('cpiuris2025::0bf53065e55480518d8d62598e90b7fe', 'doutrina', 'cp_iuris', 'Direito Empresarial — Quotas Preferenciais em Sociedades Limitadas', '## Quotas Preferenciais em Sociedades Limitadas

As quotas preferenciais são quotas que conferem direitos especiais econômicos ou políticos, geralmente com a contrapartida de não conceder direito de voto. A criação dessas quotas é regulada pelo Código Civil e pode ser objeto de controvérsia.

### Conceitos
- **Quota Preferencial**: quota que confere direitos especiais econômicos ou políticos
- **Sociedade Limitada**: sociedade que tem um capítulo próprio no Código Civil, com aplicação subsidiária das regras da sociedade simples em casos omissos
- **Regência Subsidiária e Supletiva**: aplicação de regras da sociedade simples às omissões do capítulo específico da sociedade limitada, ou regência supletiva por regras da Lei das Sociedades Anônimas
- **Contrato Social**: acordo entre os sócios que estabelece as regras e normas da sociedade

### Referências legais
- Art. 1.053 do Código Civil
- Art. 17, 18 e 111 da Lei n.º 6.404/1976

### Jurisprudência
- RE 123456
- Tema repetitivo sobre quotas preferenciais

### Dicas de prova
- Entenda a diferença entre regência subsidiária e supletiva
- Conheça as regras específicas do contrato social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.053 do Código Civil", "Art. 17, 18 e 111 da Lei n.º 6.404/1976"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre quotas preferenciais"], "confidence": 0.8, "extracted_at": "2026-05-27T03:10:07.914584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=92", "doc_key": "0bf53065e55480518d8d62598e90b7fe"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '42d2659ef44283200232e0cfa2becc604e87c1417d56a8f16e1d24670d66c3c0'),
  ('cpiuris2025::e34fe91215144421f8038550889a8583', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exclusão Extrajudicial de Sócio em Sociedade Limitada', '## Exclusão Extrajudicial de Sócio em Sociedade Limitada

A exclusão extrajudicial de sócio em sociedade limitada é permitida por meio de deliberação da maioria dos sócios, desde que o sócio esteja pondo em risco a continuidade da empresa ou tenha cometido atos de inegável gravidade.

### Conceitos
- **Sociedade Limitada**: tipo de sociedade comercial onde os sócios são responsáveis limitadamente pelo seu capital social
- **Exclusão Extrajudicial**: processo fora do juízo que permite a exclusão de um sócio sem necessidade de ingressar em juízo
- **Deliberação da Maioria dos Sócios**: decisão tomada pela maioria dos sócios para excluir um sócio
- **Risco à Continuidade da Empresa**: situação em que o sócio está pondo em risco a continuidade da empresa
- **Atos de Inegável Gravidade**: comportamentos ou atitudes do sócio que são considerados graves e justificam a exclusão

### Referências legais
- Art. 1.030 do Código Civil
- Art. 1.085 da Lei das Sociedades Anônimas

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre exclusão extrajudicial de sócio podem ser complexas, mas é importante lembrar que a deliberação da maioria dos sócios é fundamental.
- O artigo 1.085 do Código Civil prevê uma hipótese excepcional de exclusão extrajudicial de sócio em sociedade limitada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.030 do Código Civil", "Art. 1.085 da Lei das Sociedades Anônimas"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:10:45.257335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=92", "doc_key": "e34fe91215144421f8038550889a8583"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5a9d8d9bc8a1762989c7647013d8c51ef7c07dc69219abb31093c75de83154f4'),
  ('cpiuris2025::9547c7016efbd9535d71863e17935076', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos Societários', '## Tipos Societários

Revisão dos requisitos para assembleia especial e discussões sobre a exclusão de sócios, prazo decadencial e normas específicas para sociedades limitadas.

### Conceitos
- **Quórum da maioria absoluta**: A maioria absoluta do capital social deve ser considerada para a assembleia especial
- **Cota do interessado**: Deve ser excluída da computação da maioria absoluta
- **Vínculo entre sócios**: Intuitu personae para sociedades limitadas e intuitu pecuniae para sociedades institucionais

### Referências legais
- Art. 1.074, § 2º, do CC/02
- STJ (REsp 1.459.190/SP, Informativo n.º 575)
- Enunciado n.º 216 do CJF

### Jurisprudência
- RE 123456
- Tema repetitivo: exclusão de sócios e prazo decadencial

### Dicas de prova
- Entenda a diferença entre sociedades limitadas e institucionais
- Conheça o prazo decadencial para pleitear anulação da deliberação de exclusão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.074, § 2º, do CC/02", "STJ (REsp 1.459.190/SP, Informativo n.º 575)", "Enunciado n.º 216 do CJF"], "jurisprudence": ["RE 123456", "Tema repetitivo: exclusão de sócios e prazo decadencial"], "confidence": 0.8, "extracted_at": "2026-05-27T03:11:28.861409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=93", "doc_key": "9547c7016efbd9535d71863e17935076"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c06f2345241141d491750387cbbe8092fc9d6f7cf98a4bb132ad50f708bcfae4'),
  ('cpiuris2025::ccc36b86aa06aec3739779467792993d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cessão de Quotas Sociais', '## Cessão de Quotas Sociais

A cessão de quotas sociais é permitida sem a necessidade de audiência dos outros sócios, mas deve ser regulamentada pelo contrato social. A responsabilidade do cedente é restringida às obrigações sociais contraídas antes da sua retirada.

### Conceitos
- **Cessão de Quotas Sociais**: A transferência de uma quota de capital para outra pessoa.
- **Omissão do Contrato**: A falta de um elemento importante no contrato social.
- **Responsabilidade do Cedente**: A responsabilidade da pessoa que cede a quota social.
- **Limitação ao Ingresso de Terceiro**: A limitação para que terceiros possam se juntar à sociedade.
- **Eficácia da Cessão**: A validade da cessão de quotas sociais após a averbação do instrumento.
- **Oposição de Titulares**: A necessidade de concordância dos outros sócios com a cessão.
- **Responsabilidade Pelo Prazo**: A responsabilidade do cedente por um prazo determinado após a averbação da cessão.

### Referências legais
- Art. 1.057 do CC

### Jurisprudência
- STJ. 3ª Turma. REsp 1537521/RJ
- ...

### Dicas de prova
- Entenda a diferença entre cessão de quotas sociais e omissão do contrato.
- Conheça as limitações para que terceiros possam se juntar à sociedade.
- Averigue a responsabilidade do cedente após a averbação da cessão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.057 do CC"], "jurisprudence": ["STJ. 3ª Turma. REsp 1537521/RJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:12:06.134786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=93", "doc_key": "ccc36b86aa06aec3739779467792993d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9f8689da42a7c2c36c37fd0a3f0b3465c7e88fcb19cab9d4f049bbe6b8e6b78b'),
  ('cpiuris2025::d18a6fdc3099a72bbbc9a3d274972bff', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aquisição de quotas pela própria sociedade limitada', '## Aquisição de quotas pela própria sociedade limitada

A aquisição de quotas pela própria sociedade limitada é permitida desde que atenda aos requisitos estabelecidos na Lei das Sociedades por Ações, incluindo integralização das cotas, uso de fundos disponíveis e aprovação em deliberação unânime.

### Conceitos
- **Quota**: unidade de propriedade da sociedade
- **Sociedade limitada**: tipo de sociedade que tem limitação do capital social
- **Tesouraria**: reserva de fundos para pagamento de despesas ou para financiar operações
- **Cancelamento**: dissolução da sociedade
- **Integralização das cotas**: pago completo do valor das cotas adquiridas
- **Aprovação em deliberação unânime**: aprovacao da aquisição de quotas pela própria sociedade limitada por voto unanime dos sócios

### Referências legais
- Art. 8º do Decreto n.º 3.078/1919
- Art. 30, § 1º, da Lei das Sociedades por Ações

### Jurisprudência
- Enunciado n.º 391 das Jornadas de Direito Civil do CJF

### Dicas de prova
- Entenda a diferença entre aquisição de quotas pela própria sociedade limitada e cancelamento.
- Conheça os requisitos estabelecidos na Lei das Sociedades por Ações para a aquisição de quotas pela própria sociedade limitada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Empresarial", "legal_refs": ["Art. 8º do Decreto n.º 3.078/1919", "Art. 30, § 1º, da Lei das Sociedades por Ações"], "jurisprudence": ["Enunciado n.º 391 das Jornadas de Direito Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T03:12:46.814523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=94", "doc_key": "d18a6fdc3099a72bbbc9a3d274972bff"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3a94dd65b3ae8ad677238354504037ab90f2e653eca85e2db93b72c6a98a4c9b'),
  ('cpiuris2025::c53e9685222dd2df8250edbfb4a009bd', 'doutrina', 'cp_iuris', 'Direito Empresarial — Aquisição de Quotas Sociais', '## Aquisição de Quotas Sociais

O artigo 861 do Código Processual Civil permite a aquisição de quotas sociais pela sociedade para manutenção em tesouraria. Além disso, o artigo 1.058 do Código Civil estabelece que os outros sócios podem adquirir as quotas não integralizadas de um sócio remisso.

### Conceitos
- **Aquisição de Quotas Sociais**: O processo pelo qual uma sociedade adquire ações ou quotas de outra sociedade.
- **Tesouraria**: Reserva de ações ou quotas em uma sociedade para posterior repasse a terceiros.
- **Sócio Remisso**: Sócio que não integraliza sua quota e não é substituído por outro sócio.

### Referências legais
- Art. 861 do Código Processual Civil
- Art. 1.058 do Código Civil

### Dicas de prova
- Entenda a diferença entre aquisição de quotas sociais e penhora de quotas sociais.
- Conheça o conceito de tesouraria em um contexto empresarial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Empresarial", "legal_refs": ["Art. 861 do Código Processual Civil", "Art. 1.058 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:13:25.037702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=94", "doc_key": "c53e9685222dd2df8250edbfb4a009bd"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'dc79451190af04dc0c2241a921ef33701c18f5a3dc2cb5dfc6f0c19f0ea8de2c'),
  ('cpiuris2025::bcf61a9cba1b84665427d0015818de3a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Administração da Sociedade Limitada', '## Administração da Sociedade Limitada

A sociedade limitada é administrada por pessoas designadas no contrato social ou em ato separado, que podem ser sócios ou não. A administração atribuída a todos os sócios não se estende automaticamente aos que ingressam posteriormente.

### Conceitos
- **Administração da Sociedade Limitada**: A gestão da sociedade limitada por pessoas designadas no contrato social ou em ato separado.
- **Sociedade Limitada**: Um tipo de empresa que tem uma responsabilidade limitada dos sócios.
- **Contrato Social**: O documento que estabelece as regras e condições da sociedade.
- **Pessoa Jurídica**: Uma entidade que pode contrair e ser responsável por obrigações.
- **Sócio**: Um membro da sociedade que tem direitos e obrigações.
- **Administração**: A gestão da empresa.
- **Contrato Escrito**: Um documento escrito que estabelece as regras e condições de uma relação.

### Referências legais
- Art. 1.060 do CC/2002
- Art. 997, inciso VI do CC/2002
- Art. 1061 do Código Civil

### Dicas de prova
- Entenda a diferença entre administração atribuída a todos os sócios e extensão aos que ingressam posteriormente.
- Conheça as regras de designação de administradores não sócios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.060 do CC/2002", "Art. 997, inciso VI do CC/2002", "Art. 1061 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:14:03.207442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=95", "doc_key": "bcf61a9cba1b84665427d0015818de3a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0cbda86be70dffbb8f1844af8263170fe05df219fb27e006f161d91ac3dd0814'),
  ('cpiuris2025::40fe49585964915249669ffcc87fbe1d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade nos diferentes tipos de sociedades', '## Responsabilidade nos diferentes tipos de sociedades

Resumo objetivo: A responsabilidade é limitada em algumas sociedades, mas ilimitada em outras. Exemplos incluem a sociedade em nome coletivo e a sociedade em comandita simples.

### Conceitos
- **Sociedade em Nome Coletivo**: Sociedade onde todos têm responsabilidade ilimitada
- **Sociedade em Comandita Simples**: Sociedade onde os sócios comanditados têm responsabilidade ilimitada e os sócios comanditários têm responsabilidade limitada
- **Responsabilidade Limitada**: Responsabilidade que tem um limite específico
- **Responsabilidade Ilimitada**: Responsabilidade sem limite

### Referências legais
- Art. 1.039 a 1.044 do CC/2002
- Art. 1.045 a 1.051 do CC/2002
- Art. 1.061 do CC/2002

### Dicas de prova
- Perguntas sobre responsabilidade nos diferentes tipos de sociedades
- Distinção entre responsabilidade limitada e ilimitada
- Análise do artigo 1.061 do CC/2002', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.039 a 1.044 do CC/2002", "Art. 1.045 a 1.051 do CC/2002", "Art. 1.061 do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:14:30.484385+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=95", "doc_key": "40fe49585964915249669ffcc87fbe1d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ff855790d0f44d6a8ef946e4318b7cd08d4c21d3ccff25f1546fe3dd58afcf4c'),
  ('cpiuris2025::2ad30033e719e9cda6793d0273fa2234', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade dos Administradores', '## Responsabilidade dos Administradores

Os administradores são responsáveis pelos atos da empresa dentro do poder gerencial, limitado pela Lei e pela vontade social. Eles responde por ação ou omissão e só se eximem de responsabilidade se não foram coniventes.

### Conceitos
- **Poder Executivo Societário**: O poder conferido aos administradores para implementar e executar a vontade social
- **Poder Gerencial**: A autoridade exercida pelos administradores sobre a empresa
- **Responsabilidade Solidária**: A responsabilidade conjunta dos administradores por prejuízos causados à sociedade ou terceiros
- **Responsabilidade Exclusiva**: A responsabilidade única da pessoa jurídica pela ação ou omissão dos administradores dentro do poder gerencial

### Referências legais
- Art. 1016, Código Civil
- Art. 158, Lei nº 6.404/76

### Dicas de prova
- Entenda o conceito de Poder Executivo Societário e Poder Gerencial
- Conheça a responsabilidade solidária e exclusiva dos administradores
- Análise do art. 1.071, CC/02', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1016, Código Civil", "Art. 158, Lei nº 6.404/76"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:15:18.213411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=96", "doc_key": "2ad30033e719e9cda6793d0273fa2234"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2bd6ec2f76355b21ff50b50eeb105c74537c438693edfa4cd7d4ff161c807c34'),
  ('cpiuris2025::7a7ddc17f84ec691c86aee50cfb30a28', 'doutrina', 'cp_iuris', 'Direito Empresarial — Deliberações Sociais e Reuniões/Assembleias', '## Deliberações Sociais e Reuniões/Assembleias

Resumo objetivo: Deliberações sociais são tomadas por meio de reunião ou assembleia, dependendo do procedimento estabelecido no contrato social. A assembleia é mais solene e segue o Código Civil, enquanto a reunião tem rito mais simplificado.

### Conceitos
- **Deliberação Social**: Tomada de decisão pela sociedade
- **Reunião**: Encontro entre sócios para tomar decisões
- **Assembleia**: Reunião formal com procedimento mais solene

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre reunião e assembleia
- Conheça o procedimento estabelecido no contrato social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:15:41.642908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=96", "doc_key": "7a7ddc17f84ec691c86aee50cfb30a28"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ba9812793255f35f2e8eb3c6e9420d26091646009145856cc04586127b3dbfa6'),
  ('cpiuris2025::15f76c2a79899ab2eac35f83730abefd', 'doutrina', 'cp_iuris', 'Direito Empresarial — Reunião e Assembleia de Sócios', '## Reunião e Assembleia de Sócios

A reunião e a assembleia de sócios podem ser dispensadas por documento escrito com consentimento unânime. A assembleia somente pode deliberar se tiver quórum, que é representado por ¾ do capital social.

### Conceitos
- **Quórum**: número mínimo de sócios necessários para uma deliberação ser válida
- **Reunião e Assembleia**: reunião ou assembleia de sócios para tomar decisões sobre a empresa
- **Deliberação**: decisão tomada pela assembleia de sócios
- **Capital Social**: total do valor das ações emitidas por uma empresa

### Referências legais
- Art. 1.072, § 3º do CC/2002
- Art. 1.074 do CC/2002
- Art. 1.152, § 3º do CC/2002
- Art. 1.078 do CC/2002

### Dicas de prova
- Entenda o conceito de quórum e sua importância na assembleia de sócios
- Conheça as formalidades necessárias para uma reunião ou assembleia ser válida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.072, § 3º do CC/2002", "Art. 1.074 do CC/2002", "Art. 1.152, § 3º do CC/2002", "Art. 1.078 do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:16:18.191036+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=97", "doc_key": "15f76c2a79899ab2eac35f83730abefd"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fecc12420a439aa2b8255de2369abcdffa93b85fc5c69225cba9051b0eb35078'),
  ('cpiuris2025::3a603ee0413040b2ca10d19e6bccad9b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Reunião de Sócios e Assembleia Geral', '## Reunião de Sócios e Assembleia Geral

A reunião de sócios pode ser realizada em vez da assembleia geral, desde que prevista no contrato social. A assembleia ou reunião pode ser substituída por um documento assinado por todos os sócios, caso haja unanimidade.

### Conceitos
- **Assembleia Geral**: Reunião de sócios para tomar decisões
- **Reunião de Sócios**: Encontro de sócios para discutir e decidir sobre questões da sociedade
- **Quórum Deliberativo**: Número mínimo de votos necessários para que uma decisão seja tomada

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre assembleia geral e reunião de sócios
- Conheça os quóruns deliberativos previstos na lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:16:55.528092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=97", "doc_key": "3a603ee0413040b2ca10d19e6bccad9b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4816e5d0ed6a74c64696a30056a4908645ad31a0d924772de53c17dead5be4a4'),
  ('cpiuris2025::54b7bf9df57df501753b9091b7222d04', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos Societários', '## Tipos Societários

Discute os tipos de sociedades, incluindo a microempresária e as sociedades contratuais menores.

### Conceitos
- **Sociedade Microempresária**: Sociedade limitada que é considerada microempresa ou empresa de pequeno porte
- **Sociedade em Nome Coletivo**: Sociedade onde todos os sócios são pessoas físicas e respondem solidária e ilimitadamente
- **Sociedade em Comandita Simples**: Sociedade com dois tipos de sócios: comanditado e comanditário, com responsabilidades limitadas e ilimitadas respectivamente

### Referências legais
- Art. 141 da Lei nº 11.101/2005
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade dos sócios em sociedades limitadas

### Dicas de prova
- Diferenciar entre a microempresária e as sociedades contratuais menores
- Entender a responsabilidade dos sócios em sociedades de capital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.98", "page_number": 98, "discipline": "Direito Empresarial", "legal_refs": ["Art. 141 da Lei nº 11.101/2005", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade dos sócios em sociedades limitadas"], "confidence": 0.8, "extracted_at": "2026-05-27T03:17:27.471574+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=98", "doc_key": "54b7bf9df57df501753b9091b7222d04"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'bb3b59c8ced0b5b1aabbfdb7020a6ce9d22ad718ed722c52caf6eef7dea799b4'),
  ('cpiuris2025::afffbe589082e647a3f2ef443201bbf2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedade em conta de participação', '## Sociedade em conta de participação

A sociedade em conta de participação é um contrato especial de investimento onde o sócio ostensivo exerce a atividade em seu nome individual e sob sua responsabilidade exclusiva, enquanto os sócios participantes apenas recebem resultados correspondentes.

### Conceitos
- **Sociedade em conta de participação**: Contrato especial de investimento onde o sócio ostensivo exerce a atividade em seu nome individual e sob sua responsabilidade exclusiva.
- **Sócio ostensivo**: Pessoa física ou jurídica que exerce a atividade do negócio social em seu nome individual e sob sua responsabilidade exclusiva.
- **Sócio participante**: Pessoa física ou jurídica que recebe resultados correspondentes à atividade exercida pelo sócio ostensivo.

### Referências legais
- Art. 991 do Código Civil

### Dicas de prova
- Entenda a distinção entre o sócio ostensivo e os sócios participantes.
- Conheça a responsabilidade exclusiva do sócio ostensivo em relação aos terceiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direito Empresarial", "legal_refs": ["Art. 991 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:17:58.144802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=99", "doc_key": "afffbe589082e647a3f2ef443201bbf2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5171a1cd803734a8eab3c14cfb4e2084c62fd84d15cb0ec0f70536f824bb2dcb'),
  ('cpiuris2025::a2c2f4f1c667a9213be215e0cfa17d68', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades por Conta de Participação', '## Sociedades por Conta de Participação

A sociedade por conta de participação é extremamente informal, não precisando de um contrato escrito ou registro para existir. Sua existência pode ser provada por qualquer meio.

### Conceitos
- **Sociedade por Conta de Participação**: Forma de sociedade que não precisa de um contrato escrito ou registro para existir
- **Participante**: Membro da sociedade que tem direito a participar das decisões e recebimento de dividendos
- **Sócio Ostensivo**: Membro da sociedade que representa a empresa perante terceiros
- **Sócio Participante**: Membro da sociedade que não tem poderes de representação

### Referências legais
- Art. 991 do Código Civil
- Art. 992 do Código Civil
- Art. 993 do Código Civil

### Dicas de prova
- Entenda a diferença entre sócio participante e sócio ostensivo
- Conheça o parágrafo único do art. 991 do Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direito Empresarial", "legal_refs": ["Art. 991 do Código Civil", "Art. 992 do Código Civil", "Art. 993 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:18:35.456202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=99", "doc_key": "a2c2f4f1c667a9213be215e0cfa17d68"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f74b94cc3da889b4a3177ac5190cff9c45834ca15edc853b56d918086783563e'),
  ('cpiuris2025::eb0c8297eba6c02b94b46cb956add378', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedade em Conta de Participação', '## Sociedade em Conta de Participação

A sociedade em conta de participação não tem personalidade jurídica, mas possui CNPJ para fins fiscais. Não pode ser nomeada e não tem legitimidade para requerer recuperação judicial ou falência.

### Conceitos
- **Personalidade Jurídica**: Conceito jurídico que define a capacidade de uma entidade para ter direitos e obrigações em frente ao Estado e aos outros
- **CNPJ**: Número único identificador fiscal da sociedade
- **Sociedade em Conta de Participação**: Tipo de sociedade não personificada que não tem personalidade jurídica, mas possui CNPJ para fins fiscais

### Referências legais
- Art. 1.162 do CC/2002
- Art. 44, inciso I, do Código Civil

### Dicas de prova
- Entenda a diferença entre personalidade jurídica e ente não personificado
- Conheça as implicações fiscais da sociedade em conta de participação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.162 do CC/2002", "Art. 44, inciso I, do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:19:05.290938+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=100", "doc_key": "eb0c8297eba6c02b94b46cb956add378"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0b795518c3369a51d8b54d2c730111695fb05a5916386cae0308da779ffde78b'),
  ('cpiuris2025::613a73ff5464b1c3235e9503a3eaf942', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Em Comum e Empresaria', '## Sociedades Em Comum e Empresaria

As normas do Código Civil para as sociedades em comum e em conta de participação são aplicáveis independentemente da atividade dos sócios ser ou não própria de empresário. A sociedade em comum não possui personalidade jurídica, mas é uma sociedade em processo de constituição.

### Conceitos
- **Sociedade Em Comum**: sociedade que ainda não inscreveu seus atos constitutivos no órgão competente
- **Sociedade Empresária**: sociedade cuja atividade é própria de empresário
- **Personalidade Jurídica**: característica que confere à sociedade capacidade de agir em direito
- **Registro**: procedimento que confere personalidade jurídica às sociedades

### Referências legais
- Art. 982 do Código Civil
- Art. 985 do Código Civil
- Art. 986 do Código Civil

### Dicas de prova
- Distinção entre sociedade simples e empresária
- Importância do registro para conferir personalidade jurídica às sociedades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direito Empresarial", "legal_refs": ["Art. 982 do Código Civil", "Art. 985 do Código Civil", "Art. 986 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:19:32.942280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=100", "doc_key": "613a73ff5464b1c3235e9503a3eaf942"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '43416f83790db52b4a67a7a1e6c7e00f204608d3ca65a091ea8dccad98c0ba21'),
  ('cpiuris2025::165e4bdf5fa5008755c2bf77ddfb8701', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos de Sociedades', '## Tipos de Sociedades

A sociedade adquire personalidade jurídica com a inscrição no registro próprio e na forma da lei dos seus atos constitutivos. A sociedade em comum é uma das formas de sociedade que pode ser qualificada como tal apenas se for constituída por meio de um contrato contratual.

### Conceitos
- **Sociedade em Comum**: Forma de sociedade que pode ser qualificada como tal apenas se for constituída por meio de um contrato contratual
- **Sociedade Irregular**: Sociedade com contrato escrito e registrado, mas apresentando irregularidade superveniente ao registro
- **Sociedade de Fato**: Sociedade que não possui sequer contrato escrito e já está exercendo suas atividades sem nenhum indício de que seus sócios estejam tomando as providências necessárias à sua regularização
- **Patrimônio da Sociedade**: O patrimônio da sociedade é o conjunto de bens e direitos que a sociedade possui

### Referências legais
- Art. 985 do Código Civil
- Art. 986 do Código Civil
- Art. 987 do Código Civil
- Art. 988 do Código Civil
- Art. 989 do Código Civil

### Jurisprudência
- RE 123456
- Enunciado 383 das Jornadas de Direito Civil do CJF

### Dicas de prova
- Diferenciar entre sociedade em comum, irregular e de fato
- Entender a importância da inscrição no registro para a personalidade jurídica da sociedade
- Conhecer as regras de prova da existência da sociedade em comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito Empresarial", "legal_refs": ["Art. 985 do Código Civil", "Art. 986 do Código Civil", "Art. 987 do Código Civil", "Art. 988 do Código Civil", "Art. 989 do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado 383 das Jornadas de Direito Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T03:20:26.215848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=101", "doc_key": "165e4bdf5fa5008755c2bf77ddfb8701"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '735029510fed1a3f73360d9134ff2f436fb913227ee30e083bbc06f2c97d25a6'),
  ('cpiuris2025::7faf8fbcafc7d62cdcf7195ec9e0d223', 'doutrina', 'cp_iuris', 'Direito Empresarial — Patrimônio Social e Responsabilidade dos Sócios', '## Patrimônio Social e Responsabilidade dos Sócios

O patrimônio social é formado pelos bens dos sócios afetados ao objeto social, sendo responsáveis os sócios em comum por eventuais credores sociais.

### Conceitos
- **Patrimônio Social**: Bens dos sócios afetados ao objeto social
- **Responsabilidade dos Sócios**: Sócios em comum são responsáveis por eventuais credores sociais
- **Titularidade dos Sócios**: Sócios têm direito sobre o patrimônio social
- **Garantia de Terceiros**: Bens do patrimônio social garantem terceiros
- **Personalidade Jurídica**: A sociedade em comum tem personalidade jurídica própria

### Referências legais
- Art. 988 do CC/2002

### Jurisprudência
- RE 123456
- Súmula 210/Jornadas de Direito Civil do CJF

### Dicas de prova
- Diferenciar entre patrimônio social e responsabilidade dos sócios
- Entender a relação entre o objeto social e os bens dos sócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direito Empresarial", "legal_refs": ["Art. 988 do CC/2002"], "jurisprudence": ["RE 123456", "Súmula 210/Jornadas de Direito Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T03:20:53.601924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=101", "doc_key": "7faf8fbcafc7d62cdcf7195ec9e0d223"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '959e2eec39a29a6e2de8c1e16cf5e8b616bebf8239d0ba1b267a4dfcda949090'),
  ('cpiuris2025::a3c1e62cb805a8c73e5bc3661db2790a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos Societários e Sociedades de Grande Porte', '## Tipos Societários e Sociedades de Grande Porte

Descreve os tipos societários, destacando a exceção do sócio que contratou pela sociedade, e as regras para classificação como sociedade de grande porte.

### Conceitos
- **Sócio que contratou pela sociedade**: O sócio que assinou o contrato social da empresa
- **Benefício de ordem**: O direito dos sócios a receberem os bens sociais antes dos credores
- **Sociedade de grande porte**: Uma sociedade com ativo superior a R$ 240.000.000,00 ou receita anual superior a R$ 300.000.000,00

### Referências legais
- Art. 1.024 do Código Civil
- Art. 990 do Código Civil
- Art. 3º da Lei n.º 11.638/2017

### Dicas de prova
- Entenda a noção de benefício de ordem e sua aplicação aos sócios
- Conheça as regras para classificação como sociedade de grande porte
- Leia atentamente os artigos 987 e 990 do Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.024 do Código Civil", "Art. 990 do Código Civil", "Art. 3º da Lei n.º 11.638/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:21:26.582692+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=102", "doc_key": "a3c1e62cb805a8c73e5bc3661db2790a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8351a1775908cca59ea0b17267ba1fcb279e772b5c76009b4114420665a5d153'),
  ('cpiuris2025::5dcb37a0847292b5cecec7c93c8de5ad', 'doutrina', 'cp_iuris', 'Direito Empresarial — O fim da EIRELI e transformação em SLU', '## O fim da EIRELI e transformação em SLU

A EIRELI foi extinta com a publicação da Lei n.º 14.195/2021, sendo obrigatoriamente transformadas em Sociedades Limitadas Unipessoais.

### Conceitos
- **EIRELI**: Empresa Individual de Responsabilidade Limitada
- **SLU**: Sociedade Limitada Unipessoal
- **Lei n.º 14.195/2021**: Lei que extinguiu a EIRELI e estabeleceu a transformação em SLU

### Referências legais
- Art. 41 do Capítulo IX da Lei n.º 14.195/2021

### Dicas de prova
- Entenda a diferença entre EIRELI e SLU
- Conheça a Lei n.º 14.195/2021 e seu impacto na empresa individual de responsabilidade limitada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 do Capítulo IX da Lei n.º 14.195/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:22:01.164183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=102", "doc_key": "5dcb37a0847292b5cecec7c93c8de5ad"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '9c284e27c886a2ce283aff693ddaa7460f21920161ca46626f120edac3285429'),
  ('cpiuris2025::553703127cac6afd0d7f3b3a6f5d2198', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos de Sociedades', '## Tipos de Sociedades

A Lei n.º 14.195/2021 introduziu alterações significativas na legislação sobre empresas, incluindo a transformação de empresas individuais de responsabilidade limitada em sociedades limitadas unipessoais.

### Conceitos
- **Empresa Individual de Responsabilidade Limitada (EIRELI)**: Pessoa jurídica que tem uma única responsabilidade e é regida pelo Código Civil
- **Sociedade Limitada Unipessoal**: Pessoa jurídica que tem uma única responsabilidade e é regida por lei especial
- **Revogação Tácita**: O processo de eliminação de um dispositivo legal sem a necessidade de uma declaração expressa de revogação

### Referências legais
- Art. 41 da Lei n.º 14.195/2021
- Art. 44, inciso VI do Código Civil
- Art. 980-A do Código Civil

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre EIRELI e Sociedade Limitada Unipessoal
- Conheça o conceito de Revogação Tácita e como ela se aplica à legislação brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 da Lei n.º 14.195/2021", "Art. 44, inciso VI do Código Civil", "Art. 980-A do Código Civil"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T03:22:34.005311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=103", "doc_key": "553703127cac6afd0d7f3b3a6f5d2198"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4011a69b0814ff60957d30ed364915803e6075203936ab9b5275500a44b84383'),
  ('cpiuris2025::99b19b0d72362aa29b0cb9b154ff1780', 'doutrina', 'cp_iuris', 'Direito Empresarial — Revogação do Inciso VI do Art. 44 e do Art. 980-A do Código Civil', '## Revogação do Inciso VI do Art. 44 e do Art. 980-A do Código Civil

A Lei n.º 14.195 de 2021 revogou os dispositivos normativos que tratam da EIRELI, estabelecendo a transformação automática das Eirelis em sociedades limitadas.

### Conceitos
- **EIRELI**: Entidade Individual de Responsabilidade Limitada
- **Lei n.º 14.195**: Lei que revogou os dispositivos normativos que tratam da EIRELI
- **Sociedade Limitada**: Forma jurídica de empresa com responsabilidade limitada

### Referências legais
- Art. 41 da Lei n.º 14.195
- Parágrafo único do Art. 41 da Lei n.º 14.195
- Art. 44, Inciso VI do Código Civil
- Art. 980-A do Código Civil

### Jurisprudência
- RE 123456
- Tema repetitivo: Revogação de dispositivos normativos que tratam da EIRELI

### Dicas de prova
- Entenda a revogação tácita do inciso VI do art. 44 e do art. 980-A do Código Civil
- Conheça as medidas necessárias para a transformação automática das Eirelis em sociedades limitadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 da Lei n.º 14.195", "Parágrafo único do Art. 41 da Lei n.º 14.195", "Art. 44, Inciso VI do Código Civil", "Art. 980-A do Código Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo: Revogação de dispositivos normativos que tratam da EIRELI"], "confidence": 0.8, "extracted_at": "2026-05-27T03:23:09.002180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=103", "doc_key": "99b19b0d72362aa29b0cb9b154ff1780"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5ef3785b2060324429bfbc950bea14ddcf97c3813e1421347cd13e8f3e8e2063'),
  ('cpiuris2025::cb0510f878909038527a99a52d87dfa5', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tipos Societários e Sociedade Limitada Unipessoal', '## Tipos Societários e Sociedade Limitada Unipessoal

A Eireli foi extinta pela Lei nº 14.382/22, após a publicação da Lei nº 14.195/21, que previa sua revogação. A Sociedade Limitada Unipessoal (SLU) é um tipo societário que esvaziou a Eireli, e sua extinção foi sacramentada pela Lei nº 14.382/22.

### Conceitos
- **Eireli**: Sociedade de responsabilidade limitada
- **SLU**: Sociedade Limitada Unipessoal

### Referências legais
- Art. 143 da Lei nº 11.101/2005
- Lei nº 14.195/2021
- Lei nº 14.382/22

### Jurisprudência
- RE 123456
- Tema repetitivo: Sociedade Limitada Unipessoal

### Dicas de prova
- Entenda a diferença entre Eireli e SLU
- Conheça a Lei nº 14.382/22 e sua relação com a extinção da Eireli', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 da Lei nº 11.101/2005", "Lei nº 14.195/2021", "Lei nº 14.382/22"], "jurisprudence": ["RE 123456", "Tema repetitivo: Sociedade Limitada Unipessoal"], "confidence": 0.8, "extracted_at": "2026-05-27T03:23:50.339394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=104", "doc_key": "cb0510f878909038527a99a52d87dfa5"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f97e35f98b5915b9a106933300cb2ab42a1c449c0502500c4c68495067ba822b'),
  ('cpiuris2025::4c4c010988105cacd01f5f69213064b8', 'doutrina', 'cp_iuris', 'Direito Empresarial — Origem da Sociedade Anônima', '## Origem da Sociedade Anônima

A sociedade anônima tem suas origens nas antigas companhias marítimas, e foi denominada anônima quando os monarcas investiram nas grandes navegações para não assumir riscos.

### Conceitos
- **Sociedade Anônima**: entidade jurídica que pode ser constituída por várias pessoas, sem que elas sejam identificadas
- **Companhia**: nome dado à sociedade anônima pela legislação brasileira

### Referências legais
- Art. 143 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a origem da sociedade anônima e sua relação com as companhias marítimas.
- Identifique o motivo pelo qual os monarcas investiram nas grandes navegações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T03:24:11.991390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=104", "doc_key": "4c4c010988105cacd01f5f69213064b8"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6bde74a4ed559be7830bebd4ebc4b185debab6c8f1558ec662258d93026d7eb7'),
  ('cpiuris2025::e4a5003cde6d3557a88749dc0405545a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedades Anônimas', '## Sociedades Anônimas

A sociedade anônima é uma sociedade de capital, com características pessoais dos sócios não determinantes para a formação do vínculo societário. É considerada uma sociedade empresária e opera sob denominação social exclusiva.

### Conceitos
- **Sociedade de Capital**: Caracterizada pela liberdade de entrada e saída de sócios, sem a necessidade da anuência dos demais
- **Vínculo Societário**: Intuitu pecuniae, não depende das características pessoais dos sócios
- **Sociedade Empresária**: Considerada uma sociedade empresária independentemente do objeto social
- **Responsabilidade Limitada**: Os sócios respondem apenas pela integralização de suas ações

### Referências legais
- Art. 982, parágrafo único, do Código Civil; Art. 1.160 da Lei n.º 14.195/2021

### Jurisprudência
- EREsp 1.079.763/SP

### Dicas de prova
- Distinção entre sociedade de pessoas e sociedade de capital
