  ('cpiuris2025::98ab25b8a6bebbb862e6cc252330edde', 'doutrina', 'cp_iuris', 'Direito Empresarial — Negociação de Mobiliários em Mercado de Valores', '## Negociação de Mobiliários em Mercado de Valores

Rege a negociação de mobiliários em mercado de valores, exigindo registro na CVM para valores mobiliários de emissão de companhias registradas.

### Conceitos
- **Comissão de Valores Mobiliários (CVM)**: Entidade responsável por regular e supervisionar a negociação de valores mobiliários no Brasil.
- **Sociedade Anônima aberta**: Sociedade Anônima que pode ter suas ações e demais títulos negociados em bolsa, após registro perante a CVM.
- **Sociedade Anônima fechada**: Sociedade Anônima que não pode ter suas ações e demais títulos negociados em bolsa, sem registro perante a CVM.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância do registro na CVM para a negociação de valores mobiliários.
- Conheça as diferenças entre Sociedade Anônima aberta e fechada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:25:21.997754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=105", "doc_key": "98ab25b8a6bebbb862e6cc252330edde"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ee397e88b1dbc6a56de6dc54412167fb1875b402cd573f58024f0f29e9c01b8e'),
  ('cpiuris2025::d01e47632b49660901d8d83a4d4c4aed', 'doutrina', 'cp_iuris', 'Direito Empresarial — Comissão de Valores Mobiliários (CVM) e Mercado de Capitais', '## Comissão de Valores Mobiliários (CVM) e Mercado de Capitais

A CVM é uma entidade autárquica que regula, autoriza e fiscaliza o mercado de capitais, estabelecendo regramento geral para seu funcionamento.

### Conceitos
- **Comissão de Valores Mobiliários (CVM)**: entidade autárquica que regula, autoriza e fiscaliza o mercado de capitais
- **Mercado de Capitais**: setor financeiro onde os valores mobiliários são negociados
- **Mercado Primário**: mercado onde os valores mobiliários são emitidos e subscritos por novos acionistas
- **Mercado Secundário**: mercado onde os valores mobiliários já existentes são comprados e vendidos entre investidores
- **Bolsa de Valores**: entidade privada que mantém um local apropriado para a negociação pública de valores mobiliários

### Referências legais
- Art. 5º da Lei n.º 6.385/76

### Dicas de prova
- Entenda a distinção entre mercado primário e secundário
- Conheça as funções da CVM no mercado de capitais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direito Empresarial", "legal_refs": ["Art. 5º da Lei n.º 6.385/76"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:25:59.314635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=106", "doc_key": "d01e47632b49660901d8d83a4d4c4aed"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '200d4d9c2d353cc0b5330f574bf3bee99b369dc943b9171a9cf172fef6f0d125'),
  ('cpiuris2025::86ce18900735cb49d6d4173fd7b413e9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Desmutualização das Bolsas de Valores', '## Desmutualização das Bolsas de Valores

A desmutualização das bolsas de valores ocorre quando elas deixam de ser associações civis sem fins lucrativos para se tornarem empresárias, muitas vezes se transformando em S.A. de capital aberto.

### Conceitos
- **Desmutualização**: O processo pelo qual as bolsas de valores deixam de ser associações civis sem fins lucrativos
- **Empresária**: Organização jurídica que tem como objetivo principal a realização de atividades econômicas
- **S.A. de capital aberto**: Forma jurídica de empresa que permite a aquisição de ações por investidores

### Referências legais
- Art. 102 da Lei nº 11.101/2005

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de desmutualização e sua importância nas bolsas de valores
- Identifique a diferença entre associação civil sem fins lucrativos e empresa empresária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direito Empresarial", "legal_refs": ["Art. 102 da Lei nº 11.101/2005"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T03:26:24.226202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=106", "doc_key": "86ce18900735cb49d6d4173fd7b413e9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '4cd4080d2609a3286c6a9da83ca9a6b7305b02611d83f96319fd13fc8eafa1de'),
  ('cpiuris2025::185283b955de74b93c615fa029888f85', 'doutrina', 'cp_iuris', 'Direito Empresarial — Abertura de Capital e Mercado de Capitais', '## Abertura de Capital e Mercado de Capitais

A abertura de capital é um importante instrumento para as sociedades anônimas captar recursos, sem a necessidade de intermediários financeiros. É um mercado sensível, sujeito a regulação estatal e restrito às sociedades anônimas.

### Conceitos
- **Mercado de Balcão**: Operações feitas fora da bolsa de valores
- **Abertura de Capital**: Mecanismo de autofinanciamento das sociedades anônimas
- **Initial Public Offering (IPO)**: Operação de captação de recursos pela abertura do mercado de capitais
- **Mercado de Capitais**: Mercado onde as empresas emitem títulos para arrecadar recursos, sem a necessidade de intermediários financeiros
- **Poupança Popular**: Investimento direto na empresa, sem a necessidade de intermediários financeiros

### Referências legais
- Art. 142 da Lei 11.101/2005
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo do mercado de capitais

### Dicas de prova
- Diferenciar entre mercado de crédito e mercado de capitais
- Entender a importância da abertura de capital para as sociedades anônimas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito Empresarial", "legal_refs": ["Art. 142 da Lei 11.101/2005", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo do mercado de capitais"], "confidence": 0.8, "extracted_at": "2026-05-27T03:27:11.123278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=107", "doc_key": "185283b955de74b93c615fa029888f85"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ed541e3440be822721a625b37cb4002c483f9c9576c7a1c4ada7a341f40632ad'),
  ('cpiuris2025::98811cc49e4151bd905fc3a6249afe40', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade limitada do acionista', '## Responsabilidade limitada do acionista

O acionista responde pelo preço de emissão das ações que ele subscrever ou adquirir, mas com diferentes valores: nominal, patrimonial e de negociação.

### Conceitos
- **valor nominal**: obtido a partir da divisão do capital social pelo número de ações
- **valor patrimonial**: calcular com base no patrimônio líquido da sociedade dividido pelo número de ações
- **valor de negociação**: o preço que o titular da ação consegue quando a vende

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre os valores das ações: nominal, patrimonial e de negociação
- Entender que o acionista responde pelo preço de emissão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T03:27:33.518005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=107", "doc_key": "98811cc49e4151bd905fc3a6249afe40"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'bd377e29a2482e74773d6e0cec592be727016a9849cd9b35a981f62a31e5473b')
